-- Table: public.store_daily_performance
CREATE TABLE IF NOT EXISTS public.store_daily_performance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    performance_date date NOT NULL,
    player_id uuid NOT NULL,
    store_id uuid NOT NULL,
    store_slot_id uuid NOT NULL,
    slot_index integer NOT NULL,
    product_id text,
    product_name text,
    quality_level integer DEFAULT 0 NOT NULL,
    sold_quantity integer DEFAULT 0 NOT NULL,
    revenue numeric DEFAULT 0 NOT NULL,
    profit numeric DEFAULT 0 NOT NULL,
    sale_event_count integer DEFAULT 0 NOT NULL,
    last_sale_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT store_daily_performance_pkey PRIMARY KEY (id),
    CONSTRAINT store_daily_performance_performance_date_store_id_store_slo_key UNIQUE (performance_date, store_id, store_slot_id)
);

-- Table: public.store_slots
CREATE TABLE IF NOT EXISTS public.store_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    store_id uuid NOT NULL,
    slot_index integer NOT NULL,
    product_id text,
    quantity integer DEFAULT 0 NOT NULL,
    quality_level integer DEFAULT 0 NOT NULL,
    price numeric DEFAULT 0 NOT NULL,
    cost numeric DEFAULT 0 NOT NULL,
    boost_multiplier numeric(4,2) DEFAULT 1.00 NOT NULL,
    pending_sale numeric DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    capacity integer DEFAULT 0 NOT NULL,
    last_sale_processed_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    pending_quantity integer DEFAULT 0 NOT NULL,
    brand_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    CONSTRAINT store_slots_pkey PRIMARY KEY (id),
    CONSTRAINT store_slots_unique_slot_index UNIQUE (store_id, slot_index),
    CONSTRAINT store_slots_boost_multiplier_check CHECK (boost_multiplier >= 1.00 AND boost_multiplier <= 2.00),
    CONSTRAINT store_slots_capacity_check CHECK (capacity >= 0),
    CONSTRAINT store_slots_cost_check CHECK (cost >= 0::numeric),
    CONSTRAINT store_slots_empty_or_filled_check CHECK (product_id IS NULL AND quantity = 0 AND quality_level = 0 OR product_id IS NOT NULL AND quality_level >= 1 AND quality_level <= 5),
    CONSTRAINT store_slots_pending_sale_check CHECK (pending_sale >= 0::numeric),
    CONSTRAINT store_slots_price_check CHECK (price >= 0::numeric),
    CONSTRAINT store_slots_quality_level_check CHECK (quality_level >= 0 AND quality_level <= 5),
    CONSTRAINT store_slots_quantity_check CHECK (quantity >= 0),
    CONSTRAINT store_slots_slot_index_check CHECK (slot_index > 0)
);

-- Table: public.store_types
CREATE TABLE IF NOT EXISTS public.store_types (
    id uuid NOT NULL,
    name text,
    icon text,
    accepted_product_ids text,
    cost integer,
    required_level integer,
    created_at timestamp with time zone,
    base_slot_count integer,
    construction_time_minutes integer,
    max_slot_count integer,
    slot_capacity integer,
    CONSTRAINT store_types_pkey PRIMARY KEY (id)
);

-- Table: public.stores
CREATE TABLE IF NOT EXISTS public.stores (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_id uuid NOT NULL,
    store_type_id uuid NOT NULL,
    city_id uuid NOT NULL,
    name text NOT NULL,
    level integer DEFAULT 1 NOT NULL,
    current_slot_count integer DEFAULT 0 NOT NULL,
    max_slot_count integer DEFAULT 0 NOT NULL,
    slot_capacity integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT stores_pkey PRIMARY KEY (id),
    CONSTRAINT stores_level_check CHECK (level >= 1),
    CONSTRAINT stores_name_not_empty_check CHECK (length(TRIM(BOTH FROM name)) > 0),
    CONSTRAINT stores_slot_capacity_check CHECK (slot_capacity >= 0),
    CONSTRAINT stores_slot_count_check CHECK (current_slot_count >= 0 AND max_slot_count >= 0 AND current_slot_count <= max_slot_count)
);

-- Table: public.tender_bids
CREATE TABLE IF NOT EXISTS public.tender_bids (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tender_id uuid NOT NULL,
    player_id uuid NOT NULL,
    bid_amount numeric NOT NULL,
    bond_paid numeric NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    submitted_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT tender_bids_pkey PRIMARY KEY (id),
    CONSTRAINT tender_bids_unique_player_tender UNIQUE (player_id, tender_id),
    CONSTRAINT tender_bids_bid_amount_check CHECK (bid_amount > 0::numeric),
    CONSTRAINT tender_bids_bond_paid_check CHECK (bond_paid >= 0::numeric),
    CONSTRAINT tender_bids_status_check CHECK (status = ANY (ARRAY['active'::text, 'won'::text, 'lost'::text, 'cancelled'::text]))
);

-- Table: public.tender_deliveries
CREATE TABLE IF NOT EXISTS public.tender_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    player_tender_id uuid NOT NULL,
    player_id uuid NOT NULL,
    source_warehouse_id uuid NOT NULL,
    vehicle_id uuid,
    quantity integer NOT NULL,
    status text NOT NULL,
    same_city boolean DEFAULT true NOT NULL,
    started_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    finish_at timestamp with time zone,
    completed_at timestamp with time zone,
    cost numeric DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT tender_deliveries_pkey PRIMARY KEY (id),
    CONSTRAINT tender_deliveries_cost_check CHECK (cost >= 0::numeric),
    CONSTRAINT tender_deliveries_quantity_check CHECK (quantity > 0),
    CONSTRAINT tender_deliveries_status_check CHECK (status = ANY (ARRAY['instant_completed'::text, 'in_transit'::text, 'completed'::text, 'cancelled'::text, 'failed'::text, 'failed_late'::text]))
);

-- Table: public.tenders
CREATE TABLE IF NOT EXISTS public.tenders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    description text,
    city_id uuid NOT NULL,
    product_id text NOT NULL,
    quality_level integer NOT NULL,
    required_quantity integer NOT NULL,
    reward_cash numeric NOT NULL,
    bond_amount numeric NOT NULL,
    accept_until timestamp with time zone NOT NULL,
    delivery_duration_minutes integer NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    visibility text DEFAULT 'public'::text NOT NULL,
    min_player_level integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    award_type text DEFAULT 'lowest_bid'::text,
    CONSTRAINT tenders_pkey PRIMARY KEY (id),
    CONSTRAINT tenders_award_type_check CHECK (award_type = ANY (ARRAY['first_claim'::text, 'lowest_bid'::text])),
    CONSTRAINT tenders_bond_amount_check CHECK (bond_amount >= 0::numeric),
    CONSTRAINT tenders_delivery_duration_minutes_check CHECK (delivery_duration_minutes > 0),
    CONSTRAINT tenders_min_player_level_check CHECK (min_player_level >= 1),
    CONSTRAINT tenders_quality_level_check CHECK (quality_level >= 1),
    CONSTRAINT tenders_required_quantity_check CHECK (required_quantity > 0),
    CONSTRAINT tenders_reward_cash_check CHECK (reward_cash >= 0::numeric),
    CONSTRAINT tenders_status_check CHECK (status = ANY (ARRAY['open'::text, 'closed'::text, 'expired'::text, 'disabled'::text]))
);

-- Table: public.warehouse_slots
CREATE TABLE IF NOT EXISTS public.warehouse_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    warehouse_id uuid NOT NULL,
    slot_index integer NOT NULL,
    product_id text,
    quality_level integer DEFAULT 0 NOT NULL,
    quantity integer DEFAULT 0 NOT NULL,
    cost numeric DEFAULT 0 NOT NULL,
    is_available_for_sale boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    price numeric DEFAULT 0 NOT NULL,
    brand_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    pending_quantity integer DEFAULT 0 NOT NULL,
    CONSTRAINT warehouse_slots_pkey PRIMARY KEY (id),
    CONSTRAINT warehouse_slots_unique_slot_index UNIQUE (warehouse_id, slot_index),
    CONSTRAINT warehouse_slots_cost_check CHECK (cost >= 0::numeric),
    CONSTRAINT warehouse_slots_empty_or_filled_check CHECK (product_id IS NULL AND quantity = 0 AND quality_level = 0 OR product_id IS NOT NULL AND quality_level >= 1 AND quality_level <= 5),
    CONSTRAINT warehouse_slots_price_check CHECK (price >= 0::numeric),
    CONSTRAINT warehouse_slots_quality_level_check CHECK (quality_level >= 0 AND quality_level <= 5),
    CONSTRAINT warehouse_slots_quantity_check CHECK (quantity >= 0),
    CONSTRAINT warehouse_slots_slot_index_check CHECK (slot_index > 0)
);

-- Table: public.warehouse_types
CREATE TABLE IF NOT EXISTS public.warehouse_types (
    id uuid NOT NULL,
    name text,
    icon text,
    accepted_production_units text,
