-- Function: accept_tender
CREATE OR REPLACE FUNCTION public.accept_tender(p_tender_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_player public.players%rowtype;
  v_tender public.tenders%rowtype;
  v_player_tender_id uuid;
  v_deadline_at timestamptz;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  perform public.ensure_open_tenders();

  select * into v_player from public.players where id = v_player_id for update;
  if not found then
    return jsonb_build_object('success', false, 'message', 'Oyuncu bulunamadi.');
  end if;

  select * into v_tender from public.tenders where id = p_tender_id for update;
  if not found then
    return jsonb_build_object('success', false, 'message', 'Ihale bulunamadi.');
  end if;

  if v_tender.award_type <> 'first_claim' then
    return jsonb_build_object('success', false, 'message', 'Bu ihale teklif usulu ile calisiyor.');
  end if;

  if v_tender.status <> 'open' then
    return jsonb_build_object('success', false, 'message', 'Ihale artik uygun degil.');
  end if;

  if v_tender.accept_until <= timezone('utc'::text, now()) then
    return jsonb_build_object('success', false, 'message', 'Ihaleye katilim suresi doldu.');
  end if;

  if coalesce(v_player.level, 1) < v_tender.min_player_level then
    return jsonb_build_object('success', false, 'message', 'Oyuncu seviyesi yeterli degil.');
  end if;

  if exists (
    select 1 from public.player_tenders pt
    where pt.player_id = v_player_id and pt.tender_id = v_tender.id
  ) then
    return jsonb_build_object('success', false, 'message', 'Bu ihaleye zaten katildin.');
  end if;

  if coalesce(v_player.level, 1) < v_tender.min_player_level or coalesce(v_player.cash, 0) < v_tender.bond_amount then
    return jsonb_build_object('success', false, 'message', 'Teminat icin yeterli nakit yok.');
  end if;

  update public.players set cash = cash - v_tender.bond_amount where id = v_player_id;

  v_deadline_at := timezone('utc'::text, now()) + make_interval(mins => v_tender.delivery_duration_minutes);

  insert into public.player_tenders (
    player_id, tender_id, accepted_at, deadline_at, bond_paid, required_quantity,
    delivered_quantity, reward_cash, product_id, quality_level, city_id, status
  )
  values (
    v_player_id, v_tender.id, timezone('utc'::text, now()), v_deadline_at, v_tender.bond_amount,
    v_tender.required_quantity, 0, v_tender.reward_cash, v_tender.product_id, v_tender.quality_level,
    v_tender.city_id, 'active'
  )
  returning id into v_player_tender_id;

  update public.tenders set status = 'closed', updated_at = timezone('utc'::text, now()) where id = v_tender.id;

  perform public.log_player_cash_change(
    v_player_id,
    -v_tender.bond_amount,
    v_player.cash,
    'tender_bond_paid',
    format('Ihale teminati odendi. Tender: %s', v_tender.id),
    v_player_tender_id,
    'player_tender'
  );

  return jsonb_build_object(
    'success', true,
    'player_tender_id', v_player_tender_id,
    'deadline_at', v_deadline_at,
    'message', 'Ihale kabul edildi ve sana atandi.',
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id)
    )
  );
end;
$function$;

-- Function: add_product_to_warehouse
CREATE OR REPLACE FUNCTION public.add_product_to_warehouse(p_player_id uuid, p_warehouse_id uuid, p_product_id text, p_quality_level integer, p_quantity integer, p_cost numeric, p_transport_cost numeric DEFAULT 0, p_release_reserved_capacity boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_warehouse record;
  v_product record;
  v_existing_slot record;

  v_used_capacity numeric := 0;
  v_incoming_capacity numeric := 0;
  v_available_capacity numeric := 0;

  v_new_slot_index integer;
  v_slot_id uuid;

  v_new_quantity integer;
  v_new_cost numeric;

  v_reserved_before numeric := 0;
  v_reserved_after numeric := 0;
  v_released_reserved_capacity numeric := 0;

  v_transport_unit_cost numeric := 0;
  v_effective_unit_cost numeric := 0;
begin
  if p_product_id is null or length(trim(p_product_id)) = 0 then
    raise exception 'Ürün id boş olamaz.';
  end if;

  if p_quality_level < 1 or p_quality_level > 5 then
    raise exception 'Kalite seviyesi 1 ile 5 arasında olmalıdır.';
  end if;

  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Eklenecek miktar 0''dan büyük olmalıdır.';
  end if;

  if p_cost is null or p_cost < 0 then
    raise exception 'Ürün maliyeti 0 veya daha büyük olmalıdır.';
  end if;

  if p_transport_cost is null or p_transport_cost < 0 then
    raise exception 'Nakliye maliyeti 0 veya daha büyük olmalıdır.';
  end if;

  v_transport_unit_cost := p_transport_cost / p_quantity;
  v_effective_unit_cost := p_cost + v_transport_unit_cost;

  -- Depoyu kilitle
  select *
  into v_warehouse
  from public.warehouses
  where id = p_warehouse_id
    and player_id = p_player_id
  for update;

  if not found then
    raise exception 'Depo bulunamadı veya oyuncuya ait değil.';
  end if;

  -- Ürün bilgisi
  select *
  into v_product
  from public.products
  where id = p_product_id;

  if not found then
    raise exception 'Ürün bulunamadı.';
  end if;

  if v_product.birim_hacim is null or v_product.birim_hacim <= 0 then
    raise exception 'Ürünün birim_hacim değeri geçerli değil.';
  end if;

  v_incoming_capacity := p_quantity * v_product.birim_hacim;
  v_reserved_before := coalesce(v_warehouse.reserved_capacity, 0);

  -- Mevcut kullanılan kapasite
  select coalesce(sum(ws.quantity * p.birim_hacim), 0)
  into v_used_capacity
  from public.warehouse_slots ws
  join public.products p on p.id = ws.product_id
  where ws.warehouse_id = p_warehouse_id;

  -- Rezervsiz eklemede boş kapasite kontrolü
  if p_release_reserved_capacity = false then
    v_available_capacity :=
      coalesce(v_warehouse.capacity, 0)
      - v_used_capacity
      - v_reserved_before;

    if v_incoming_capacity > v_available_capacity then
      raise exception 'Depo kapasitesi yetersiz. Boş kapasite: %, Eklenecek hacim: %',
        v_available_capacity,
        v_incoming_capacity;
    end if;
  else
    -- Transfer tamamlanıyorsa, alan önceden rezerve edilmiş kabul edilir
    if v_used_capacity + v_incoming_capacity > coalesce(v_warehouse.capacity, 0) then
      raise exception 'Depo kapasitesi yetersiz. Kullanılan hacim: %, Eklenecek hacim: %, Kapasite: %',
        v_used_capacity,
        v_incoming_capacity,
        v_warehouse.capacity;
    end if;
  end if;

  -- Aynı ürün + kalite slotu var mı?
  select *
  into v_existing_slot
  from public.warehouse_slots
  where warehouse_id = p_warehouse_id
    and product_id = p_product_id
    and quality_level = p_quality_level
  for update;

  if found then
    v_slot_id := v_existing_slot.id;
    v_new_quantity := v_existing_slot.quantity + p_quantity;

    v_new_cost :=
      (
        (v_existing_slot.quantity * v_existing_slot.cost)
        +
        (p_quantity * v_effective_unit_cost)
      )
      / v_new_quantity;

    update public.warehouse_slots
    set
      quantity = v_new_quantity,
      cost = v_new_cost,
      updated_at = timezone('utc'::text, now())
    where id = v_existing_slot.id;

  else
    select coalesce(max(slot_index), 0) + 1
    into v_new_slot_index
    from public.warehouse_slots
    where warehouse_id = p_warehouse_id;

    insert into public.warehouse_slots (
      warehouse_id,
      slot_index,
      product_id,
      quality_level,
      quantity,
      cost,
      is_available_for_sale
    )
    values (
      p_warehouse_id,
      v_new_slot_index,
      p_product_id,
      p_quality_level,
      p_quantity,
      v_effective_unit_cost,
      false
    )
    returning id into v_slot_id;

    v_new_quantity := p_quantity;
    v_new_cost := v_effective_unit_cost;
  end if;

  -- Transferden geldiyse rezerv kapasiteyi düş
  if p_release_reserved_capacity = true then
    v_released_reserved_capacity := least(v_reserved_before, v_incoming_capacity);
    v_reserved_after := greatest(v_reserved_before - v_incoming_capacity, 0);

    update public.warehouses
    set
      reserved_capacity = v_reserved_after,
      updated_at = timezone('utc'::text, now())
    where id = p_warehouse_id;
  else
    v_released_reserved_capacity := 0;
    v_reserved_after := v_reserved_before;

    update public.warehouses
    set updated_at = timezone('utc'::text, now())
    where id = p_warehouse_id;
  end if;

  return jsonb_build_object(
    'success', true,
    'warehouse_id', p_warehouse_id,
    'warehouse_slot_id', v_slot_id,
    'product_id', p_product_id,
    'quality_level', p_quality_level,
    'added_quantity', p_quantity,
    'base_unit_cost', p_cost,
    'transport_cost', p_transport_cost,
    'transport_unit_cost', v_transport_unit_cost,
    'effective_unit_cost', v_effective_unit_cost,
    'unit_volume', v_product.birim_hacim,
    'added_capacity', v_incoming_capacity,
    'quantity_after', v_new_quantity,
    'cost_after', v_new_cost,
    'reserved_capacity_before', v_reserved_before,
    'released_reserved_capacity', v_released_reserved_capacity,
    'reserved_capacity_after', v_reserved_after
  );
end;
$function$;

-- Function: add_product_to_warehouse_with_brand
CREATE OR REPLACE FUNCTION public.add_product_to_warehouse_with_brand(p_player_id uuid, p_warehouse_id uuid, p_product_id text, p_quality_level integer, p_brand_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid, p_quantity integer DEFAULT 0, p_cost numeric DEFAULT 0, p_transport_cost numeric DEFAULT 0, p_release_reserved_capacity boolean DEFAULT false, p_preferred_slot_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_default_brand uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_now timestamptz := timezone('utc'::text, now());
  v_warehouse warehouses%rowtype;
  v_product products%rowtype;
  v_target_slot warehouse_slots%rowtype;
  v_empty_slot warehouse_slots%rowtype;
  v_target_slot_id uuid;
  v_next_slot_index integer := 1;
  v_used_capacity numeric := 0;
  v_required_capacity numeric := 0;
  v_reserved_before numeric := 0;
  v_reserved_after numeric := 0;
  v_released_reserved_capacity numeric := 0;
  v_new_quantity integer := 0;
  v_new_cost numeric := 0;
  v_pending_to_release integer := 0;
  v_incoming_total_cost numeric := 0;
  v_incoming_unit_cost numeric := 0;
begin
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Eklenecek miktar 0 dan buyuk olmalidir.';
  end if;
  if p_quality_level is null or p_quality_level < 1 or p_quality_level > 5 then
    raise exception 'Kalite seviyesi 1 ile 5 arasinda olmalidir.';
  end if;
  select * into v_warehouse from public.warehouses where id = p_warehouse_id for update;
  if not found then raise exception 'Hedef depo bulunamadi.'; end if;
  if v_warehouse.player_id <> p_player_id then raise exception 'Bu depo oyuncuya ait degil.'; end if;
  select * into v_product from public.products where id = p_product_id;
  if not found then raise exception 'Urun bulunamadi.'; end if;
  v_required_capacity := p_quantity * coalesce(v_product.birim_hacim, 0);
  v_incoming_total_cost := (p_quantity * coalesce(p_cost, 0)) + coalesce(p_transport_cost, 0);
  v_incoming_unit_cost := case when p_quantity <= 0 then coalesce(p_cost, 0) else round(v_incoming_total_cost / p_quantity::numeric, 4) end;
  select coalesce(sum((ws.quantity + coalesce(ws.pending_quantity, 0)) * coalesce(p.birim_hacim, 0)), 0)
  into v_used_capacity
  from public.warehouse_slots ws
  left join public.products p on p.id = ws.product_id
  where ws.warehouse_id = p_warehouse_id;
  v_reserved_before := coalesce(v_warehouse.reserved_capacity, 0);
  if p_preferred_slot_id is not null then
    select * into v_target_slot from public.warehouse_slots where id = p_preferred_slot_id and warehouse_id = p_warehouse_id for update;
  end if;
  if not found or v_target_slot.product_id is distinct from p_product_id or coalesce(v_target_slot.quality_level, 0) <> p_quality_level or coalesce(v_target_slot.brand_id, v_default_brand) <> coalesce(p_brand_id, v_default_brand) then
    select * into v_target_slot
    from public.warehouse_slots
    where warehouse_id = p_warehouse_id and product_id = p_product_id and quality_level = p_quality_level and coalesce(brand_id, v_default_brand) = coalesce(p_brand_id, v_default_brand)
    order by slot_index limit 1 for update;
  end if;
  if found then v_pending_to_release := least(coalesce(v_target_slot.pending_quantity, 0), p_quantity); else v_pending_to_release := 0; end if;
  if v_pending_to_release > 0 then v_used_capacity := greatest(v_used_capacity - (v_pending_to_release * coalesce(v_product.birim_hacim, 0)), 0); end if;
  if p_release_reserved_capacity = false then
    if v_used_capacity + v_reserved_before + v_required_capacity > coalesce(v_warehouse.capacity, 0) then raise exception 'Depoda yeterli kapasite yok.'; end if;
  end if;
  if found then
    v_target_slot_id := v_target_slot.id;
    v_new_quantity := coalesce(v_target_slot.quantity, 0) + p_quantity;
    v_new_cost := case
      when v_new_quantity <= 0 then 0
      when coalesce(v_target_slot.quantity, 0) <= 0 then v_incoming_unit_cost
      else round(((coalesce(v_target_slot.quantity, 0) * coalesce(v_target_slot.cost, 0)) + v_incoming_total_cost) / v_new_quantity::numeric, 4)
    end;
    update public.warehouse_slots
    set product_id = p_product_id, quality_level = p_quality_level, brand_id = coalesce(p_brand_id, v_default_brand), quantity = v_new_quantity,
        pending_quantity = greatest(coalesce(v_target_slot.pending_quantity, 0) - v_pending_to_release, 0), cost = v_new_cost, updated_at = v_now
    where id = v_target_slot_id;
  else
    select * into v_empty_slot
    from public.warehouse_slots
    where warehouse_id = p_warehouse_id and product_id is null and quantity = 0 and coalesce(pending_quantity, 0) = 0 and quality_level = 0
    order by slot_index limit 1 for update;
    if found then
      v_target_slot_id := v_empty_slot.id;
      update public.warehouse_slots
      set product_id = p_product_id, quality_level = p_quality_level, brand_id = coalesce(p_brand_id, v_default_brand), quantity = p_quantity,
          pending_quantity = 0, cost = v_incoming_unit_cost, is_available_for_sale = false, updated_at = v_now
      where id = v_target_slot_id;
    else
      select coalesce(max(slot_index), 0) + 1 into v_next_slot_index from public.warehouse_slots where warehouse_id = p_warehouse_id;
      insert into public.warehouse_slots (
        warehouse_id, slot_index, brand_id, product_id, quality_level, quantity, pending_quantity, cost, is_available_for_sale, created_at, updated_at, price
      ) values (
        p_warehouse_id, v_next_slot_index, coalesce(p_brand_id, v_default_brand), p_product_id, p_quality_level, p_quantity, 0, v_incoming_unit_cost, false, v_now, v_now, 0
      ) returning id into v_target_slot_id;
    end if;
  end if;
  if p_release_reserved_capacity = true then
    v_released_reserved_capacity := least(v_reserved_before, v_required_capacity);
    v_reserved_after := greatest(v_reserved_before - v_required_capacity, 0);
    update public.warehouses set reserved_capacity = v_reserved_after, updated_at = v_now where id = p_warehouse_id;
  else
    v_released_reserved_capacity := 0;
    v_reserved_after := v_reserved_before;
  end if;
  return jsonb_build_object(
    'success', true,
    'warehouse_id', p_warehouse_id,
    'warehouse_slot_id', v_target_slot_id,
    'product_id', p_product_id,
    'quality_level', p_quality_level,
    'brand_id', coalesce(p_brand_id, v_default_brand),
    'quantity', p_quantity,
    'unit_cost', v_incoming_unit_cost,
    'transport_cost', coalesce(p_transport_cost, 0),
    'released_reserved_capacity', v_released_reserved_capacity,
    'reserved_capacity_after', v_reserved_after
  );
end;
$function$;

-- Function: add_production_slot
CREATE OR REPLACE FUNCTION public.add_production_slot(p_player_id uuid, p_owner_kind text, p_owner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner record;
  v_new_slot_index integer;
  v_slot_id uuid;
  v_current_slot_count integer;
  v_max_slot_count integer;
  v_input_capacity_gain integer := 0;
  v_output_capacity_gain integer := 0;
  v_capacity_multiplier numeric := 1;
begin
  if p_owner_kind not in ('field', 'farm') then
    raise exception 'Invalid owner_kind. Only field or farm is allowed: %', p_owner_kind;
  end if;

  if p_owner_kind = 'field' then
    select *
    into v_owner
    from public.fields
    where id = p_owner_id
      and player_id = p_player_id
    for update;

    if not found then
      raise exception 'Field not found or does not belong to player.';
    end if;

    v_current_slot_count := v_owner.current_slot_count;
    v_max_slot_count := v_owner.max_slot_count;

    if v_current_slot_count >= v_max_slot_count then
      raise exception 'Maximum production slot count reached for field. Current: %, Max: %',
        v_current_slot_count,
        v_max_slot_count;
    end if;

  elsif p_owner_kind = 'farm' then
    select
      f.*,
      ft.input_capacity as base_input_capacity,
      ft.output_capacity as base_output_capacity
    into v_owner
    from public.farms f
    join public.farm_types ft on ft.id = f.farm_type_id
    where f.id = p_owner_id
      and f.player_id = p_player_id
    for update;

    if not found then
      raise exception 'Farm not found or does not belong to player.';
    end if;

    v_current_slot_count := v_owner.current_slot_count;
    v_max_slot_count := v_owner.max_slot_count;

    if v_current_slot_count >= v_max_slot_count then
      raise exception 'Maximum production slot count reached for farm. Current: %, Max: %',
        v_current_slot_count,
        v_max_slot_count;
    end if;

    v_capacity_multiplier := power(2::numeric, greatest(coalesce(v_owner.level, 1) - 1, 0));
    v_input_capacity_gain := ceil(((coalesce(v_owner.base_input_capacity, 0)::numeric / greatest(coalesce(v_owner.max_slot_count, 1), 1)) * v_capacity_multiplier))::integer;
    v_output_capacity_gain := ceil(((coalesce(v_owner.base_output_capacity, 0)::numeric / greatest(coalesce(v_owner.max_slot_count, 1), 1)) * v_capacity_multiplier))::integer;
  end if;

  select coalesce(max(slot_index), 0) + 1
  into v_new_slot_index
  from public.production_slots
  where owner_kind = p_owner_kind
    and owner_id = p_owner_id;

  insert into public.production_slots (
    owner_kind,
    owner_id,
    slot_index,
    product_id,
    quality_level,
    boost_multiplier,
    is_active
  )
  values (
    p_owner_kind,
    p_owner_id,
    v_new_slot_index,
    null,
    0,
    1.00,
    true
  )
  returning id into v_slot_id;

  if p_owner_kind = 'field' then
    update public.fields
    set
      current_slot_count = current_slot_count + 1,
      updated_at = timezone('utc'::text, now())
    where id = p_owner_id;
  elsif p_owner_kind = 'farm' then
    update public.farms
    set
      current_slot_count = current_slot_count + 1,
      input_capacity = input_capacity + v_input_capacity_gain,
      output_capacity = output_capacity + v_output_capacity_gain,
      updated_at = timezone('utc'::text, now())
    where id = p_owner_id;
  end if;

  return jsonb_build_object(
    'success', true,
    'production_slot_id', v_slot_id,
    'owner_kind', p_owner_kind,
    'owner_id', p_owner_id,
    'slot_index', v_new_slot_index,
    'current_slot_count', v_current_slot_count + 1,
    'max_slot_count', v_max_slot_count,
    'input_capacity_gain', v_input_capacity_gain,
    'output_capacity_gain', v_output_capacity_gain,
    'slot', jsonb_build_object(
      'id', v_slot_id,
      'owner_kind', p_owner_kind,
      'owner_id', p_owner_id,
      'slot_index', v_new_slot_index,
      'product_id', null,
      'brand_id', '00000000-0000-0000-0000-000000000000',
      'quality_level', 0,
      'boost_multiplier', 1.00,
      'is_active', true,
      'product', null
    )
  );
end;
$function$;

-- Function: add_store_slot
CREATE OR REPLACE FUNCTION public.add_store_slot(p_player_id uuid, p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_store record;
  v_new_slot_index integer;
  v_slot_id uuid;
  v_boost_multiplier numeric := 1.00;
begin
  select *
  into v_store
  from public.stores
  where id = p_store_id
    and player_id = p_player_id
  for update;

  if not found then
    raise exception 'Magaza bulunamadi veya oyuncuya ait degil.';
  end if;

  if v_store.current_slot_count >= v_store.max_slot_count then
    raise exception 'Magazada acilabilecek maksimum slot sayisina ulasildi. Mevcut: %, Maksimum: %',
      v_store.current_slot_count,
      v_store.max_slot_count;
  end if;

  select coalesce(max(slot_index), 0) + 1
  into v_new_slot_index
  from public.store_slots
  where store_id = p_store_id;

  select coalesce(bb.multiplier, 1.00)
  into v_boost_multiplier
  from public.building_boosts bb
  where bb.player_id = p_player_id
    and bb.building_kind = 'store'
    and bb.entity_id = p_store_id
    and bb.status = 'in_progress'
    and coalesce(bb.finish_at, timezone('utc', now())) > timezone('utc', now())
  order by bb.created_at desc
  limit 1;

  insert into public.store_slots (
    store_id,
    slot_index,
    product_id,
    quantity,
    quality_level,
    price,
    cost,
    capacity,
    boost_multiplier,
    pending_sale,
    is_active
  )
  values (
    p_store_id,
    v_new_slot_index,
    null,
    0,
    0,
    0,
    0,
    coalesce(v_store.slot_capacity, 0),
    coalesce(v_boost_multiplier, 1.00),
    0,
    true
  )
  returning id into v_slot_id;

  update public.stores
  set
    current_slot_count = current_slot_count + 1,
    updated_at = timezone('utc', now())
  where id = p_store_id;

  return jsonb_build_object(
    'success', true,
    'store_id', p_store_id,
    'slot_id', v_slot_id,
    'slot_index', v_new_slot_index,
    'capacity', coalesce(v_store.slot_capacity, 0),
    'current_slot_count', v_store.current_slot_count + 1,
    'max_slot_count', v_store.max_slot_count
  );
end;
$function$;

-- Function: apply_production_brand_selection
CREATE OR REPLACE FUNCTION public.apply_production_brand_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_default_brand uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_player_id uuid;
begin
  if coalesce(new.product_id, '') = '' then
    new.brand_id := v_default_brand;
    return new;
  end if;

  if tg_table_name = 'production_slots' then
    if new.owner_kind = 'field' then
      select f.player_id
      into v_player_id
      from public.fields f
      where f.id = new.owner_id;
    elsif new.owner_kind = 'farm' then
      select fa.player_id
      into v_player_id
      from public.farms fa
      where fa.id = new.owner_id;
    else
      v_player_id := null;
    end if;
  else
    v_player_id := new.player_id;
  end if;

  new.brand_id := public.resolve_player_product_brand(v_player_id, new.product_id);
  return new;
end;
$function$;

-- Function: apply_production_inventory_brand
CREATE OR REPLACE FUNCTION public.apply_production_inventory_brand()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.brand_id := public.resolve_production_inventory_brand(
    new.owner_kind,
    new.owner_id,
    new.inventory_type,
    new.product_id,
    new.quality_level
  );
  return new;
end;
$function$;

-- Function: assign_production_slot_product
CREATE OR REPLACE FUNCTION public.assign_production_slot_product(p_player_id uuid, p_production_slot_id uuid, p_product_id text, p_quality_level integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot public.production_slots%rowtype;
  v_product public.products%rowtype;

  v_owner_player_id uuid;
  v_owner_type_id uuid;
  v_accepted_product_ids text;
  v_product_unit text;

  v_max_quality integer;
  v_duplicate_slot_index integer;

  v_created_input_count integer := 0;
  v_created_output_count integer := 0;

  v_hammadde_1_id text;
  v_hammadde_2_id text;
  v_hammadde_3_id text;

  v_hammadde_1_miktar numeric;
  v_hammadde_2_miktar numeric;
  v_hammadde_3_miktar numeric;

  v_input_quality_level integer;
  v_inventory_id uuid;
  v_output_inventory_id uuid;
begin
  perform pg_advisory_xact_lock(hashtext('field_farm_production_lock'));

  if p_quality_level is null or p_quality_level < 1 or p_quality_level > 5 then
    raise exception 'Kalite seviyesi 1 ile 5 arasinda olmalidir.';
  end if;

  v_input_quality_level := greatest(1, least(coalesce(p_quality_level, 1), 5) - 1);

  select *
  into v_slot
  from public.production_slots
  where id = p_production_slot_id
  for update;

  if not found then
    raise exception 'Uretim slotu bulunamadi.';
  end if;

  if coalesce(v_slot.product_id, '') <> '' and coalesce(v_slot.quality_level, 0) > 0 then
    raise exception 'Bu slotta zaten urun var. Urun degistirme akisini kullan.';
  end if;

  if v_slot.owner_kind not in ('field', 'farm') then
    raise exception 'Gecersiz production slot owner_kind: %', v_slot.owner_kind;
  end if;

  if v_slot.owner_kind = 'field' then
    select f.player_id, f.field_type_id, ft.accepted_product_ids
    into v_owner_player_id, v_owner_type_id, v_accepted_product_ids
    from public.fields f
    join public.field_types ft on ft.id = f.field_type_id
    where f.id = v_slot.owner_id;
  elsif v_slot.owner_kind = 'farm' then
    select fa.player_id, fa.farm_type_id, ft.accepted_product_ids
    into v_owner_player_id, v_owner_type_id, v_accepted_product_ids
    from public.farms fa
    join public.farm_types ft on ft.id = fa.farm_type_id
    where fa.id = v_slot.owner_id;
  end if;

  if v_owner_player_id is null then
    raise exception 'Uretim slotunun bagli oldugu yapi bulunamadi.';
  end if;

  if v_owner_player_id <> p_player_id then
    raise exception 'Bu uretim slotu oyuncuya ait degil.';
  end if;

  select *
  into v_product
  from public.products
  where id = p_product_id;

  if not found then
    raise exception 'Urun bulunamadi: %', p_product_id;
  end if;

  v_product_unit := lower(trim(coalesce(v_product.uretim_birimi, '')));

  -- 'farm' is Tarla
  if v_slot.owner_kind = 'farm'
     and v_product_unit not in ('tarla', 'farm') then
    raise exception 'Bu urun tarla urunu degil: %', p_product_id;
  end if;

  -- 'field' is Çiftlik
  if v_slot.owner_kind = 'field'
     and v_product_unit not in ('ciftlik', 'çiftlik', 'field') then
    raise exception 'Bu urun ciftlik urunu degil: %', p_product_id;
  end if;

  if v_accepted_product_ids is null
     or not (p_product_id = any(regexp_split_to_array(v_accepted_product_ids, '\s*,\s*'))) then
    raise exception 'Bu yapi turu bu urunu uretemez: %', p_product_id;
  end if;

  select ps.slot_index
  into v_duplicate_slot_index
  from public.production_slots ps
  where ps.owner_kind = v_slot.owner_kind
    and ps.owner_id = v_slot.owner_id
    and ps.id <> v_slot.id
    and ps.product_id = p_product_id
  limit 1;

  if v_duplicate_slot_index is not null then
    raise exception 'Ayni uretim biriminde ayni urun yalnizca tek slotta uretilebilir. Urun zaten slot % uzerinde ayarli.', v_duplicate_slot_index;
  end if;

  select coalesce(max(max_quality_level), 1)
  into v_max_quality
  from public.player_product_quality_levels
  where player_id = p_player_id
    and product_id = p_product_id;

  if v_max_quality is null then
    v_max_quality := 1;
  end if;

  if p_quality_level > v_max_quality then
    raise exception 'Oyuncu bu urun icin kalite % seviyesine ulasmadi. Mevcut maksimum kalite: %', p_quality_level, v_max_quality;
  end if;

  update public.production_slots
  set product_id = p_product_id,
      quality_level = p_quality_level,
      brand_id = public.resolve_player_product_brand(v_owner_player_id, p_product_id),
      updated_at = timezone('utc'::text, now()),
      last_production_at = timezone('utc'::text, now())
  where id = p_production_slot_id;

  v_hammadde_1_id := nullif(v_product.hammadde_1_id, '');
  v_hammadde_2_id := nullif(v_product.hammadde_2_id, '');
  v_hammadde_3_id := nullif(v_product.hammadde_3_id, '');

  v_hammadde_1_miktar := coalesce(v_product.hammadde_1_miktar, 0);
  v_hammadde_2_miktar := coalesce(v_product.hammadde_2_miktar, 0);
  v_hammadde_3_miktar := coalesce(v_product.hammadde_3_miktar, 0);

  if v_hammadde_1_id is not null and v_hammadde_1_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_1_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_1_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  if v_hammadde_2_id is not null and v_hammadde_2_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_2_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_2_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  if v_hammadde_3_id is not null and v_hammadde_3_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_3_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_3_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  select id into v_output_inventory_id
  from public.production_inventory
  where owner_kind = v_slot.owner_kind
    and owner_id = v_slot.owner_id
    and inventory_type = 'output'
    and product_id = p_product_id
    and quality_level = p_quality_level
    and brand_id = public.resolve_player_product_brand(v_owner_player_id, p_product_id);

  if not found then
    insert into public.production_inventory (
      owner_kind, owner_id, inventory_type, product_id, quality_level, brand_id, quantity, pending_quantity, cost
    ) values (
      v_slot.owner_kind, v_slot.owner_id, 'output', p_product_id, p_quality_level, public.resolve_player_product_brand(v_owner_player_id, p_product_id), 0, 0, 0
    ) returning id into v_output_inventory_id;
    v_created_output_count := 1;
  end if;

  return jsonb_build_object(
    'success', true,
    'mode', 'assign',
    'production_slot_id', p_production_slot_id,
    'owner_kind', v_slot.owner_kind,
    'owner_id', v_slot.owner_id,
    'owner_type_id', v_owner_type_id,
    'product_id', p_product_id,
    'product_name', v_product.urun_adi,
    'quality_level', p_quality_level,
    'input_quality_level', v_input_quality_level,
    'player_max_quality_level', v_max_quality,
    'created_input_count', v_created_input_count,
    'created_output_count', v_created_output_count,
    'output_inventory_id', v_output_inventory_id,
    'slots', coalesce((
      select jsonb_agg(
        (to_jsonb(ps) - 'boost_multiplier') || jsonb_build_object(
          'boost_multiplier',
          coalesce((
            select bb.multiplier
            from public.building_boosts bb
            where bb.player_id = auth.uid()
              and bb.building_kind = v_slot.owner_kind
              and bb.entity_id = v_slot.owner_id
              and bb.status = 'in_progress'
              and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
            order by bb.started_at desc
            limit 1
          ), 1.00),
          'product',
          case when p.id is null then null else to_jsonb(p) end
        )
        order by ps.slot_index
      )
      from public.production_slots ps
      left join public.products p on p.id = ps.product_id
      where ps.owner_kind = v_slot.owner_kind
        and ps.owner_id = v_slot.owner_id
    ), '[]'::jsonb),
    'inventories', coalesce((
      select jsonb_agg(
        to_jsonb(pi) || jsonb_build_object(
          'product',
          case when p.id is null then null else to_jsonb(p) end
        )
        order by pi.id
      )
      from public.production_inventory pi
      left join public.products p on p.id = pi.product_id
      where pi.owner_kind = v_slot.owner_kind
        and pi.owner_id = v_slot.owner_id
    ), '[]'::jsonb),
    'changed', jsonb_build_object(
      'player', public.get_player_profile(p_player_id)
    )
  );
end;
$function$;

-- Function: bootstrap_game_session
CREATE OR REPLACE FUNCTION public.bootstrap_game_session(p_city_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_player jsonb;
  v_logistics_state jsonb;
  v_production_result jsonb;
  v_transfer_result jsonb;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  perform public.ensure_player_record_exists(v_player_id, p_city_id);
  
  if p_city_id is not null then
    perform public.set_player_headquarters_city(p_city_id);
  end if;

  -- 1. Tamamlanma süresi dolmuş transferleri ve ihale teslimatlarını anında tamamla
  v_transfer_result := public.complete_due_market_transfers(v_player_id, 100);
  perform public.process_tender_deliveries(v_player_id);
  perform public.process_player_tenders(v_player_id);

  -- 2. Liderlik ve şirket değerini güncelle
  perform public.refresh_player_leaderboard_stats(v_player_id);

  -- 3. Üretimleri işle
  v_production_result := public.process_player_production_entry(v_player_id);
  v_player := public.get_player_profile(v_player_id);
  v_logistics_state := public.get_logistics_entry_state();

  return jsonb_build_object(
    'success', true,
    'player', v_player,
    'logistics_entry_state', v_logistics_state,
    'completed_transfers', v_transfer_result,
    'completed_due_building_boosts', v_production_result -> 'completed_due_building_boosts',
    'completed_due_building_upgrades', v_production_result -> 'completed_due_building_upgrades',
    'processed_production', v_production_result
  );
end;
$function$;

-- Function: build_level_progress_payload
CREATE OR REPLACE FUNCTION public.build_level_progress_payload(p_level integer, p_current_experience integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_level integer := greatest(coalesce(p_level, 1), 1);
  v_current_experience integer := greatest(coalesce(p_current_experience, 0), 0);
  v_required integer := public.get_experience_required_for_level(v_level);
  v_remaining integer;
  v_ratio numeric;
begin
  v_remaining := greatest(v_required - v_current_experience, 0);

  if v_required <= 0 then
    v_ratio := 1;
  else
    v_ratio := least(
      1,
      greatest(v_current_experience::numeric / v_required::numeric, 0)
    );
  end if;

  return jsonb_build_object(
    'level', v_level,
    'current_level_start_experience', 0,
    'next_level_total_experience', v_required,
    'current_level_experience', v_current_experience,
    'next_level_required_experience', v_required,
    'remaining_experience_to_next_level', v_remaining,
    'progress_ratio', round(v_ratio, 4)
  );
end;
$function$;

-- Function: build_player_achievement_payload
CREATE OR REPLACE FUNCTION public.build_player_achievement_payload(p_player_id uuid, p_achievement_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', ad.id,
    'category', ad.category,
    'title', ad.title,
    'description', ad.description,
    'event_key', ad.event_key,
    'target_count', ad.target_count,
    'progress_count', coalesce(pa.progress_count, 0),
    'is_unlocked', coalesce(pa.is_unlocked, false),
    'unlocked_at', pa.unlocked_at,
    'is_claimed', pa.reward_granted_at is not null,
    'is_claimable', coalesce(pa.is_unlocked, false) and pa.reward_granted_at is null,
    'reward_granted_at', pa.reward_granted_at,
    'last_progress_at', pa.last_progress_at,
    'badge_key', ad.badge_key,
    'badge_color', ad.badge_color,
    'reward', jsonb_build_object(
      'xp', ad.reward_xp,
      'cash', ad.reward_cash,
      'gold', ad.reward_gold
    ),
    'progress_ratio',
      least(
        1.0,
        greatest(coalesce(pa.progress_count, 0), 0)::numeric / greatest(ad.target_count, 1)::numeric
      )
  )
  from public.achievement_definitions ad
  left join public.player_achievements pa
    on pa.achievement_id = ad.id
   and pa.player_id = p_player_id
  where ad.id = p_achievement_id;
$function$;

-- Function: build_player_mission_payload
CREATE OR REPLACE FUNCTION public.build_player_mission_payload(p_player_id uuid, p_mission_id text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', md.id,
    'mission_type', md.mission_type,
    'title', md.title,
    'description', md.description,
    'event_key', md.event_key,
    'icon_key', md.icon_key,
    'target_count', md.target_count,
    'progress_count', coalesce(pm.progress_count, 0),
    'is_completed', coalesce(pm.is_completed, false),
    'is_claimed', coalesce(pm.is_claimed, false),
    'claimable', coalesce(pm.is_completed, false) and coalesce(pm.is_claimed, false) = false,
    'completed_at', pm.completed_at,
    'claimed_at', pm.claimed_at,
    'reward', jsonb_build_object(
      'xp', md.reward_xp,
      'cash', md.reward_cash,
      'gold', md.reward_gold
    ),
    'display_order', md.display_order,
    'progress_ratio',
      case
        when md.target_count > 0 then
          round(least(coalesce(pm.progress_count, 0), md.target_count)::numeric / md.target_count::numeric, 4)
        else 0
      end
  )
  from public.mission_definitions md
  left join public.player_missions pm
    on pm.mission_id = md.id
   and pm.player_id = p_player_id
  where md.id = p_mission_id;
$function$;

-- Function: bulk_update_store_slot_prices
CREATE OR REPLACE FUNCTION public.bulk_update_store_slot_prices(p_player_id uuid, p_store_id uuid, p_markup_percent numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_store record;
  v_slot record;
  v_update_result jsonb;
  v_new_price numeric;
  v_examined_slot_count integer := 0;
  v_updated_slot_count integer := 0;
  v_failed_slot_count integer := 0;
  v_affected_slot_ids uuid[] := '{}'::uuid[];
  v_updated_slots jsonb := '[]'::jsonb;
begin
  if p_markup_percent is null or p_markup_percent < 1 or p_markup_percent > 300 then
    raise exception 'Kar marji 1 ile 300 arasinda olmalidir.';
  end if;

  select s.*
  into v_store
  from public.stores s
  where s.id = p_store_id
  for update;

  if not found then
    raise exception 'Magaza bulunamadi.';
  end if;

  if v_store.player_id <> p_player_id then
    raise exception 'Bu magaza oyuncuya ait degil.';
  end if;

  for v_slot in
    select ss.*
    from public.store_slots ss
    where ss.store_id = p_store_id
      and coalesce(ss.is_active, true) = true
      and coalesce(ss.product_id, '') <> ''
      and coalesce(ss.quality_level, 0) > 0
      and coalesce(ss.cost, 0) > 0
    order by ss.slot_index, ss.id
  loop
    v_examined_slot_count := v_examined_slot_count + 1;
    v_new_price := round(
      (coalesce(v_slot.cost, 0) * (1 + (p_markup_percent / 100.0)))::numeric,
      2
    );

    v_update_result := public.set_store_slot_price(
      p_player_id,
      v_slot.id,
      v_new_price
    );

    if coalesce((v_update_result ->> 'success')::boolean, false) then
      v_updated_slot_count := v_updated_slot_count + 1;
      v_affected_slot_ids := array_append(v_affected_slot_ids, v_slot.id);
      v_updated_slots := v_updated_slots || jsonb_build_object(
        'slot_id', v_slot.id,
        'price', v_new_price
      );
    else
      v_failed_slot_count := v_failed_slot_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'success', true,
    'store_id', p_store_id,
    'markup_percent', p_markup_percent,
    'examined_slot_count', v_examined_slot_count,
    'updated_slot_count', v_updated_slot_count,
    'failed_slot_count', v_failed_slot_count,
    'store_slot_ids', coalesce(to_jsonb(v_affected_slot_ids), '[]'::jsonb),
    'updated_slots', v_updated_slots,
    'message', case
      when v_updated_slot_count > 0
        then format('Magaza fiyatlari maliyet +%%%s olarak guncellendi.', p_markup_percent)
      else 'Guncellenecek uygun magaza slotu bulunamadi.'
    end
  );
end;
$function$;

-- Function: calculate_brand_level
CREATE OR REPLACE FUNCTION public.calculate_brand_level(p_xp bigint)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_xp < 1000 then 1
    when p_xp < 5000 then 2
    when p_xp < 15000 then 3
    when p_xp < 40000 then 4
    else 5
  end;
$function$;

-- Function: calculate_experience_reward
CREATE OR REPLACE FUNCTION public.calculate_experience_reward(p_reason text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_building_kind text := coalesce(p_meta ->> 'building_kind', '');
  v_target_level integer := greatest(coalesce((p_meta ->> 'target_level')::integer, 1), 1);
  v_target_quality integer := greatest(coalesce((p_meta ->> 'target_quality')::integer, 1), 1);
  v_quantity integer := greatest(coalesce((p_meta ->> 'quantity')::integer, 0), 0);
  v_sold_quantity integer := greatest(coalesce((p_meta ->> 'sold_quantity')::integer, 0), 0);
  v_profit numeric := greatest(coalesce((p_meta ->> 'profit')::numeric, 0), 0);
begin
  case p_reason
    when 'building_construction_completed' then
      return case v_building_kind
        when 'store' then 90
        when 'warehouse' then 80
        when 'factory' then 110
        when 'field' then 95
        when 'farm' then 95
        when 'mine' then 105
        when 'logistics_company' then 120
        when 'arge_center' then 130
        else 75
      end;
    when 'building_upgrade_completed' then
      return greatest(30, least(220, 30 + (v_target_level * 15)));
    when 'arge_research_completed' then
      return greatest(100, least(320, 80 + (v_target_quality * 40)));
    when 'market_transfer_completed' then
      return greatest(8, least(60, 8 + floor(v_quantity::numeric / 10)::integer));
    when 'production_transfer_completed' then
      return greatest(10, least(70, 10 + floor(v_quantity::numeric / 8)::integer));
    when 'store_sales_processed' then
      return greatest(
        0,
        least(
          60,
          floor(v_sold_quantity::numeric / 2)::integer
          + floor(v_profit / 1000)::integer
        )
      );
    else
      return greatest(coalesce((p_meta ->> 'exp_amount')::integer, 0), 0);
  end case;
end;
$function$;

-- Function: calculate_player_company_value
CREATE OR REPLACE FUNCTION public.calculate_player_company_value(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with building_base_assets as (
    select coalesce(sum(asset_value), 0)::numeric as total_value
    from (
      select coalesce(st.cost, 0)::numeric as asset_value
      from public.stores s
      join public.store_types st on st.id = s.store_type_id
      where s.player_id = p_player_id

      union all

      select coalesce(wt.cost, 0)::numeric
      from public.warehouses w
      join public.warehouse_types wt on wt.id = w.warehouse_type_id
      where w.player_id = p_player_id

      union all

      select coalesce(ft.cost, 0)::numeric
      from public.factories f
      join public.factory_types ft on ft.id = f.factory_type_id
      where f.player_id = p_player_id

      union all

      select coalesce(ft.cost, 0)::numeric
      from public.fields f
      join public.field_types ft on ft.id = f.field_type_id
      where f.player_id = p_player_id

      union all

      select coalesce(ft.cost, 0)::numeric
      from public.farms f
      join public.farm_types ft on ft.id = f.farm_type_id
      where f.player_id = p_player_id

      union all

      select coalesce(mt.cost, 0)::numeric
      from public.mines m
      join public.mine_types mt on mt.id = m.mine_type_id
      where m.player_id = p_player_id

      union all

      select coalesce(lct.cost, 0)::numeric
      from public.logistics_companies lc
      cross join lateral (
        select cost
        from public.logistics_company_types
        order by cost desc, created_at asc
        limit 1
      ) lct
      where lc.player_id = p_player_id

      union all

      select 25000::numeric
      from public.arge_centers ac
      where ac.player_id = p_player_id
    ) assets
  ),
  building_upgrade_assets as (
    select coalesce(sum(coalesce((bu.params ->> 'upgrade_cost')::numeric, 0)), 0)::numeric as total_value
    from public.building_upgrades bu
    where bu.player_id = p_player_id
      and bu.status = 'completed'
      and (
        (bu.building_kind = 'store' and exists (
          select 1 from public.stores s where s.id = bu.entity_id and s.player_id = p_player_id
        ))
        or (bu.building_kind = 'warehouse' and exists (
          select 1 from public.warehouses w where w.id = bu.entity_id and w.player_id = p_player_id
        ))
        or (bu.building_kind = 'factory' and exists (
          select 1 from public.factories f where f.id = bu.entity_id and f.player_id = p_player_id
        ))
        or (bu.building_kind = 'field' and exists (
          select 1 from public.fields f where f.id = bu.entity_id and f.player_id = p_player_id
        ))
        or (bu.building_kind = 'farm' and exists (
          select 1 from public.farms f where f.id = bu.entity_id and f.player_id = p_player_id
        ))
        or (bu.building_kind = 'mine' and exists (
          select 1 from public.mines m where m.id = bu.entity_id and m.player_id = p_player_id
        ))
        or (bu.building_kind = 'logistics_company' and exists (
          select 1 from public.logistics_companies lc where lc.id = bu.entity_id and lc.player_id = p_player_id
        ))
        or (bu.building_kind = 'arge_center' and exists (
          select 1 from public.arge_centers ac where ac.id = bu.entity_id and ac.player_id = p_player_id
        ))
      )
  ),
  vehicle_assets as (
    select coalesce(
      sum(
        coalesce(lvt.purchase_price, 0)::numeric
        * greatest(least(coalesce(lv.condition, 100), 100), 0)::numeric
        / 100.0
      ),
      0
    )::numeric as total_value
    from public.logistics_vehicles lv
    join public.logistics_vehicle_types lvt
      on lvt.id = lv.logistics_vehicle_type_id
    where lv.player_id = p_player_id
  ),
  warehouse_inventory_assets as (
    select coalesce(
      sum(
        greatest(coalesce(ws.quantity, 0), 0)::numeric
        * coalesce(
            p.baz_satis_fiyati * public.store_quality_price_multiplier(ws.quality_level),
            0
          )
      ),
      0
    )::numeric as total_value
    from public.warehouse_slots ws
    join public.warehouses w on w.id = ws.warehouse_id
    left join public.products p on p.id = ws.product_id
    where w.player_id = p_player_id
  ),
  store_inventory_assets as (
    select coalesce(
      sum(
        greatest(coalesce(ss.quantity, 0), 0)::numeric
        * coalesce(
            p.baz_satis_fiyati * public.store_quality_price_multiplier(ss.quality_level),
            0
          )
      ),
      0
    )::numeric as total_value
    from public.store_slots ss
    join public.stores s on s.id = ss.store_id
    left join public.products p on p.id = ss.product_id
    where s.player_id = p_player_id
  ),
  production_inventory_assets as (
    select coalesce(
      sum(
        greatest(coalesce(pi.quantity, 0), 0)::numeric
        * coalesce(
            p.baz_satis_fiyati * public.store_quality_price_multiplier(pi.quality_level),
            0
          )
      ),
      0
    )::numeric as total_value
    from public.production_inventory pi
    left join public.products p on p.id = pi.product_id
    where pi.owner_id in (
      select id from public.factories where player_id = p_player_id
      union
      select id from public.fields where player_id = p_player_id
      union
      select id from public.farms where player_id = p_player_id
      union
      select id from public.mines where player_id = p_player_id
    )
  ),
  player_assets as (
    select
      coalesce(pl.cash, 0)::numeric as cash_value,
      coalesce(pl.gold, 0)::numeric as gold_value
    from public.players pl
    where pl.id = p_player_id
  )
  select jsonb_build_object(
    'cash_value', pa.cash_value,
    'gold_value', pa.gold_value,
    'building_base_value', bba.total_value,
    'building_upgrade_value', bua.total_value,
    'vehicle_value', va.total_value,
    'warehouse_inventory_value', wia.total_value,
    'store_inventory_value', sia.total_value,
    'production_inventory_value', pia.total_value,
    'inventory_value', wia.total_value + sia.total_value + pia.total_value,
    'business_value', bba.total_value + bua.total_value + va.total_value,
    'total_company_value',
      pa.cash_value
      + bba.total_value
      + bua.total_value
      + va.total_value
      + wia.total_value
      + sia.total_value
      + pia.total_value
  )
  from building_base_assets bba
  cross join building_upgrade_assets bua
  cross join vehicle_assets va
  cross join warehouse_inventory_assets wia
  cross join store_inventory_assets sia
  cross join production_inventory_assets pia
  cross join player_assets pa;
$function$;

-- Function: calculate_store_saturation_multiplier
CREATE OR REPLACE FUNCTION public.calculate_store_saturation_multiplier(p_city_id uuid, p_store_type_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pop integer;
  v_store_type_name text;
  v_people_per_store integer;
  v_ideal_capacity integer;
  v_current_count integer;
  v_saturation_ratio numeric;
BEGIN
  SELECT population INTO v_pop FROM public.cities WHERE id = p_city_id;
  IF NOT FOUND OR coalesce(v_pop, 0) <= 0 THEN
    v_pop := 500000;
  END IF;

  SELECT name INTO v_store_type_name FROM public.store_types WHERE id = p_store_type_id;

  v_people_per_store := CASE coalesce(v_store_type_name, '')
    WHEN 'Büfe' THEN 50000
    WHEN 'Manav' THEN 60000
    WHEN 'Market' THEN 75000
    WHEN 'Fırın' THEN 80000
    WHEN 'Kasap' THEN 90000
    WHEN 'Kuruyemişçi' THEN 100000
    WHEN 'Süpermarket' THEN 150000
    WHEN 'Tekstil Mağazası' THEN 180000
    WHEN 'Mobilya Mağazası' THEN 220000
    WHEN 'Kozmetik Mağazası' THEN 250000
    WHEN 'Beyaz Eşya' THEN 280000
    WHEN 'Teknoloji ve Elektronik' THEN 320000
    WHEN 'İnşaat Malzemeleri' THEN 350000
    WHEN 'Kuyumcu' THEN 400000
    WHEN 'Oto Galeri' THEN 500000
    ELSE 100000
  END;

  v_ideal_capacity := greatest(1, round(v_pop::numeric / v_people_per_store)::integer);

  SELECT count(*)
  INTO v_current_count
  FROM public.stores
  WHERE city_id = p_city_id
    AND store_type_id = p_store_type_id
    AND is_active = true;

  v_saturation_ratio := v_current_count::numeric / v_ideal_capacity::numeric;

  -- Saturation Curve:
  -- 0 stores: 1.30x (+30% virgin market bonus)
  -- 0.0 - 0.5 ratio: 1.30x -> 1.15x (+15% to +30% opportunity bonus)
  -- 0.5 - 1.0 ratio: 1.15x -> 1.00x (Balanced)
  -- 1.0 - 2.0 ratio: 1.00x -> 0.60x (High competition)
  -- > 2.0 ratio: 0.50x floor limit (Saturated)
  IF v_saturation_ratio <= 0.0 THEN
    RETURN 1.30;
  ELSIF v_saturation_ratio <= 0.5 THEN
    RETURN round((1.30 - (v_saturation_ratio / 0.5) * 0.15)::numeric, 4);
  ELSIF v_saturation_ratio <= 1.0 THEN
    RETURN round((1.15 - ((v_saturation_ratio - 0.5) / 0.5) * 0.15)::numeric, 4);
  ELSIF v_saturation_ratio <= 2.0 THEN
    RETURN round((1.00 - ((v_saturation_ratio - 1.0) / 1.0) * 0.40)::numeric, 4);
  ELSE
    RETURN 0.50;
  END IF;
END;
$function$;

-- Function: cancel_player_tender
CREATE OR REPLACE FUNCTION public.cancel_player_tender(p_player_tender_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_now timestamptz := timezone('utc'::text, now());
  v_player_tender public.player_tenders%rowtype;
  v_tender_title text := 'Ihale';
  v_cancelled_delivery_count integer := 0;
  v_cancelled_quantity integer := 0;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  select *
  into v_player_tender
  from public.player_tenders
  where id = p_player_tender_id
    and player_id = v_player_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Oyuncu ihalesi bulunamadi.');
  end if;

  if v_player_tender.status <> 'active' then
    return jsonb_build_object('success', false, 'message', 'Sadece aktif ihale iptal edilebilir.');
  end if;

  select coalesce(t.title, 'Ihale')
  into v_tender_title
  from public.tenders t
  where t.id = v_player_tender.tender_id;

  select
    count(*)::integer,
    coalesce(sum(td.quantity), 0)::integer
  into v_cancelled_delivery_count, v_cancelled_quantity
  from public.tender_deliveries td
  where td.player_tender_id = v_player_tender.id
    and td.status = 'in_transit';

  update public.tender_deliveries
  set status = 'cancelled',
      updated_at = v_now
  where player_tender_id = v_player_tender.id
    and status = 'in_transit';

  update public.logistics_vehicles lv
  set status = 'idle',
      updated_at = v_now
  where exists (
    select 1
    from public.tender_deliveries td
    where td.player_tender_id = v_player_tender.id
      and td.vehicle_id = lv.id
      and td.status = 'cancelled'
  );

  update public.player_tenders
  set status = 'cancelled',
      updated_at = v_now
  where id = v_player_tender.id;

  return jsonb_build_object(
    'success', true,
    'player_tender_id', v_player_tender.id,
    'status', 'cancelled',
    'cancelled_delivery_count', v_cancelled_delivery_count,
    'cancelled_quantity', v_cancelled_quantity,
    'message', 'Ihale iptal edildi. Teminat ve yoldaki sevkiyat yandi.'
  );
end;
$function$;

-- Function: change_production_slot_product
CREATE OR REPLACE FUNCTION public.change_production_slot_product(p_player_id uuid, p_production_slot_id uuid, p_product_id text, p_quality_level integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot public.production_slots%rowtype;
  v_product public.products%rowtype;
  v_old_product public.products%rowtype;

  v_owner_player_id uuid;
  v_owner_type_id uuid;
  v_accepted_product_ids text;
  v_product_unit text;

  v_old_product_id text;
  v_old_quality_level integer;
  v_old_brand_id uuid;
  v_same_setting boolean;

  v_max_quality integer;
  v_existing_input_quantity integer := 0;
  v_existing_input_pending numeric := 0;
  v_existing_output_quantity integer := 0;
  v_existing_output_pending numeric := 0;

  v_created_input_count integer := 0;
  v_created_output_count integer := 0;
  v_deleted_obsolete_count integer := 0;

  v_hammadde_1_id text;
  v_hammadde_2_id text;
  v_hammadde_3_id text;
  v_old_hammadde_1_id text;
  v_old_hammadde_2_id text;
  v_old_hammadde_3_id text;

  v_hammadde_1_miktar numeric;
  v_hammadde_2_miktar numeric;
  v_hammadde_3_miktar numeric;
  v_old_hammadde_1_miktar numeric;
  v_old_hammadde_2_miktar numeric;
  v_old_hammadde_3_miktar numeric;

  v_input_quality_level integer;
  v_old_input_quality_level integer;
  v_inventory_id uuid;
  v_output_inventory_id uuid;
begin
  perform pg_advisory_xact_lock(hashtext('field_farm_production_lock'));

  if p_quality_level is null or p_quality_level < 1 or p_quality_level > 5 then
    raise exception 'Kalite seviyesi 1 ile 5 arasinda olmalidir.';
  end if;

  v_input_quality_level := greatest(1, least(coalesce(p_quality_level, 1), 5) - 1);

  select *
  into v_slot
  from public.production_slots
  where id = p_production_slot_id
  for update;

  if not found then
    raise exception 'Uretim slotu bulunamadi.';
  end if;

  if coalesce(v_slot.product_id, '') = '' or coalesce(v_slot.quality_level, 0) <= 0 then
    raise exception 'Bu slotta henuz urun yok. Ilk urun secme akisini kullan.';
  end if;

  if v_slot.owner_kind not in ('field', 'farm') then
    raise exception 'Gecersiz production slot owner_kind: %', v_slot.owner_kind;
  end if;

  v_old_product_id := v_slot.product_id;
  v_old_quality_level := v_slot.quality_level;
  v_old_brand_id := v_slot.brand_id;
  v_old_input_quality_level := greatest(1, coalesce(v_old_quality_level, 1) - 1);

  select *
  into v_old_product
  from public.products
  where id = v_old_product_id;

  if v_slot.owner_kind = 'field' then
    select f.player_id, f.field_type_id, ft.accepted_product_ids
    into v_owner_player_id, v_owner_type_id, v_accepted_product_ids
    from public.fields f
    join public.field_types ft on ft.id = f.field_type_id
    where f.id = v_slot.owner_id;
  elsif v_slot.owner_kind = 'farm' then
    select fa.player_id, fa.farm_type_id, ft.accepted_product_ids
    into v_owner_player_id, v_owner_type_id, v_accepted_product_ids
    from public.farms fa
    join public.farm_types ft on ft.id = fa.farm_type_id
    where fa.id = v_slot.owner_id;
  end if;

  if v_owner_player_id is null then
    raise exception 'Uretim slotunun bagli oldugu yapi bulunamadi.';
  end if;

  if v_owner_player_id <> p_player_id then
    raise exception 'Bu uretim slotu oyuncuya ait degil.';
  end if;

  select *
  into v_product
  from public.products
  where id = p_product_id;

  if not found then
    raise exception 'Urun bulunamadi: %', p_product_id;
  end if;

  v_product_unit := lower(trim(coalesce(v_product.uretim_birimi, '')));

  -- 'farm' is Tarla
  if v_slot.owner_kind = 'farm'
     and v_product_unit not in ('tarla', 'farm') then
    raise exception 'Bu urun tarla urunu degil: %', p_product_id;
  end if;

  -- 'field' is Çiftlik
  if v_slot.owner_kind = 'field'
     and v_product_unit not in ('ciftlik', 'çiftlik', 'field') then
    raise exception 'Bu urun ciftlik urunu degil: %', p_product_id;
  end if;

  if v_accepted_product_ids is null
     or not (p_product_id = any(regexp_split_to_array(v_accepted_product_ids, '\s*,\s*'))) then
    raise exception 'Bu yapi turu bu urunu uretemez: %', p_product_id;
  end if;

  select coalesce(max(max_quality_level), 1)
  into v_max_quality
  from public.player_product_quality_levels
  where player_id = p_player_id
    and product_id = p_product_id;

  if v_max_quality is null then
    v_max_quality := 1;
  end if;

  if p_quality_level > v_max_quality then
    raise exception 'Oyuncu bu urun icin kalite % seviyesine ulasmadi. Mevcut maksimum kalite: %', p_quality_level, v_max_quality;
  end if;

  v_same_setting :=
    v_old_product_id = p_product_id
    and v_old_quality_level = p_quality_level;

  v_hammadde_1_id := nullif(v_product.hammadde_1_id, '');
  v_hammadde_2_id := nullif(v_product.hammadde_2_id, '');
  v_hammadde_3_id := nullif(v_product.hammadde_3_id, '');
  v_hammadde_1_miktar := coalesce(v_product.hammadde_1_miktar, 0);
  v_hammadde_2_miktar := coalesce(v_product.hammadde_2_miktar, 0);
  v_hammadde_3_miktar := coalesce(v_product.hammadde_3_miktar, 0);

  v_old_hammadde_1_id := nullif(v_old_product.hammadde_1_id, '');
  v_old_hammadde_2_id := nullif(v_old_product.hammadde_2_id, '');
  v_old_hammadde_3_id := nullif(v_old_product.hammadde_3_id, '');
  v_old_hammadde_1_miktar := coalesce(v_old_product.hammadde_1_miktar, 0);
  v_old_hammadde_2_miktar := coalesce(v_old_product.hammadde_2_miktar, 0);
  v_old_hammadde_3_miktar := coalesce(v_old_product.hammadde_3_miktar, 0);

  if not v_same_setting then
    select coalesce(sum(quantity), 0), coalesce(sum(pending_quantity), 0)
    into v_existing_output_quantity, v_existing_output_pending
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'output'
      and product_id = v_old_product_id
      and quality_level = v_old_quality_level
      and brand_id = v_old_brand_id;

    if v_existing_output_quantity > 0 then
      raise exception 'Bu slotun mevcut output stogu var. Urun degistirmeden once stoklari depoya aktar.';
    end if;

    select coalesce(sum(pi.quantity), 0), coalesce(sum(pi.pending_quantity), 0)
    into v_existing_input_quantity, v_existing_input_pending
    from public.production_inventory pi
    where pi.owner_kind = v_slot.owner_kind
      and pi.owner_id = v_slot.owner_id
      and pi.inventory_type = 'input'
      and (
        (v_old_hammadde_1_id is not null and v_old_hammadde_1_miktar > 0 and pi.product_id = v_old_hammadde_1_id and pi.quality_level = v_old_input_quality_level)
        or (v_old_hammadde_2_id is not null and v_old_hammadde_2_miktar > 0 and pi.product_id = v_old_hammadde_2_id and pi.quality_level = v_old_input_quality_level)
        or (v_old_hammadde_3_id is not null and v_old_hammadde_3_miktar > 0 and pi.product_id = v_old_hammadde_3_id and pi.quality_level = v_old_input_quality_level)
      )
      and not (
        (v_hammadde_1_id is not null and v_hammadde_1_miktar > 0 and pi.product_id = v_hammadde_1_id and pi.quality_level = v_input_quality_level)
        or (v_hammadde_2_id is not null and v_hammadde_2_miktar > 0 and pi.product_id = v_hammadde_2_id and pi.quality_level = v_input_quality_level)
        or (v_hammadde_3_id is not null and v_hammadde_3_miktar > 0 and pi.product_id = v_hammadde_3_id and pi.quality_level = v_input_quality_level)
      )
      and not exists (
        select 1
        from public.production_slots ps
        join public.products pr on pr.id = ps.product_id
        where ps.owner_kind = pi.owner_kind
          and ps.owner_id = pi.owner_id
          and ps.id <> v_slot.id
          and coalesce(ps.product_id, '') <> ''
          and pi.quality_level = greatest(coalesce(ps.quality_level, 1) - 1, 1)
          and (
            (nullif(pr.hammadde_1_id, '') = pi.product_id and coalesce(pr.hammadde_1_miktar, 0) > 0)
            or (nullif(pr.hammadde_2_id, '') = pi.product_id and coalesce(pr.hammadde_2_miktar, 0) > 0)
            or (nullif(pr.hammadde_3_id, '') = pi.product_id and coalesce(pr.hammadde_3_miktar, 0) > 0)
          )
      );

    if v_existing_input_quantity > 0 then
      raise exception 'Bu slotun yeni urunde kullanilmayan input stoklari var. Urun degistirmeden once stoklari depoya aktar.';
    end if;

    if coalesce(v_existing_input_pending, 0) > 0 then
      raise exception 'Bu slotun yeni urunde kullanilmayan inputlari icin yoldaki urunler var. Urun degistirmeden once transferlerin tamamlanmasini bekleyin.';
    end if;

    if coalesce(v_existing_output_pending, 0) > 0 then
      update public.production_inventory
      set pending_quantity = 0
      where owner_kind = v_slot.owner_kind
        and owner_id = v_slot.owner_id
        and inventory_type = 'output'
        and product_id = v_old_product_id
        and quality_level = v_old_quality_level
        and brand_id = v_old_brand_id;
    end if;
  end if;

  update public.production_slots
  set product_id = p_product_id,
      quality_level = p_quality_level,
      brand_id = public.resolve_player_product_brand(v_owner_player_id, p_product_id),
      updated_at = timezone('utc'::text, now()),
      last_production_at = timezone('utc'::text, now())
  where id = p_production_slot_id;

  if v_hammadde_1_id is not null and v_hammadde_1_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_1_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_1_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  if v_hammadde_2_id is not null and v_hammadde_2_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_2_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_2_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  if v_hammadde_3_id is not null and v_hammadde_3_miktar > 0 then
    select id into v_inventory_id
    from public.production_inventory
    where owner_kind = v_slot.owner_kind
      and owner_id = v_slot.owner_id
      and inventory_type = 'input'
      and product_id = v_hammadde_3_id
      and quality_level = v_input_quality_level;

    if not found then
      insert into public.production_inventory (
        owner_kind, owner_id, inventory_type, product_id, quality_level, quantity, pending_quantity, cost
      ) values (
        v_slot.owner_kind, v_slot.owner_id, 'input', v_hammadde_3_id, v_input_quality_level, 0, 0, 0
      );
      v_created_input_count := v_created_input_count + 1;
    end if;
  end if;

  select id into v_output_inventory_id
  from public.production_inventory
  where owner_kind = v_slot.owner_kind
    and owner_id = v_slot.owner_id
    and inventory_type = 'output'
    and product_id = p_product_id
    and quality_level = p_quality_level
    and brand_id = public.resolve_player_product_brand(v_owner_player_id, p_product_id);

  if not found then
    insert into public.production_inventory (
      owner_kind, owner_id, inventory_type, product_id, quality_level, brand_id, quantity, pending_quantity, cost
    ) values (
      v_slot.owner_kind, v_slot.owner_id, 'output', p_product_id, p_quality_level, public.resolve_player_product_brand(v_owner_player_id, p_product_id), 0, 0, 0
    ) returning id into v_output_inventory_id;
    v_created_output_count := 1;
  end if;

  if not v_same_setting then
    update public.logistics_transfer_items lti
    set target_production_inventory_id = null
    from public.logistics_transfers lt
    where lt.id = lti.transfer_id
      and lt.status = 'completed'
      and lti.status = 'completed'
      and exists (
        select 1
        from public.production_inventory pi
        where pi.id = lti.target_production_inventory_id
          and pi.owner_kind = v_slot.owner_kind
          and pi.owner_id = v_slot.owner_id
          and coalesce(pi.quantity, 0) = 0
          and coalesce(pi.pending_quantity, 0) = 0
          and not (
            pi.inventory_type = 'output'
            and exists (
              select 1
              from public.production_slots ps
              where ps.owner_kind = pi.owner_kind
                and ps.owner_id = pi.owner_id
                and coalesce(ps.product_id, '') <> ''
                and ps.product_id = pi.product_id
                and ps.quality_level = pi.quality_level
                and ps.brand_id = pi.brand_id
            )
          )
          and not (
            pi.inventory_type = 'input'
            and exists (
              select 1
              from public.production_slots ps
              join public.products pr on pr.id = ps.product_id
              where ps.owner_kind = pi.owner_kind
                and ps.owner_id = pi.owner_id
                and coalesce(ps.product_id, '') <> ''
                and pi.quality_level = greatest(coalesce(ps.quality_level, 1) - 1, 1)
                and (
                  (nullif(pr.hammadde_1_id, '') = pi.product_id and coalesce(pr.hammadde_1_miktar, 0) > 0)
                  or (nullif(pr.hammadde_2_id, '') = pi.product_id and coalesce(pr.hammadde_2_miktar, 0) > 0)
                  or (nullif(pr.hammadde_3_id, '') = pi.product_id and coalesce(pr.hammadde_3_miktar, 0) > 0)
                )
            )
          )
      );

    update public.logistics_transfers lt
    set seller_production_inventory_id = null
    where lt.status = 'completed'
      and exists (
        select 1
        from public.production_inventory pi
        where pi.id = lt.seller_production_inventory_id
          and pi.owner_kind = v_slot.owner_kind
          and pi.owner_id = v_slot.owner_id
          and coalesce(pi.quantity, 0) = 0
          and coalesce(pi.pending_quantity, 0) = 0
          and not (
            pi.inventory_type = 'output'
            and exists (
              select 1
              from public.production_slots ps
              where ps.owner_kind = pi.owner_kind
                and ps.owner_id = pi.owner_id
                and coalesce(ps.product_id, '') <> ''
                and ps.product_id = pi.product_id
                and ps.quality_level = pi.quality_level
                and ps.brand_id = pi.brand_id
            )
          )
          and not (
            pi.inventory_type = 'input'
            and exists (
              select 1
              from public.production_slots ps
              join public.products pr on pr.id = ps.product_id
              where ps.owner_kind = pi.owner_kind
                and ps.owner_id = pi.owner_id
                and coalesce(ps.product_id, '') <> ''
                and pi.quality_level = greatest(coalesce(ps.quality_level, 1) - 1, 1)
                and (
                  (nullif(pr.hammadde_1_id, '') = pi.product_id and coalesce(pr.hammadde_1_miktar, 0) > 0)
                  or (nullif(pr.hammadde_2_id, '') = pi.product_id and coalesce(pr.hammadde_2_miktar, 0) > 0)
                  or (nullif(pr.hammadde_3_id, '') = pi.product_id and coalesce(pr.hammadde_3_miktar, 0) > 0)
                )
            )
          )
      );

    delete from public.production_inventory pi
    where pi.owner_kind = v_slot.owner_kind
      and pi.owner_id = v_slot.owner_id
      and coalesce(pi.quantity, 0) = 0
      and coalesce(pi.pending_quantity, 0) = 0
      and not exists (
        select 1
        from public.logistics_transfers lt
        where lt.seller_production_inventory_id = pi.id
           or lt.buyer_production_inventory_id = pi.id
      )
      and not (
        pi.inventory_type = 'output'
        and exists (
          select 1
          from public.production_slots ps
          where ps.owner_kind = pi.owner_kind
            and ps.owner_id = pi.owner_id
            and coalesce(ps.product_id, '') <> ''
            and ps.product_id = pi.product_id
            and ps.quality_level = pi.quality_level
            and ps.brand_id = pi.brand_id
        )
      )
      and not (
        pi.inventory_type = 'input'
        and exists (
          select 1
          from public.production_slots ps
          join public.products pr on pr.id = ps.product_id
          where ps.owner_kind = pi.owner_kind
            and ps.owner_id = pi.owner_id
            and coalesce(ps.product_id, '') <> ''
            and pi.quality_level = greatest(coalesce(ps.quality_level, 1) - 1, 1)
            and (
              (nullif(pr.hammadde_1_id, '') = pi.product_id and coalesce(pr.hammadde_1_miktar, 0) > 0)
              or (nullif(pr.hammadde_2_id, '') = pi.product_id and coalesce(pr.hammadde_2_miktar, 0) > 0)
              or (nullif(pr.hammadde_3_id, '') = pi.product_id and coalesce(pr.hammadde_3_miktar, 0) > 0)
            )
        )
      );

    get diagnostics v_deleted_obsolete_count = row_count;
  end if;

  return jsonb_build_object(
    'success', true,
    'mode', 'change',
    'production_slot_id', p_production_slot_id,
    'owner_kind', v_slot.owner_kind,
    'owner_id', v_slot.owner_id,
    'owner_type_id', v_owner_type_id,
    'old_product_id', v_old_product_id,
    'old_quality_level', v_old_quality_level,
    'product_id', p_product_id,
    'product_name', v_product.urun_adi,
    'quality_level', p_quality_level,
    'input_quality_level', v_input_quality_level,
    'player_max_quality_level', v_max_quality,
    'same_setting', v_same_setting,
    'existing_output_quantity', coalesce(v_existing_output_quantity, 0),
    'cleared_output_pending_quantity', coalesce(v_existing_output_pending, 0),
    'created_input_count', v_created_input_count,
    'created_output_count', v_created_output_count,
    'deleted_obsolete_inventory_count', v_deleted_obsolete_count,
    'output_inventory_id', v_output_inventory_id,
    'slots', coalesce((
      select jsonb_agg(
        (to_jsonb(ps) - 'boost_multiplier') || jsonb_build_object(
          'boost_multiplier',
          coalesce((
            select bb.multiplier
            from public.building_boosts bb
            where bb.player_id = auth.uid()
              and bb.building_kind = v_slot.owner_kind
              and bb.entity_id = v_slot.owner_id
              and bb.status = 'in_progress'
              and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
            order by bb.started_at desc
            limit 1
          ), 1.00),
          'product',
          case when p.id is null then null else to_jsonb(p) end
        )
        order by ps.slot_index
      )
      from public.production_slots ps
      left join public.products p on p.id = ps.product_id
      where ps.owner_kind = v_slot.owner_kind
        and ps.owner_id = v_slot.owner_id
    ), '[]'::jsonb),
    'inventories', coalesce((
      select jsonb_agg(
        to_jsonb(pi) || jsonb_build_object(
          'product',
          case when p.id is null then null else to_jsonb(p) end
        )
        order by pi.id
      )
      from public.production_inventory pi
      left join public.products p on p.id = pi.product_id
      where pi.owner_kind = v_slot.owner_kind
        and pi.owner_id = v_slot.owner_id
    ), '[]'::jsonb),
    'changed', jsonb_build_object(
      'player', public.get_player_profile(p_player_id)
    )
  );
end;
$function$;

-- Function: claim_daily_streak_reward
CREATE OR REPLACE FUNCTION public.claim_daily_streak_reward(p_reward_cash numeric, p_reward_gold numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_current_cash numeric;
  v_current_gold numeric;
BEGIN
  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Oturum acilmamis.';
  END IF;

  -- Update player cash and gold
  UPDATE public.players
  SET cash = cash + p_reward_cash,
      gold = gold + p_reward_gold
  WHERE id = v_player_id
  RETURNING cash, gold INTO v_current_cash, v_current_gold;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Oyuncu bulunamadi.';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Gunluk giris odulu alindi.',
    'new_cash', v_current_cash,
    'new_gold', v_current_gold,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id),
      'dashboard_dirty', true
    )
  );
END;
$function$;

-- Function: claim_deposit
CREATE OR REPLACE FUNCTION public.claim_deposit(p_deposit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_current_cash numeric;
  v_amount numeric;
  v_expected_payout numeric;
  v_locked_until timestamp with time zone;
  v_status text;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  -- Lock deposit record
  select status, amount, expected_payout, locked_until
  into v_status, v_amount, v_expected_payout, v_locked_until
  from public.player_deposits
  where id = p_deposit_id and player_id = v_player_id for update;

  if v_status is null then
    return jsonb_build_object('success', false, 'message', 'Mevduat kaydi bulunamadi.');
  end if;

  if v_status != 'active' then
    return jsonb_build_object('success', false, 'message', 'Bu mevduat hesabi zaten kapatilmis.');
  end if;

  if v_locked_until > now() then
    return jsonb_build_object('success', false, 'message', 'Mevduat vadesi henüz dolmadı.');
  end if;

  -- Lock player
  select cash into v_current_cash from public.players where id = v_player_id for update;

  -- Update deposit status
  update public.player_deposits
  set status = 'claimed',
      updated_at = now()
  where id = p_deposit_id;

  -- Add cash (principal + interest)
  update public.players
  set cash = cash + v_expected_payout
  where id = v_player_id;

  -- Log cash change
  perform public.log_player_cash_change(
    v_player_id,
    v_expected_payout,
    v_current_cash,
    'deposit_claimed',
    format('Mevduat Vade Sonu Tahsilati (Net Getiri: +%s TL)', round(v_expected_payout - v_amount, 2)),
    p_deposit_id,
    'deposit'
  );

  return jsonb_build_object(
    'success', true,
    'message', format('Mevduat başarıyla tahsil edildi. %s TL hesabınıza aktarıldı.', round(v_expected_payout, 2)),
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id)
    )
  );
end;
$function$;

-- Function: claim_player_achievement_reward
CREATE OR REPLACE FUNCTION public.claim_player_achievement_reward(p_achievement_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_def public.achievement_definitions%rowtype;
  v_row public.player_achievements%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_exp_result jsonb := null;
  v_balance_before numeric;
  v_reward_cash numeric;
  v_reward_gold integer;
  v_reward_xp integer;
  v_player jsonb;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  perform public.ensure_player_achievement_rows(v_player_id);
  perform public.sync_player_achievement_snapshot(v_player_id);

  select * into v_def
  from public.achievement_definitions
  where id = p_achievement_id and is_active = true;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Basari bulunamadi.');
  end if;

  select * into v_row
  from public.player_achievements
  where player_id = v_player_id and achievement_id = p_achievement_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Oyuncu basarisi bulunamadi.');
  end if;

  if v_row.is_unlocked = false then
    return jsonb_build_object('success', false, 'message', 'Bu basarim henuz acilmadi.');
  end if;

  if v_row.reward_granted_at is not null then
    return jsonb_build_object('success', false, 'already_claimed', true, 'message', 'Bu basarim odulu zaten alindi.');
  end if;

  v_reward_cash := coalesce(v_def.reward_cash, 0);
  v_reward_gold := coalesce(v_def.reward_gold, 0);
  v_reward_xp := coalesce(v_def.reward_xp, 0);

  if v_reward_cash > 0 or v_reward_gold > 0 then
    select cash into v_balance_before from public.players where id = v_player_id;
    update public.players
    set
      cash = cash + v_reward_cash,
      gold = gold + v_reward_gold
    where id = v_player_id;

    if v_reward_cash > 0 then
      perform public.log_player_cash_change(
        v_player_id, v_reward_cash, v_balance_before,
        'achievement_reward',
        format('Basarim odulu: %s', v_def.title),
        null, null
      );
    end if;
  end if;

  if v_reward_xp > 0 then
    v_exp_result := public.grant_player_experience(
      v_player_id, v_reward_xp, 'achievement_reward_claimed',
      jsonb_build_object('achievement_id', v_def.id, 'title', v_def.title, 'category', v_def.category)
    );
  end if;

  update public.player_achievements
  set
    reward_granted_at = v_now,
    updated_at = v_now
  where player_id = v_player_id and achievement_id = p_achievement_id;

  v_player := public.get_player_profile(v_player_id);

  return jsonb_build_object(
    'success', true,
    'message', 'Basarim odulu basariyla alindi.',
    'achievement_id', v_def.id,
    'reward', jsonb_build_object('xp', v_reward_xp, 'cash', v_reward_cash, 'gold', v_reward_gold),
    'experience', v_exp_result,
    'player', v_player,
    'changed', jsonb_build_object(
      'player', v_player,
      'dashboard_dirty', true
    )
  );
end;
$function$;

-- Function: claim_player_mission_reward
CREATE OR REPLACE FUNCTION public.claim_player_mission_reward(p_mission_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_now timestamptz := timezone('utc', now());
  v_mission record;
  v_exp_result jsonb := null;
  v_player jsonb;
  v_balance_before numeric;
  v_reward_cash numeric;
begin
  if v_player_id is null then raise exception 'Oturum acilmamis.'; end if;

  perform public.ensure_player_mission_rows(v_player_id);
  perform public.reset_player_daily_missions(v_player_id);
  perform public.reset_player_weekly_missions(v_player_id);
  perform public.sync_player_mission_snapshot(v_player_id);

  select pm.player_id, pm.mission_id, pm.progress_count, pm.is_completed, pm.is_claimed,
         md.title, md.reward_xp, md.reward_cash, md.reward_gold
  into v_mission
  from public.player_missions pm
  join public.mission_definitions md on md.id = pm.mission_id
  where pm.player_id = v_player_id and pm.mission_id = p_mission_id and md.is_active = true
  for update of pm;

  if not found then return jsonb_build_object('success', false, 'message', 'Gorev bulunamadi.'); end if;
  if v_mission.is_claimed then return jsonb_build_object('success', false, 'message', 'Bu gorevin odulu zaten alindi.'); end if;
  if v_mission.is_completed = false then return jsonb_build_object('success', false, 'message', 'Bu gorev henuz tamamlanmadi.'); end if;

  update public.player_missions
  set is_claimed = true, claimed_at = v_now, updated_at = v_now
  where player_id = v_player_id and mission_id = p_mission_id;

  v_reward_cash := coalesce(v_mission.reward_cash, 0);
  if v_reward_cash > 0 or coalesce(v_mission.reward_gold, 0) > 0 then
    select cash into v_balance_before from public.players where id = v_player_id;
    update public.players
    set cash = cash + v_reward_cash, gold = gold + coalesce(v_mission.reward_gold, 0)
    where id = v_player_id;
    if v_reward_cash > 0 then
      perform public.log_player_cash_change(
        v_player_id, v_reward_cash, v_balance_before,
        'mission_reward',
        format('Gorev odulu: %s', v_mission.title),
        null, null
      );
    end if;
  end if;

  if coalesce(v_mission.reward_xp, 0) > 0 then
    v_exp_result := public.grant_player_experience(
      v_player_id, v_mission.reward_xp, 'mission_reward_claimed',
      jsonb_build_object('mission_id', p_mission_id, 'mission_title', v_mission.title)
    );
  end if;

  v_player := public.get_player_profile(v_player_id);

  return jsonb_build_object(
    'success', true,
    'message', 'Gorev odulu alindi.',
    'mission', public.build_player_mission_payload(v_player_id, p_mission_id),
    'reward', jsonb_build_object('xp', coalesce(v_mission.reward_xp, 0), 'cash', v_reward_cash, 'gold', coalesce(v_mission.reward_gold, 0)),
    'experience', v_exp_result,
    'player', v_player,
    'changed', jsonb_build_object(
      'player', v_player,
      'dashboard_dirty', true
    )
  );
end;
$function$;

-- Function: cleanup_database_bloat
CREATE OR REPLACE FUNCTION public.cleanup_database_bloat()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_cron integer := 0;
  v_deleted_expired_tenders integer := 0;
BEGIN
  -- A. 3 günden eski pg_cron çalıştırma loglarını temizle
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    BEGIN
      DELETE FROM cron.job_run_details
      WHERE start_time < timezone('utc'::text, now()) - interval '3 days';
      GET DIAGNOSTICS v_deleted_cron = ROW_COUNT;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- B. Teklifsiz ve sahipsiz 24 saatten eski süresi dolmuş ihaleleri temizle
  DELETE FROM public.tenders t
  WHERE t.status = 'expired'
    AND t.updated_at < timezone('utc'::text, now()) - interval '24 hours'
    AND NOT EXISTS (
      SELECT 1 FROM public.tender_bids tb WHERE tb.tender_id = t.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.player_tenders pt WHERE pt.tender_id = t.id
    );
  GET DIAGNOSTICS v_deleted_expired_tenders = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_cron_logs', v_deleted_cron,
    'deleted_expired_tenders', v_deleted_expired_tenders,
    'cleaned_at', timezone('utc'::text, now())
  );
END;
$function$;

-- Function: clear_player_notifications
CREATE OR REPLACE FUNCTION public.clear_player_notifications(p_only_read boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_only_read THEN
    DELETE FROM public.player_notifications
    WHERE player_id = auth.uid()
      AND is_read = true;
  ELSE
    DELETE FROM public.player_notifications
    WHERE player_id = auth.uid();
  END IF;

  RETURN true;
END;
$function$;

-- Function: clear_store_slot_product
CREATE OR REPLACE FUNCTION public.clear_store_slot_product(p_player_id uuid, p_store_slot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot record;
  v_warehouse_id uuid;
  v_existing_wh_slot_id uuid;
  v_now timestamptz := timezone('utc'::text, now());
begin
  select
    ss.*,
    s.player_id
  into v_slot
  from public.store_slots ss
  join public.stores s on s.id = ss.store_id
  where ss.id = p_store_slot_id
  for update;

  if not found then
    raise exception 'Magaza slotu bulunamadi.';
  end if;

  if v_slot.player_id <> p_player_id then
    raise exception 'Bu slot oyuncuya ait degil.';
  end if;

  -- Eger rafta kalan stok varsa depoya aktar
  if coalesce(v_slot.quantity, 0) > 0 and v_slot.product_id is not null then
    select id into v_warehouse_id
    from public.warehouses
    where store_id = v_slot.store_id
      and warehouse_kind = 'store'
      and is_active = true
    order by created_at desc
    limit 1;

    if v_warehouse_id is not null then
      select id into v_existing_wh_slot_id
      from public.warehouse_slots
      where warehouse_id = v_warehouse_id
        and product_id = v_slot.product_id
        and quality_level = v_slot.quality_level
        and coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(v_slot.brand_id, '00000000-0000-0000-0000-000000000000'::uuid)
      limit 1;

      if v_existing_wh_slot_id is not null then
        update public.warehouse_slots
        set
          quantity = quantity + v_slot.quantity,
          updated_at = v_now
        where id = v_existing_wh_slot_id;
      else
        insert into public.warehouse_slots (
          warehouse_id,
          product_id,
          quality_level,
          brand_id,
          quantity,
          cost,
          created_at,
          updated_at
        ) values (
          v_warehouse_id,
          v_slot.product_id,
          v_slot.quality_level,
          coalesce(v_slot.brand_id, '00000000-0000-0000-0000-000000000000'::uuid),
          v_slot.quantity,
          coalesce(v_slot.cost, 0),
          v_now,
          v_now
        );
      end if;
    end if;
  end if;

  update public.store_slots
  set
    product_id = null,
    brand_id = '00000000-0000-0000-0000-000000000000'::uuid,
    quality_level = 0,
    quantity = 0,
    price = 0,
    cost = 0,
    pending_sale = 0,
    pending_quantity = 0,
    updated_at = v_now
  where id = p_store_slot_id;

  return jsonb_build_object(
    'success', true,
    'store_slot_id', p_store_slot_id,
    'store_id', v_slot.store_id,
    'product_id', null,
    'brand_id', '00000000-0000-0000-0000-000000000000'::uuid,
    'quality_level', 0,
    'quantity', 0,
    'price', 0,
    'cost', 0,
    'pending_sale', 0
  );
end;
$function$;

-- Function: complete_arge_research
CREATE OR REPLACE FUNCTION public.complete_arge_research(p_research_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_research arge_researches%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_exp_result jsonb;
begin
  select * into v_research
  from arge_researches
  where id = p_research_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Arastirma bulunamadi.');
  end if;

  if v_research.status <> 'in_progress' then
    return jsonb_build_object('success', false, 'message', 'Bu arastirma zaten tamamlanmis.');
  end if;

  if v_research.finish_at > v_now then
    return jsonb_build_object('success', false, 'message', 'Arastirma henuz tamamlanmadi.');
  end if;

  insert into player_product_quality_levels (player_id, product_id, max_quality_level, created_at, updated_at)
  values (v_research.player_id, v_research.product_id, v_research.target_quality, v_now, v_now)
  on conflict (player_id, product_id) do update
    set max_quality_level = excluded.max_quality_level, updated_at = v_now;

  update arge_researches
  set status = 'completed', completed_at = v_now
  where id = p_research_id;

  v_exp_result := public.grant_player_experience(
    v_research.player_id,
    public.calculate_experience_reward(
      'arge_research_completed',
      jsonb_build_object(
        'product_id', v_research.product_id,
        'target_quality', v_research.target_quality
      )
    ),
    'arge_research_completed',
    jsonb_build_object(
      'research_id', p_research_id,
      'product_id', v_research.product_id,
      'product_name', v_research.product_name,
      'target_quality', v_research.target_quality
    )
  );

  -- Ar-Ge Araştırma Bildirimi (Oyun İçi + Push)
  PERFORM public.send_game_notification(
    v_research.player_id,
    'Ar-Ge Tamamlandı!',
    v_research.product_name || ' ürünü Kalite Seviyesi ' || v_research.target_quality::text || ' araştırması başarıyla bitti.',
    'research',
    'arge',
    p_research_id,
    true
  );

  return jsonb_build_object(
    'success', true,
    'product_id', v_research.product_id,
    'product_name', v_research.product_name,
    'new_quality_level', v_research.target_quality,
    'experience', v_exp_result,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_research.player_id)
    )
  );
end;
$function$;

-- Function: complete_building_construction
CREATE OR REPLACE FUNCTION public.complete_building_construction(p_player_id uuid, p_construction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
  v_construction public.building_constructions%rowtype;
  v_created_id uuid;
  v_exp_result jsonb;
  v_building_display_name text;
begin
  select *
  into v_construction
  from public.building_constructions
  where id = p_construction_id
    and player_id = p_player_id
  for update;

  if not found then
    raise exception 'Insaat kaydi bulunamadi.';
  end if;

  if v_construction.status <> 'in_progress' then
    raise exception 'Bu insaat tamamlanabilir durumda degil.';
  end if;

  if v_construction.finish_at > v_now then
    raise exception 'Insaat henuz bitmedi.';
  end if;

  v_building_display_name := coalesce(v_construction.params->>'name', 'Yeni Tesis');

  if v_construction.building_kind = 'store' then
    insert into public.stores (
      player_id,
      store_type_id,
      city_id,
      name,
      level,
      current_slot_count,
      max_slot_count,
      slot_capacity,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'store_type_id')::uuid,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'current_slot_count')::integer, 0),
      coalesce((v_construction.params->>'max_slot_count')::integer, 0),
      coalesce((v_construction.params->>'slot_capacity')::integer, 0),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'warehouse' then
    insert into public.warehouses (
      player_id,
      city_id,
      name,
      level,
      capacity,
      reserved_capacity,
      warehouse_kind,
      store_id,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'capacity')::numeric, 0),
      0,
      coalesce(v_construction.params->>'warehouse_kind', 'general'),
      nullif(v_construction.params->>'store_id', '')::uuid,
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'factory' then
    insert into public.factories (
      player_id,
      factory_type_id,
      city_id,
      name,
      level,
      product_id,
      quality_level,
      input_capacity,
      output_capacity,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'factory_type_id')::uuid,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      null,
      coalesce((v_construction.params->>'quality_level')::integer, 0),
      coalesce((v_construction.params->>'input_capacity')::integer, 0),
      coalesce((v_construction.params->>'output_capacity')::integer, 0),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'field' then
    insert into public.fields (
      player_id,
      field_type_id,
      city_id,
      name,
      level,
      current_slot_count,
      max_slot_count,
      input_capacity,
      output_capacity,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'field_type_id')::uuid,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'current_slot_count')::integer, 0),
      coalesce((v_construction.params->>'max_slot_count')::integer, 0),
      coalesce((v_construction.params->>'input_capacity')::integer, 0),
      coalesce((v_construction.params->>'output_capacity')::integer, 0),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'farm' then
    insert into public.farms (
      player_id,
      farm_type_id,
      city_id,
      name,
      level,
      current_slot_count,
      max_slot_count,
      input_capacity,
      output_capacity,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'farm_type_id')::uuid,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'current_slot_count')::integer, 0),
      coalesce((v_construction.params->>'max_slot_count')::integer, 0),
      coalesce((v_construction.params->>'input_capacity')::integer, 0),
      coalesce((v_construction.params->>'output_capacity')::integer, 0),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'mine' then
    insert into public.mines (
      player_id,
      mine_type_id,
      city_id,
      name,
      level,
      product_id,
      quality_level,
      output_capacity,
      boost_multiplier,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'mine_type_id')::uuid,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      null,
      coalesce((v_construction.params->>'quality_level')::integer, 0),
      coalesce((v_construction.params->>'output_capacity')::integer, 0),
      coalesce((v_construction.params->>'boost_multiplier')::numeric, 1.00),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'logistics_company' then
    insert into public.logistics_companies (
      player_id,
      city_id,
      name,
      level,
      current_vehicle_count,
      max_vehicle_count,
      fuel_capacity,
      current_fuel,
      fuel_cost,
      is_active
    )
    values (
      p_player_id,
      (v_construction.params->>'city_id')::uuid,
      v_construction.params->>'name',
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'current_vehicle_count')::integer, 0),
      coalesce((v_construction.params->>'max_vehicle_count')::integer, 0),
      coalesce((v_construction.params->>'fuel_capacity')::integer, 0),
      coalesce((v_construction.params->>'current_fuel')::integer, 0),
      coalesce((v_construction.params->>'fuel_cost')::numeric, 0),
      true
    )
    returning id into v_created_id;
  elsif v_construction.building_kind = 'arge_center' then
    insert into public.arge_centers (
      player_id,
      name,
      level,
      max_concurrent_researches,
      duration_reduction_pct,
      is_active
    )
    values (
      p_player_id,
      coalesce(v_construction.params->>'name', 'AR-GE Merkezi'),
      coalesce((v_construction.params->>'level')::integer, 1),
      coalesce((v_construction.params->>'max_concurrent_researches')::integer, 1),
      coalesce((v_construction.params->>'duration_reduction_pct')::numeric, 0),
      true
    )
    returning id into v_created_id;
  else
    raise exception 'Gecersiz building_kind: %', v_construction.building_kind;
  end if;

  update public.building_constructions
  set
    status = 'complete',
    completed_at = v_now
  where id = p_construction_id;

  v_exp_result := public.grant_player_experience(
    p_player_id,
    public.calculate_experience_reward(
      'building_construction_completed',
      jsonb_build_object('building_kind', v_construction.building_kind)
    ),
    'building_construction_completed',
    jsonb_build_object(
      'construction_id', p_construction_id,
      'building_kind', v_construction.building_kind,
      'created_id', v_created_id
    )
  );

  -- İnşaat Tamamlanma Bildirimi (Oyun İçi + Push)
  PERFORM public.send_game_notification(
    p_player_id,
    'İnşaat Tamamlandı!',
    v_building_display_name || ' inşaatı tamamlandı ve hizmete açıldı.',
    'building',
    'construction',
    v_created_id,
    true
  );

  return jsonb_build_object(
    'success', true,
    'construction_id', p_construction_id,
    'building_kind', v_construction.building_kind,
    'created_id', v_created_id,
    'status', 'complete',
    'completed_at', v_now,
    'experience', v_exp_result,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(p_player_id)
    )
  );
end;
$function$;

-- Function: complete_building_upgrade
CREATE OR REPLACE FUNCTION public.complete_building_upgrade(p_player_id uuid, p_upgrade_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
  v_upgrade public.building_upgrades%rowtype;
  v_slot_capacity_increase integer := 0;
  v_max_slot_increase integer := 0;
  v_input_capacity_increase integer := 0;
  v_output_capacity_increase integer := 0;
  v_capacity_increase numeric := 0;
  v_exp_result jsonb;
  v_building_name text;
begin
  select * into v_upgrade from public.building_upgrades
  where id = p_upgrade_id and player_id = p_player_id for update;
  if not found then raise exception 'Yukseltme bulunamadi.'; end if;
  if v_upgrade.status <> 'in_progress' then raise exception 'Bu yukseltme tamamlanabilir durumda degil.'; end if;
  if v_upgrade.finish_at > v_now then raise exception 'Yukseltme henuz bitmedi.'; end if;

  if v_upgrade.building_kind = 'store' then
    v_building_name := 'Mağaza';
    v_slot_capacity_increase := coalesce((v_upgrade.params->>'slot_capacity_increase')::integer, 0);
    v_max_slot_increase := coalesce((v_upgrade.params->>'max_slot_increase')::integer, 0);
    update public.stores set level=v_upgrade.target_level,
      slot_capacity=slot_capacity+v_slot_capacity_increase,
      max_slot_count=max_slot_count+v_max_slot_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
    update public.store_slots set capacity=capacity+v_slot_capacity_increase, updated_at=v_now
    where store_id=v_upgrade.entity_id;
  elsif v_upgrade.building_kind = 'warehouse' then
    v_building_name := 'Depo';
    v_capacity_increase := coalesce((v_upgrade.params->>'capacity_increase')::numeric, 0);
    update public.warehouses set level=v_upgrade.target_level,
      capacity=capacity+v_capacity_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  elsif v_upgrade.building_kind = 'field' then
    v_building_name := 'Tarla';
    v_input_capacity_increase := coalesce((v_upgrade.params->>'input_capacity_increase')::integer, 0);
    v_output_capacity_increase := coalesce((v_upgrade.params->>'output_capacity_increase')::integer, 0);
    update public.fields set level=v_upgrade.target_level,
      input_capacity=input_capacity+v_input_capacity_increase,
      output_capacity=output_capacity+v_output_capacity_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  elsif v_upgrade.building_kind = 'farm' then
    v_building_name := 'Çiftlik';
    v_input_capacity_increase := coalesce((v_upgrade.params->>'input_capacity_increase')::integer, 0);
    v_output_capacity_increase := coalesce((v_upgrade.params->>'output_capacity_increase')::integer, 0);
    update public.farms set level=v_upgrade.target_level,
      input_capacity=input_capacity+v_input_capacity_increase,
      output_capacity=output_capacity+v_output_capacity_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  elsif v_upgrade.building_kind = 'factory' then
    v_building_name := 'Fabrika';
    v_input_capacity_increase := coalesce((v_upgrade.params->>'input_capacity_increase')::integer, 0);
    v_output_capacity_increase := coalesce((v_upgrade.params->>'output_capacity_increase')::integer, 0);
    update public.factories set level=v_upgrade.target_level,
      input_capacity=input_capacity+v_input_capacity_increase,
      output_capacity=output_capacity+v_output_capacity_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  elsif v_upgrade.building_kind = 'mine' then
    v_building_name := 'Maden';
    v_output_capacity_increase := coalesce((v_upgrade.params->>'output_capacity_increase')::integer, 0);
    update public.mines set level=v_upgrade.target_level,
      output_capacity=output_capacity+v_output_capacity_increase, updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  elsif v_upgrade.building_kind = 'arge_center' then
    v_building_name := 'Ar-Ge Merkezi';
    update public.arge_centers set level=v_upgrade.target_level,
      max_concurrent_researches=coalesce((v_upgrade.params->>'next_concurrent_researches')::integer,max_concurrent_researches),
      duration_reduction_pct=coalesce((v_upgrade.params->>'next_duration_reduction_pct')::numeric,duration_reduction_pct), updated_at=v_now
    where id=v_upgrade.entity_id and player_id=p_player_id;
  else raise exception 'Desteklenmeyen yukseltme turu: %', v_upgrade.building_kind;
  end if;

  if not found then raise exception 'Yukseltilecek isletme bulunamadi.'; end if;
  update public.building_upgrades set status='completed', completed_at=v_now, updated_at=v_now where id=p_upgrade_id;

  v_exp_result := public.grant_player_experience(
    p_player_id,
    public.calculate_experience_reward('building_upgrade_completed', jsonb_build_object('building_kind',v_upgrade.building_kind,'target_level',v_upgrade.target_level)),
    'building_upgrade_completed',
    jsonb_build_object('upgrade_id',p_upgrade_id,'building_kind',v_upgrade.building_kind,'entity_id',v_upgrade.entity_id,'target_level',v_upgrade.target_level)
  );

  -- Bildirim gönder (Oyun İçi + Push)
  PERFORM public.send_game_notification(
    p_player_id,
    'Yükseltme Tamamlandı',
    coalesce(v_building_name, 'Bina') || ' Seviye ' || v_upgrade.target_level::text || ' oldu!',
    'building',
    'building_upgrade',
    v_upgrade.entity_id,
    true
  );

  return jsonb_build_object('success',true,'upgrade_id',p_upgrade_id,'building_kind',v_upgrade.building_kind,
    'entity_id',v_upgrade.entity_id,'target_level',v_upgrade.target_level,
    'slot_capacity_increase',v_slot_capacity_increase,'max_slot_increase',v_max_slot_increase,
    'input_capacity_increase',v_input_capacity_increase,'output_capacity_increase',v_output_capacity_increase,
    'capacity_increase',v_capacity_increase,'completed_at',v_now,'experience',v_exp_result,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(p_player_id)
    )
  );
end;
$function$;

-- Function: complete_due_arge_researches
CREATE OR REPLACE FUNCTION public.complete_due_arge_researches()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row arge_researches%rowtype;
  v_count integer := 0;
begin
  for v_row in
    select * from arge_researches
    where status = 'in_progress' and finish_at <= timezone('utc', now())
    for update skip locked
  loop
    insert into player_product_quality_levels (player_id, product_id, max_quality_level, created_at, updated_at)
    values (v_row.player_id, v_row.product_id, v_row.target_quality, timezone('utc', now()), timezone('utc', now()))
    on conflict (player_id, product_id) DO UPDATE
      set max_quality_level = EXCLUDED.max_quality_level, updated_at = timezone('utc', now());

    update arge_researches
    set status = 'completed', completed_at = timezone('utc', now())
    where id = v_row.id;

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('success', true, 'completed_count', v_count);
end;
$function$;

-- Function: complete_due_building_boosts
CREATE OR REPLACE FUNCTION public.complete_due_building_boosts(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_result jsonb;
begin
  for v_row in
    select id, player_id
    from public.building_boosts
    where status = 'in_progress'
      and finish_at <= timezone('utc'::text, now())
    order by finish_at asc
    limit p_limit
    for update skip locked
  loop
    begin
      select public.finish_building_boost(v_row.player_id, v_row.id)
      into v_result;
      v_completed_count := v_completed_count + 1;
    exception when others then
      v_failed_count := v_failed_count + 1;
    end;
  end loop;

  return jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'failed_count', v_failed_count
  );
end;
$function$;

-- Function: complete_due_building_constructions
CREATE OR REPLACE FUNCTION public.complete_due_building_constructions(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_result jsonb;
begin
  for v_row in
    select
      id,
      player_id
    from public.building_constructions
    where status = 'in_progress'
      and finish_at <= timezone('utc'::text, now())
    order by finish_at asc
    limit p_limit
    for update skip locked
  loop
    begin
      select public.complete_building_construction(
        v_row.player_id,
        v_row.id
      )
      into v_result;

      v_completed_count := v_completed_count + 1;

    exception when others then
      v_failed_count := v_failed_count + 1;
    end;
  end loop;

  return jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'failed_count', v_failed_count
  );
end;
$function$;

