-- Function: complete_due_market_transfers
CREATE OR REPLACE FUNCTION public.complete_due_market_transfers(p_player_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row record;
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_result jsonb;
  v_tender_result jsonb;
BEGIN
  -- 1. Süresi dolmuş pazar ve lojistik transferlerini tamamla
  FOR v_row IN
    SELECT 
      id, 
      buyer_player_id
    FROM public.logistics_transfers
    WHERE status = 'in_transit'
      AND finish_at <= timezone('utc'::text, now())
      AND (p_player_id IS NULL OR buyer_player_id = p_player_id)
    ORDER BY finish_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_result := public.complete_logistics_transfer_internal(v_row.id, v_row.buyer_player_id);
      v_completed_count := v_completed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed_count := v_failed_count + 1;
    END;
  END LOOP;

  -- 2. Süresi dolmuş ihale teslimatlarını da otomatik tamamla
  BEGIN
    v_tender_result := public.process_tender_deliveries(p_player_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'failed_count', v_failed_count,
    'tender_deliveries_processed', v_tender_result
  );
END;
$function$;

-- Function: complete_due_player_building_boosts
CREATE OR REPLACE FUNCTION public.complete_due_player_building_boosts(p_player_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row record;
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_result jsonb;
BEGIN
  IF p_player_id IS NULL THEN
    RAISE EXCEPTION 'Oyuncu kimligi gerekli.';
  END IF;

  FOR v_row IN
    SELECT id
    FROM public.building_boosts
    WHERE player_id = p_player_id
      AND status = 'in_progress'
      AND finish_at <= timezone('utc'::text, now())
    ORDER BY finish_at, id
    LIMIT greatest(coalesce(p_limit, 100), 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      SELECT public.finish_building_boost(p_player_id, v_row.id)
      INTO v_result;
      v_completed_count := v_completed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed_count := v_failed_count + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'failed_count', v_failed_count
  );
END;
$function$;

-- Function: complete_due_player_building_upgrades
CREATE OR REPLACE FUNCTION public.complete_due_player_building_upgrades(p_player_id uuid, p_limit integer DEFAULT 100, p_building_kind text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row record;
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_result jsonb;
BEGIN
  IF p_player_id IS NULL THEN
    RAISE EXCEPTION 'Oyuncu kimligi gerekli.';
  END IF;

  FOR v_row IN
    SELECT id
    FROM public.building_upgrades
    WHERE player_id = p_player_id
      AND status = 'in_progress'
      AND finish_at <= timezone('utc'::text, now())
      AND (p_building_kind IS NULL OR building_kind = p_building_kind)
      AND (p_entity_id IS NULL OR entity_id = p_entity_id)
    ORDER BY finish_at, id
    LIMIT greatest(coalesce(p_limit, 100), 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      SELECT public.complete_building_upgrade(p_player_id, v_row.id)
      INTO v_result;
      v_completed_count := v_completed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed_count := v_failed_count + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'completed_count', v_completed_count,
    'failed_count', v_failed_count
  );
END;
$function$;

-- Function: complete_due_warehouse_upgrades
CREATE OR REPLACE FUNCTION public.complete_due_warehouse_upgrades(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.complete_due_building_upgrades(p_limit);
$function$;

-- Function: complete_logistics_transfer
CREATE OR REPLACE FUNCTION public.complete_logistics_transfer(p_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
BEGIN
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;
  return public.complete_logistics_transfer_internal(p_transfer_id, v_player_id);
END;
$function$;

-- Function: complete_logistics_transfer_internal
CREATE OR REPLACE FUNCTION public.complete_logistics_transfer_internal(p_transfer_id uuid, p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_default_brand uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_player_id uuid := p_player_id;
  v_now timestamptz := timezone('utc'::text, now());
  v_transfer logistics_transfers%rowtype;
  v_item logistics_transfer_items%rowtype;
  v_target_store_warehouse_id uuid;
  v_result jsonb;
  v_completed_count integer := 0;
  v_item_transport_cost numeric := 0;
  v_target_inventory record;
  v_total_existing_cost numeric := 0;
  v_total_incoming_cost numeric := 0;
  v_new_cost numeric := 0;
  v_transfer_exp integer := 0;
BEGIN
  if v_player_id is null then
    raise exception 'Oturum acilmamis.'; end if;

  select *
  into v_transfer
  from public.logistics_transfers
  where id = p_transfer_id
    and buyer_player_id = v_player_id
  for update;

  if not found then
    raise exception 'Transfer bulunamadi.';
  end if;

  if v_transfer.status = 'completed' then
    return jsonb_build_object(
      'success', true,
      'transfer_id', p_transfer_id,
      'completed_item_count', 0,
      'completed_at', coalesce(v_transfer.completed_at, v_now),
      'changed', jsonb_build_object(
        'player', public.get_player_profile(v_player_id)
      )
    );
  end if;

  if v_transfer.status <> 'in_transit' then
    raise exception 'Transfer tamamlanabilir durumda degil.';
  end if;

  if coalesce(v_transfer.finish_at, v_now) > v_now then
    raise exception 'Transfer henuz hedefe ulasmadi.';
  end if;

  if coalesce(v_transfer.buyer_entity_kind, '') = 'store' then
    select id
    into v_target_store_warehouse_id
    from public.warehouses
    where store_id = v_transfer.buyer_store_id
      and warehouse_kind = 'store'
      and is_active = true
    order by created_at desc
    limit 1
    for update;

    if not found then
      raise exception 'Hedef magazaya bagli depo bulunamadi.';
    end if;
  end if;

  for v_item in
    select *
    from public.logistics_transfer_items
    where transfer_id = p_transfer_id
      and status = 'in_transit'
    order by created_at, id
    for update
  loop
    v_item_transport_cost := case
      when coalesce(v_transfer.reserved_capacity_amount, 0) > 0
        and coalesce(v_item.reserved_capacity_amount, 0) > 0 then
        round(
          coalesce(v_transfer.transport_cost, 0)
          * (
            coalesce(v_item.reserved_capacity_amount, 0)
            / v_transfer.reserved_capacity_amount
          ),
          4
        )
      when coalesce(v_transfer.total_quantity, 0) > 0 then
        round(
          coalesce(v_transfer.transport_cost, 0)
          * (coalesce(v_item.quantity, 0)::numeric / v_transfer.total_quantity::numeric),
          4
        )
      else 0
    end;

    if coalesce(v_transfer.buyer_entity_kind, '') = 'warehouse' then
      v_result := public.add_product_to_warehouse_with_brand(
        v_player_id,
        v_transfer.buyer_warehouse_id,
        v_item.product_id,
        v_item.quality_level,
        coalesce(v_item.brand_id, v_default_brand),
        v_item.quantity,
        v_item.unit_cost,
        v_item_transport_cost,
        true,
        null
      );
    elsif coalesce(v_transfer.buyer_entity_kind, '') = 'store' then
      v_result := public.add_product_to_warehouse_with_brand(
        v_player_id,
        v_target_store_warehouse_id,
        v_item.product_id,
        v_item.quality_level,
        coalesce(v_item.brand_id, v_default_brand),
        v_item.quantity,
        v_item.unit_cost,
        v_item_transport_cost,
        false,
        v_item.target_warehouse_slot_id
      );
    elsif coalesce(v_transfer.buyer_entity_kind, '') = 'production_inventory' then
      select
        pi.*,
        case
          when pi.owner_kind = 'factory' then fx.player_id
          when pi.owner_kind = 'farm' then fa.player_id
          when pi.owner_kind = 'field' then fld.player_id
          when pi.owner_kind = 'mine' then m.player_id
          else null
        end as owner_player_id
      into v_target_inventory
      from public.production_inventory pi
      left join public.factories fx
        on pi.owner_kind = 'factory' and fx.id = pi.owner_id
      left join public.farms fa
        on pi.owner_kind = 'farm' and fa.id = pi.owner_id
      left join public.fields fld
        on pi.owner_kind = 'field' and fld.id = pi.owner_id
      left join public.mines m
        on pi.owner_kind = 'mine' and m.id = pi.owner_id
      where pi.id = coalesce(
        v_item.target_production_inventory_id,
        v_transfer.buyer_production_inventory_id
      )
      for update of pi;

      if not found then
        raise exception 'Hedef production envanteri bulunamadi.';
      end if;

      if v_target_inventory.owner_player_id <> v_player_id then
        raise exception 'Hedef production envanteri oyuncuya ait degil.';
      end if;

      if coalesce(v_target_inventory.product_id, '') <> coalesce(v_item.product_id, '') then
        raise exception 'Transfer urunu ile hedef production envanteri uyusmuyor.';
      end if;

      if coalesce(v_target_inventory.quality_level, 0) <> coalesce(v_item.quality_level, 0) then
        raise exception 'Transfer kalitesi ile hedef production envanteri uyusmuyor.';
      end if;

      if coalesce(v_target_inventory.inventory_type, '') <> 'input'
         and coalesce(v_target_inventory.brand_id, v_default_brand) <> coalesce(v_item.brand_id, v_default_brand) then
        raise exception 'Transfer brandi ile hedef production envanteri uyusmuyor.';
      end if;

      v_total_existing_cost := coalesce(v_target_inventory.quantity, 0) * coalesce(v_target_inventory.cost, 0);
      v_total_incoming_cost := (coalesce(v_item.quantity, 0) * coalesce(v_item.unit_cost, 0)) + coalesce(v_item_transport_cost, 0);
      v_new_cost := case
        when coalesce(v_target_inventory.quantity, 0) + coalesce(v_item.quantity, 0) <= 0 then coalesce(v_target_inventory.cost, 0)
        else round(
          (v_total_existing_cost + v_total_incoming_cost)
          / (coalesce(v_target_inventory.quantity, 0) + coalesce(v_item.quantity, 0)),
          4
        )
      end;

      update public.production_inventory
      set
        quantity = quantity + v_item.quantity,
        pending_quantity = greatest(coalesce(pending_quantity, 0) - v_item.quantity, 0),
        cost = v_new_cost
      where id = v_target_inventory.id;
    else
      raise exception 'Desteklenmeyen hedef turu: %', v_transfer.buyer_entity_kind;
    end if;

    update public.logistics_transfer_items
    set
      status = 'completed',
      completed_at = v_now,
      updated_at = v_now
    where id = v_item.id;

    v_completed_count := v_completed_count + 1;
  end loop;

  update public.logistics_transfers
  set
    status = 'completed',
    completed_at = v_now,
    updated_at = v_now
  where id = p_transfer_id;

  if v_transfer.logistics_vehicle_id is not null then
    update public.logistics_vehicles
    set
      status = 'idle',
      updated_at = v_now
    where id = v_transfer.logistics_vehicle_id;
  end if;

  -- Transfer Tamamlanma XP Ödülü
  v_transfer_exp := greatest(10, least(80, 10 + floor(coalesce(v_transfer.total_quantity, 0)::numeric / 10)::integer));
  perform public.grant_player_experience(
    v_player_id,
    v_transfer_exp,
    'logistics_transfer_completed',
    jsonb_build_object(
      'transfer_id', p_transfer_id,
      'total_quantity', v_transfer.total_quantity
    )
  );

  -- Bildirim gönder (Oyun İçi + Push)
  PERFORM public.send_game_notification(
    v_player_id,
    'Sevkiyat Ulaştı',
    coalesce(v_transfer.total_quantity, 0)::text || ' adet ürün hedefe başarıyla teslim edildi.',
    'logistics',
    'transfer',
    p_transfer_id,
    true
  );

  return jsonb_build_object(
    'success', true,
    'transfer_id', p_transfer_id,
    'completed_item_count', v_completed_count,
    'exp_gained', v_transfer_exp,
    'completed_at', v_now,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id)
    )
  );
END;
$function$;

-- Function: complete_player_tender
CREATE OR REPLACE FUNCTION public.complete_player_tender(p_player_tender_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_tender public.player_tenders%rowtype;
  v_player_cash numeric := 0;
  v_payout numeric := 0;
  v_tender_title text := 'Ihale';
  v_tender_exp integer := 0;
begin
  select *
  into v_player_tender
  from public.player_tenders
  where id = p_player_tender_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Oyuncu ihalesi bulunamadi.');
  end if;

  if v_player_tender.status <> 'active' then
    return jsonb_build_object('success', false, 'message', 'Ihale aktif degil.');
  end if;

  if v_player_tender.delivered_quantity < v_player_tender.required_quantity then
    return jsonb_build_object('success', false, 'message', 'Teslim miktari henuz yeterli degil.');
  end if;

  select cash
  into v_player_cash
  from public.players
  where id = v_player_tender.player_id
  for update;

  select coalesce(t.title, 'Ihale')
  into v_tender_title
  from public.tenders t
  where t.id = v_player_tender.tender_id;

  v_payout := v_player_tender.reward_cash + v_player_tender.bond_paid;

  update public.player_tenders
  set status = 'completed',
      completed_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where id = v_player_tender.id;

  update public.players
  set cash = cash + v_payout
  where id = v_player_tender.player_id;

  perform public.log_player_cash_change(
    v_player_tender.player_id,
    v_player_tender.reward_cash,
    v_player_cash,
    'tender_reward_paid',
    format('Ihale odulu kazanildi. Tender: %s', v_player_tender.tender_id),
    v_player_tender.id,
    'player_tender'
  );

  perform public.log_player_cash_change(
    v_player_tender.player_id,
    v_player_tender.bond_paid,
    v_player_cash + v_player_tender.reward_cash,
    'tender_bond_refunded',
    format('Ihale teminati iade edildi. Tender: %s', v_player_tender.tender_id),
    v_player_tender.id,
    'player_tender'
  );

  v_tender_exp := greatest(200, least(1500, 200 + floor(v_player_tender.reward_cash / 10000)::integer + floor(v_player_tender.required_quantity / 10)::integer));
  perform public.grant_player_experience(
    v_player_tender.player_id,
    v_tender_exp,
    'tender_completed',
    jsonb_build_object(
      'tender_id', v_player_tender.tender_id,
      'player_tender_id', v_player_tender.id,
      'reward_cash', v_player_tender.reward_cash,
      'required_quantity', v_player_tender.required_quantity
    )
  );

  -- İhale Tamamlanma Bildirimi (Oyun İçi + Push)
  PERFORM public.send_game_notification(
    v_player_tender.player_id,
    'İhale Teslimatı Tamamlandı!',
    v_tender_title || ' ihalesi başarıyla tamamlandı. Kazanç: ' || round(v_payout, 0)::text || ' TL',
    'trade',
    'tender',
    v_player_tender.id,
    true
  );

  return jsonb_build_object(
    'success', true,
    'player_tender_id', v_player_tender.id,
    'status', 'completed',
    'payout', v_payout,
    'exp_gained', v_tender_exp,
    'message', 'Ihale tamamlandi.'
  );
end;
$function$;

-- Function: consume_rewarded_ad_usage_v2
CREATE OR REPLACE FUNCTION public.consume_rewarded_ad_usage_v2(p_player_id uuid, p_reward_kind text, p_cooldown_seconds integer, p_daily_limit integer, p_metadata jsonb DEFAULT '{}'::jsonb, p_resource_key text DEFAULT NULL::text, p_resource_value text DEFAULT NULL::text, p_resource_daily_limit integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := timezone('utc'::text, now());
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_last_used_at timestamptz;
  v_global_count integer;
  v_kind_count integer;
  v_resource_count integer;
BEGIN
  IF p_player_id IS NULL OR p_player_id <> auth.uid() THEN
    RAISE EXCEPTION 'Gecersiz oyuncu.';
  END IF;

  -- Serialize all rewards for one player so parallel requests cannot bypass limits.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_player_id::text, 0));

  v_day_start := date_trunc('day', timezone('Europe/Istanbul', v_now))
    AT TIME ZONE 'Europe/Istanbul';
  v_day_end := v_day_start + interval '1 day';

  SELECT count(*)::integer
  INTO v_global_count
  FROM public.player_rewarded_ad_usages
  WHERE player_id = p_player_id
    AND created_at >= v_day_start
    AND created_at < v_day_end;

  IF v_global_count >= 15 THEN
    RAISE EXCEPTION 'Bugunku toplam 15 reklam odulu limitine ulastin. Yarin tekrar kullanabilirsin.';
  END IF;

  SELECT count(*)::integer, max(created_at)
  INTO v_kind_count, v_last_used_at
  FROM public.player_rewarded_ad_usages
  WHERE player_id = p_player_id
    AND reward_kind = p_reward_kind
    AND created_at >= v_day_start
    AND created_at < v_day_end;

  IF v_kind_count >= GREATEST(p_daily_limit, 0) THEN
    RAISE EXCEPTION 'Bu reklam odulu icin bugunku % kullanim hakkini doldurdun.', p_daily_limit;
  END IF;

  IF p_resource_key IS NOT NULL
     AND p_resource_value IS NOT NULL
     AND p_resource_daily_limit IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_resource_count
    FROM public.player_rewarded_ad_usages
    WHERE player_id = p_player_id
      AND reward_kind = p_reward_kind
      AND created_at >= v_day_start
      AND created_at < v_day_end
      AND metadata ->> p_resource_key = p_resource_value;

    IF v_resource_count >= GREATEST(p_resource_daily_limit, 0) THEN
      RAISE EXCEPTION 'Bu islem icin bugunku reklam odulu hakkini doldurdun. Baska bir islemde kullanabilir veya yarini bekleyebilirsin.';
    END IF;
  END IF;

  IF v_last_used_at IS NOT NULL
     AND EXTRACT(EPOCH FROM (v_now - v_last_used_at)) < GREATEST(p_cooldown_seconds, 0) THEN
    RAISE EXCEPTION 'Yeni reklam odulu icin % saniye beklemelisin.',
      CEIL(GREATEST(p_cooldown_seconds, 0) - EXTRACT(EPOCH FROM (v_now - v_last_used_at)))::integer;
  END IF;

  INSERT INTO public.player_rewarded_ad_usages (player_id, reward_kind, metadata)
  VALUES (p_player_id, p_reward_kind, coalesce(p_metadata, '{}'::jsonb));

  RETURN v_kind_count + 1;
END;
$function$;

-- Function: create_brand_company
CREATE OR REPLACE FUNCTION public.create_brand_company(p_brand_name text, p_logo_id text DEFAULT NULL::text, p_theme_color text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_brand_company public.brand_companies%rowtype;
  v_clean_name text;
  v_lower_name text;
  v_similar_record record;
  v_len integer;
BEGIN
  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Oturum açılmamış.';
  END IF;

  -- 1. Check if player already has a brand company
  SELECT *
  INTO v_brand_company
  FROM public.brand_companies
  WHERE player_id = v_player_id
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Zaten aktif bir marka şirketiniz bulunmaktadır.';
  END IF;

  -- 2. Clean & normalize name (strip double spaces, trim)
  v_clean_name := btrim(regexp_replace(COALESCE(p_brand_name, ''), '\\s+', ' ', 'g'));
  v_len := char_length(v_clean_name);

  -- 3. Length validation
  IF v_len < 3 THEN
    RAISE EXCEPTION 'Marka adı çok kısa. En az 3 karakterden oluşmalıdır.';
  END IF;

  IF v_len > 24 THEN
    RAISE EXCEPTION 'Marka adı çok uzun. En fazla 24 karakter olabilir.';
  END IF;

  -- 4. Character set validation (Only Turkish/Latin letters, digits and spaces)
  IF v_clean_name !~* '^[a-z0-9çğışöüÇĞİŞÖÜ ]+$' THEN
    RAISE EXCEPTION 'Marka adında yalnızca harf, rakam ve boşluk kullanılabilir. Özel semboller, noktalama işaretleri veya emojiler kullanılamaz.';
  END IF;

  v_lower_name := lower(v_clean_name);

  -- 5. Reserved / Official Names Check
  IF v_lower_name IN (
    'admin', 'administrator', 'sistem', 'system', 'hard kapitalizm', 'kapitalizm',
    'merkez bankasi', 'merkez bankası', 'devlet', 'resmi', 'official', 'destek',
    'support', 'npc', 'toptan ticaret', 'belediye', 'bakanlik', 'bakanlık',
    'moderator', 'mod', 'türkiye', 'turkiye', 'hazine', 'maliye'
  ) OR v_lower_name LIKE 'admin%' OR v_lower_name LIKE 'sistem%' THEN
    RAISE EXCEPTION 'Bu marka adı resmi kurumlar ve sistem için rezerve edilmiştir. Lütfen şirketiniz için özgün bir marka adı seçin.';
  END IF;

  -- 6. Exact duplicate check (case-insensitive)
  IF EXISTS (
    SELECT 1 FROM public.brand_companies
    WHERE lower(btrim(brand_name)) = v_lower_name
      AND is_active = true
  ) THEN
    RAISE EXCEPTION '"%" marka adı daha önce başka bir holding tarafından tescil edilmiş. Lütfen farklı ve benzersiz bir marka adı seçin.', v_clean_name;
  END IF;

  -- 7. Knock-off / Fuzzy similarity check against existing brands
  SELECT
    brand_name,
    similarity(lower(brand_name), v_lower_name) AS sim,
    levenshtein(lower(brand_name), v_lower_name) AS dist
  INTO v_similar_record
  FROM public.brand_companies
  WHERE is_active = true
    AND (
      similarity(lower(brand_name), v_lower_name) >= 0.72
      OR (char_length(brand_name) <= 5 AND levenshtein(lower(brand_name), v_lower_name) <= 1)
      OR (char_length(brand_name) > 5 AND levenshtein(lower(brand_name), v_lower_name) <= 2)
    )
  ORDER BY similarity(lower(brand_name), v_lower_name) DESC
  LIMIT 1;

  IF v_similar_record.brand_name IS NOT NULL THEN
    RAISE EXCEPTION 'Belirlediğiniz marka adı tescilli "%" markasına aşırı derecede benzemektedir. Marka taklitçiliğini ve haksız rekabeti önlemek adına lütfen daha özgün bir isim seçin.', v_similar_record.brand_name;
  END IF;

  -- 8. Insert new brand company
  INSERT INTO public.brand_companies (
    player_id,
    brand_name,
    is_active,
    logo_id,
    theme_color,
    brand_level,
    brand_xp
  ) VALUES (
    v_player_id,
    v_clean_name,
    true,
    COALESCE(p_logo_id, 'logo_1.png'),
    COALESCE(p_theme_color, '#E5C05C'),
    1,
    0
  )
  RETURNING * INTO v_brand_company;

  RETURN jsonb_build_object(
    'success', true,
    'message', format('"%s" marka şirketiniz başarıyla tescillendi ve koruma altına alındı.', v_brand_company.brand_name),
    'brand_company_id', v_brand_company.id,
    'brand_name', v_brand_company.brand_name,
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id)
    )
  );
END;
$function$;

-- Function: create_deposit
CREATE OR REPLACE FUNCTION public.create_deposit(p_amount numeric, p_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_current_cash numeric;
  v_max_deposit_limit numeric;
  v_active_deposits_total numeric;
  v_interest_rate numeric;
  v_expected_payout numeric;
  v_deposit_id uuid;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  if p_amount <= 0 then
    return jsonb_build_object('success', false, 'message', 'Gecersiz mevduat tutari.');
  end if;

  -- Temerrut kontrolu: Borcu olan mevduat acamaz
  if exists (
    select 1 from public.player_loans
    where player_id = v_player_id and status = 'defaulted'
  ) then
    return jsonb_build_object(
      'success', false,
      'message', 'Gecikmiş kredi borcunuz bulunmaktadır. Vadeli mevduat hesabı açabilmek için lütfen önce kredi borcunuzu kapatınız.'
    );
  end if;

  if p_days not in (1, 3, 7) then
    return jsonb_build_object('success', false, 'message', 'Gecersiz vade secenegi. (Sadece 1, 3 veya 7 gun secilebilir)');
  end if;

  if p_days = 1 then v_interest_rate := 0.01;
  elsif p_days = 3 then v_interest_rate := 0.04;
  else v_interest_rate := 0.10;
  end if;

  select cash into v_current_cash from public.players where id = v_player_id for update;
  if v_current_cash is null then
    return jsonb_build_object('success', false, 'message', 'Oyuncu bulunamadi.');
  end if;

  if v_current_cash < p_amount then
    return jsonb_build_object('success', false, 'message', 'Yetersiz nakit bakiye.');
  end if;

  -- Maksimum mevduat limiti kontrolu
  v_max_deposit_limit := public.get_player_max_deposit_limit(v_player_id);
  select coalesce(sum(amount), 0) into v_active_deposits_total
  from public.player_deposits
  where player_id = v_player_id and status = 'active';

  if (v_active_deposits_total + p_amount) > v_max_deposit_limit then
    return jsonb_build_object(
      'success', false,
      'message', format('Mevduat üst limiti aşıldı. Maksimum mevduat limitiniz: %s TL. Kalan limitiniz: %s TL.', round(v_max_deposit_limit, 0), round(greatest(0, v_max_deposit_limit - v_active_deposits_total), 0))
    );
  end if;

  v_expected_payout := p_amount * (1.0 + v_interest_rate);
  v_deposit_id := gen_random_uuid();

  insert into public.player_deposits (
    id, player_id, amount, interest_rate, expected_payout,
    locked_until, status
  ) values (
    v_deposit_id, v_player_id, p_amount, v_interest_rate, v_expected_payout,
    now() + (p_days * interval '24 hours'), 'active'
  );

  update public.players
  set cash = cash - p_amount
  where id = v_player_id;

  perform public.log_player_cash_change(
    v_player_id,
    -p_amount,
    v_current_cash,
    'deposit_placed',
    format('%s TL Vadeli Mevduat Hesabi Acildi (%s Gun, %%%s Getiri)', round(p_amount, 2), p_days, round(v_interest_rate * 100, 0)),
    v_deposit_id,
    'deposit'
  );

  return jsonb_build_object(
    'success', true,
    'message', format('%s TL tutarında vadeli mevduat hesabı açıldı.', round(p_amount, 2)),
    'deposit_id', v_deposit_id,
    'expected_payout', v_expected_payout,
    'locked_until', now() + (p_days * interval '24 hours'),
    'changed', jsonb_build_object(
      'player', public.get_player_profile(v_player_id)
    )
  );
end;
$function$;

-- Function: delete_own_account
CREATE OR REPLACE FUNCTION public.delete_own_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_id uuid;
  v_npc_id uuid;
BEGIN
  -- 1. Get authenticated user ID
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Oturum açılmamış.');
  END IF;

  -- 2. Ensure NPC logistics account exists for transfer handoff
  v_npc_id := public.get_npc_logistics_player_id();

  -- 3. Clean up personal push tokens
  DELETE FROM public.player_push_tokens WHERE player_id = v_user_id;

  -- 4. Hand off in-transit transfers to NPC to protect buyer's cargo & economy integrity
  UPDATE public.logistics_transfers
  SET seller_player_id = v_npc_id
  WHERE seller_player_id = v_user_id AND status = 'in_transit';

  UPDATE public.logistics_transfers
  SET vehicle_owner_player_id = v_npc_id
  WHERE vehicle_owner_player_id = v_user_id AND status = 'in_transit';

  -- 5. Close market listings (prevent ghost purchases)
  UPDATE public.warehouse_slots
  SET is_available_for_sale = false, price = 0
  WHERE warehouse_id IN (SELECT id FROM public.warehouses WHERE player_id = v_user_id);

  -- 6. Decommission player-owned facilities & free city real estate
  UPDATE public.factories SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.fields SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.farms SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.mines SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.warehouses SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.stores SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.logistics_companies SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.logistics_vehicles SET status = 'decommissioned', is_available_for_rent = false WHERE player_id = v_user_id;
  UPDATE public.arge_centers SET is_active = false WHERE player_id = v_user_id;
  UPDATE public.brand_companies SET is_active = false WHERE player_id = v_user_id;

  -- 7. Liquidate ongoing constructions, upgrades and active bank products
  DELETE FROM public.building_boosts WHERE player_id = v_user_id;
  DELETE FROM public.building_upgrades WHERE player_id = v_user_id;
  DELETE FROM public.building_constructions WHERE player_id = v_user_id;
  DELETE FROM public.tender_bids WHERE player_id = v_user_id;

  UPDATE public.player_loans
  SET status = 'liquidated'
  WHERE player_id = v_user_id;

  UPDATE public.player_deposits
  SET status = 'liquidated'
  WHERE player_id = v_user_id;

  -- 8. Anonymize world player profile
  UPDATE public.players
  SET
    player_name = 'Eski Oyuncu',
    company_name = 'Tasfiye Edilmiş Holding',
    google_email = NULL,
    google_avatar_url = NULL,
    avatar_id = 'ae1.webp',
    cash = 0,
    gold = 0,
    last_seen_at = NULL
  WHERE id = v_user_id;

  -- 9. Permanently delete auth.users identity record
  DELETE FROM auth.users WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Hesabınız ve kişisel verileriniz başarıyla silindi. Şirketiniz tasfiye edildi.'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', format('Hesap silinirken hata oluştu: %s', SQLERRM));
END;
$function$;

-- Function: delete_warehouse_slot
CREATE OR REPLACE FUNCTION public.delete_warehouse_slot(p_player_id uuid, p_warehouse_slot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot record;
begin
  select
    ws.*,
    w.player_id
  into v_slot
  from public.warehouse_slots ws
  join public.warehouses w on w.id = ws.warehouse_id
  where ws.id = p_warehouse_slot_id
  for update;

  if not found then
    raise exception 'Depo slotu bulunamadi.';
  end if;

  if v_slot.player_id <> p_player_id then
    raise exception 'Bu depo slotu oyuncuya ait degil.';
  end if;

  if coalesce(v_slot.quantity, 0) > 0 then
    raise exception 'Sadece bos slotlar silinebilir.';
  end if;

  delete from public.warehouse_slots
  where id = p_warehouse_slot_id;

  return jsonb_build_object(
    'success', true,
    'warehouse_id', v_slot.warehouse_id,
    'warehouse_slot_id', p_warehouse_slot_id,
    'message', 'Slot basariyla silindi.'
  );
end;
$function$;

-- Function: discard_warehouse_slot
CREATE OR REPLACE FUNCTION public.discard_warehouse_slot(p_player_id uuid, p_warehouse_slot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_slot record;
begin
  if p_player_id is null or p_player_id <> auth.uid() then
    raise exception 'Gecersiz oyuncu.';
  end if;

  select
    ws.*,
    w.player_id,
    w.id as warehouse_id
  into v_slot
  from public.warehouse_slots ws
  join public.warehouses w on w.id = ws.warehouse_id
  where ws.id = p_warehouse_slot_id
  for update;

  if not found then
    raise exception 'Depo slotu bulunamadi.';
  end if;

  if v_slot.player_id <> p_player_id then
    raise exception 'Bu depo slotu oyuncuya ait degil.';
  end if;

  if coalesce(v_slot.pending_quantity, 0) > 0 then
    raise exception 'Transfer asamasindaki urunler cope atilamaz.';
  end if;

  delete from public.warehouse_slots
  where id = p_warehouse_slot_id;

  return jsonb_build_object(
    'success', true,
    'warehouse_id', v_slot.warehouse_id,
    'warehouse_slot_id', p_warehouse_slot_id,
    'discarded_quantity', coalesce(v_slot.quantity, 0),
    'product_id', v_slot.product_id,
    'message', 'Urun basariyla cope atildi.'
  );
end;
$function$;

-- Function: ensure_npc_logistics_account
CREATE OR REPLACE FUNCTION public.ensure_npc_logistics_account()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_npc_id uuid := '6e085b80-5c09-4efa-949f-c58daf1fb9e6'::uuid;
  v_city_id uuid;
  v_logistics_id uuid;
BEGIN
  -- 1. Ensure game_settings has the key
  INSERT INTO public.game_settings (key, value_text, description, updated_at)
  VALUES (
    'npc_logistics_player_id',
    v_npc_id::text,
    'Kiralik NPC lojistik fallback oyuncu hesabi.',
    now()
  )
  ON CONFLICT (key) DO UPDATE
  SET value_text = v_npc_id::text, updated_at = now();

  -- 2. Pick any valid city ID
  SELECT id INTO v_city_id FROM public.cities ORDER BY id LIMIT 1;

  -- 3. Ensure auth.users has the NPC user
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_npc_id) THEN
    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
      created_at, updated_at
    ) VALUES (
      v_npc_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      'npc-logistics@hardkapitalizm.local',
      '$2a$10$Defau1tNPCHashPasswordNeverUsed12345678901234567890123',
      now(),
      '{"provider":"email","providers":["email"]}',
      '{"player_name":"NPC Lojistik Ticaret"}',
      now(),
      now()
    );
  END IF;

  -- 4. Ensure public.players has the NPC player
  IF NOT EXISTS (SELECT 1 FROM public.players WHERE id = v_npc_id) THEN
    INSERT INTO public.players (
      id, player_name, company_name, avatar_id,
      headquarters_city_id, level, experience, cash, gold, created_at
    ) VALUES (
      v_npc_id,
      'NPC Lojistik Ticaret',
      'Devlet Lojistik Kurumu',
      'ae1.webp',
      v_city_id,
      99,
      9999999,
      999999999,
      999999,
      now()
    );
  END IF;

  -- 5. Ensure public.logistics_companies has the NPC company
  SELECT id INTO v_logistics_id FROM public.logistics_companies WHERE player_id = v_npc_id LIMIT 1;
  IF v_logistics_id IS NULL THEN
    INSERT INTO public.logistics_companies (
      player_id, name, is_active, created_at, updated_at
    ) VALUES (
      v_npc_id,
      'Devlet Lojistik Filosu',
      true,
      now(),
      now()
    )
    RETURNING id INTO v_logistics_id;
  END IF;

  RETURN v_npc_id;
END;
$function$;

-- Function: ensure_npc_rental_vehicle
CREATE OR REPLACE FUNCTION public.ensure_npc_rental_vehicle(p_from_city_id uuid, p_to_city_id uuid, p_vehicle_type_id uuid)
 RETURNS logistics_vehicles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_npc_player_id uuid;
  v_company_id uuid;
  v_vehicle_type record;
  v_vehicle public.logistics_vehicles%rowtype;
  v_city_a uuid;
  v_city_b uuid;
  v_now timestamptz := timezone('utc'::text, now());
  v_rental_price numeric := 2.0;
begin
  if p_from_city_id is null or p_to_city_id is null or p_from_city_id = p_to_city_id then
    raise exception 'NPC fallback araci icin gecersiz rota sehirleri.';
  end if;

  if p_from_city_id::text <= p_to_city_id::text then
    v_city_a := p_from_city_id;
    v_city_b := p_to_city_id;
  else
    v_city_a := p_to_city_id;
    v_city_b := p_from_city_id;
  end if;

  v_npc_player_id := public.get_npc_logistics_player_id();

  select lc.id
  into v_company_id
  from public.logistics_companies lc
  where lc.player_id = v_npc_player_id
  order by lc.created_at asc
  limit 1;

  if v_company_id is null then
    insert into public.logistics_companies (
      player_id,
      city_id,
      name,
      level,
      current_vehicle_count,
      max_vehicle_count,
      fuel_capacity,
      current_fuel,
      fuel_cost,
      is_active,
      created_at,
      updated_at
    )
    values (
      v_npc_player_id,
      v_city_a,
      'Atlas Lojistik',
      99,
      0,
      9999,
      999999,
      999999,
      0,
      true,
      v_now,
      v_now
    )
    returning id into v_company_id;
  else
    update public.logistics_companies
    set
      city_id = coalesce(city_id, v_city_a),
      level = greatest(coalesce(level, 1), 99),
      max_vehicle_count = greatest(coalesce(max_vehicle_count, 0), 9999),
      fuel_capacity = greatest(coalesce(fuel_capacity, 0), 999999),
      current_fuel = greatest(coalesce(current_fuel, 0), 999999),
      fuel_cost = 0,
      is_active = true,
      updated_at = v_now
    where id = v_company_id;
  end if;

  select
    lvt.id,
    coalesce(lvt.capacity, 250) as capacity,
    coalesce(lvt.speed_kmh, 60) as speed_kmh,
    coalesce(lvt.fuel_capacity, 60) as fuel_capacity,
    coalesce(lvt.fuel_rate, 0.02) as fuel_rate,
    coalesce(lvt.name, 'Kiralik Arac') as name
  into v_vehicle_type
  from public.logistics_vehicle_types lvt
  where lvt.id = p_vehicle_type_id;

  if v_vehicle_type.id is null then
    raise exception 'NPC fallback araci icin vehicle type bulunamadi.';
  end if;

  -- Load rental price dynamically from game_settings
  select coalesce(value_text::numeric, 2.0)
  into v_rental_price
  from public.game_settings
  where key = 'npc_rental_price_' || v_vehicle_type.name;

  v_rental_price := coalesce(v_rental_price, 2.0);

  select lv.*
  into v_vehicle
  from public.logistics_vehicles lv
  where lv.player_id = v_npc_player_id
    and lv.logistics_company_id = v_company_id
    and lv.logistics_vehicle_type_id = p_vehicle_type_id
    and lv.is_available_for_rent = true
    and lv.status = 'idle'
    and (
      (lv.route_city_a_id = v_city_a and lv.route_city_b_id = v_city_b)
      or (lv.route_city_a_id = v_city_b and lv.route_city_b_id = v_city_a)
    )
  order by lv.created_at asc
  limit 1
  for update;

  if found then
    update public.logistics_vehicles
    set
      capacity = v_vehicle_type.capacity,
      speed_kmh = v_vehicle_type.speed_kmh,
      fuel_capacity = v_vehicle_type.fuel_capacity,
      current_fuel = v_vehicle_type.fuel_capacity,
      fuel_rate = v_vehicle_type.fuel_rate,
      condition = 100,
      status = 'idle',
      is_available_for_rent = true,
      rental_price = v_rental_price,
      route_city_a_id = v_city_a,
      route_city_b_id = v_city_b,
      updated_at = v_now
    where id = v_vehicle.id
    returning * into v_vehicle;

    return v_vehicle;
  end if;

  insert into public.logistics_vehicles (
    player_id,
    logistics_company_id,
    logistics_vehicle_type_id,
    capacity,
    speed_kmh,
    fuel_capacity,
    current_fuel,
    fuel_rate,
    condition,
    status,
    is_available_for_rent,
    rental_price,
    route_city_a_id,
    route_city_b_id,
    created_at,
    updated_at
  )
  values (
    v_npc_player_id,
    v_company_id,
    v_vehicle_type.id,
    v_vehicle_type.capacity,
    v_vehicle_type.speed_kmh,
    v_vehicle_type.fuel_capacity,
    v_vehicle_type.fuel_capacity,
    v_vehicle_type.fuel_rate,
    100,
    'idle',
    true,
    v_rental_price,
    v_city_a,
    v_city_b,
    v_now,
    v_now
  )
  returning * into v_vehicle;

  update public.logistics_companies
  set
    current_vehicle_count = coalesce(current_vehicle_count, 0) + 1,
    updated_at = v_now
  where id = v_company_id;

  return v_vehicle;
end;
$function$;

-- Function: ensure_open_tenders
CREATE OR REPLACE FUNCTION public.ensure_open_tenders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc'::text, now());
  v_expired_count integer := 0;
  v_closed_count integer := 0;
  v_tender public.tenders%rowtype;
  v_winning_bid public.tender_bids%rowtype;
  v_losing_bid public.tender_bids%rowtype;
  v_player_tender_id uuid;
  v_deadline_at timestamptz;
  v_player_cash numeric;
begin
  for v_tender in
    select * from public.tenders
    where status = 'open' and accept_until <= v_now
    order by accept_until asc
    for update
  loop
    if v_tender.award_type = 'first_claim' then
      update public.tenders
      set status = 'expired', updated_at = v_now
      where id = v_tender.id;
      v_expired_count := v_expired_count + 1;
      continue;
    end if;

    select * into v_winning_bid
    from public.tender_bids tb
    where tb.tender_id = v_tender.id
      and tb.status = 'active'
    order by tb.bid_amount asc, tb.submitted_at asc, tb.created_at asc
    limit 1
    for update;

    if not found then
      update public.tenders
      set status = 'expired', updated_at = v_now
      where id = v_tender.id;
      v_expired_count := v_expired_count + 1;
      continue;
    end if;

    v_deadline_at := v_now + make_interval(mins => v_tender.delivery_duration_minutes);

    insert into public.player_tenders (
      player_id, tender_id, accepted_at, deadline_at, bond_paid, required_quantity,
      delivered_quantity, reward_cash, product_id, quality_level, city_id, status
    )
    values (
      v_winning_bid.player_id, v_tender.id, v_now, v_deadline_at, v_winning_bid.bond_paid,
      v_tender.required_quantity, 0, v_winning_bid.bid_amount, v_tender.product_id,
      v_tender.quality_level, v_tender.city_id, 'active'
    )
    returning id into v_player_tender_id;

    update public.tender_bids
    set status = 'won', resolved_at = v_now, updated_at = v_now
    where id = v_winning_bid.id;

    update public.tenders
    set status = 'closed', updated_at = v_now
    where id = v_tender.id;

    -- İhale Kazanma Bildirimi (Oyun İçi + Push)
    PERFORM public.send_game_notification(
      v_winning_bid.player_id,
      'İhaleyi Kazandınız!',
      coalesce(v_tender.title, 'İhale') || ' sözleşmesi size verildi. Teklif bedeli: ' || round(v_winning_bid.bid_amount, 0)::text || ' TL',
      'trade',
      'tender',
      v_player_tender_id,
      true
    );

    for v_losing_bid in
      select * from public.tender_bids tb
      where tb.tender_id = v_tender.id
        and tb.status = 'active'
        and tb.id <> v_winning_bid.id
      for update
    loop
      select cash into v_player_cash from public.players where id = v_losing_bid.player_id for update;
      update public.players set cash = cash + v_losing_bid.bond_paid where id = v_losing_bid.player_id;
      update public.tender_bids
      set status = 'lost', resolved_at = v_now, updated_at = v_now
      where id = v_losing_bid.id;
      perform public.log_player_cash_change(
        v_losing_bid.player_id,
        v_losing_bid.bond_paid,
        v_player_cash,
        'tender_bid_bond_refunded',
        format('Ihale teklif teminati iade edildi. Tender: %s', v_tender.id),
        v_losing_bid.id,
        'tender_bid'
      );
    end loop;

    v_closed_count := v_closed_count + 1;
  end loop;

  return jsonb_build_object(
    'success', true,
    'expired_count', v_expired_count,
    'closed_count', v_closed_count
  );
end;
$function$;

-- Function: ensure_player_achievement_rows
CREATE OR REPLACE FUNCTION public.ensure_player_achievement_rows(p_player_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_player_id is null then
    return;
  end if;

  insert into public.player_achievements (player_id, achievement_id)
  select p_player_id, ad.id
  from public.achievement_definitions ad
  where ad.is_active = true
  on conflict (player_id, achievement_id) do nothing;
end;
$function$;

-- Function: ensure_player_mission_rows
CREATE OR REPLACE FUNCTION public.ensure_player_mission_rows(p_player_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_player_id is null then
    return;
  end if;

  insert into public.player_missions (player_id, mission_id, last_reset_on)
  select
    p_player_id,
    md.id,
    timezone('Europe/Istanbul', now())::date
  from public.mission_definitions md
  where md.is_active = true
  on conflict (player_id, mission_id) do nothing;

  perform public.reset_player_daily_missions(p_player_id);
  perform public.reset_player_weekly_missions(p_player_id);
end;
$function$;

-- Function: ensure_player_record_exists
CREATE OR REPLACE FUNCTION public.ensure_player_record_exists(p_user_id uuid, p_city_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player public.players%rowtype;
  v_created boolean := false;
  v_assigned_city_id uuid := p_city_id;
begin
  if auth.uid() is null or auth.uid() <> p_user_id then
    raise exception 'Yetkisiz istek.';
  end if;

  select *
  into v_player
  from public.players
  where id = p_user_id;

  if not found then
    if v_assigned_city_id is not null and not exists (select 1 from public.cities where id = v_assigned_city_id) then
      v_assigned_city_id := null;
    end if;

    insert into public.players (
      id,
      player_name,
      company_name,
      avatar_id,
      level,
      experience,
      cash,
      gold,
      headquarters_city_id
    )
    values (
      p_user_id,
      'Oyuncu_' || left(p_user_id::text, 4),
      'Yeni Holding',
      'ae1.webp',
      1,
      0,
      100000,
      100,
      v_assigned_city_id
    )
    returning *
    into v_player;

    v_created := true;
  elsif p_city_id is not null and v_player.headquarters_city_id is null then
    update public.players
    set headquarters_city_id = p_city_id
    where id = p_user_id
    returning *
    into v_player;
  end if;

  return jsonb_build_object(
    'created', v_created,
    'player', to_jsonb(v_player)
  );
end;
$function$;

-- Function: fill_store_shelves
CREATE OR REPLACE FUNCTION public.fill_store_shelves(p_player_id uuid, p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_default_brand uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_store record;
  v_store_warehouse record;
  v_store_slot record;
  v_source_slot record;
  v_transfer_result jsonb;
  v_available_capacity integer;
  v_transfer_quantity integer;
  v_total_transferred_quantity integer := 0;
  v_filled_slot_count integer := 0;
  v_examined_slot_count integer := 0;
  v_used_source_slot_count integer := 0;
  v_affected_store_slot_ids uuid[] := '{}'::uuid[];
  v_affected_warehouse_slot_ids uuid[] := '{}'::uuid[];
  v_updated_store_slots jsonb := '[]'::jsonb;
  v_updated_warehouse_slots jsonb := '[]'::jsonb;
begin
  select s.*
  into v_store
  from public.stores s
  where s.id = p_store_id
  for update;

  if not found then
    raise exception 'Magaza bulunamadi.';
  end if;

  if v_store.player_id <> p_player_id then
    raise exception 'Bu magaza oyuncuya ait degil.';
  end if;

  select w.*
  into v_store_warehouse
  from public.warehouses w
  where w.store_id = p_store_id
    and w.warehouse_kind = 'store'
    and w.is_active = true
  order by w.created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'Magazaya bagli aktif depo bulunamadi.';
  end if;

  for v_store_slot in
    select ss.*
    from public.store_slots ss
    where ss.store_id = p_store_id
      and coalesce(ss.is_active, true) = true
      and coalesce(ss.product_id, '') <> ''
      and coalesce(ss.quality_level, 0) between 1 and 5
      and greatest(
        coalesce(ss.capacity, 0)
        - coalesce(ss.quantity, 0)
        - coalesce(ss.pending_quantity, 0),
        0
      ) > 0
    order by ss.slot_index, ss.id
  loop
    v_examined_slot_count := v_examined_slot_count + 1;
    v_available_capacity := greatest(
      coalesce(v_store_slot.capacity, 0)
      - coalesce(v_store_slot.quantity, 0)
      - coalesce(v_store_slot.pending_quantity, 0),
      0
    );

    if v_available_capacity <= 0 then
      continue;
    end if;

    for v_source_slot in
      select ws.*
      from public.warehouse_slots ws
      where ws.warehouse_id = v_store_warehouse.id
        and ws.product_id = v_store_slot.product_id
        and ws.quality_level = v_store_slot.quality_level
        and coalesce(ws.brand_id, v_default_brand) = coalesce(v_store_slot.brand_id, v_default_brand)
        and coalesce(ws.quantity, 0) > 0
      order by ws.slot_index, ws.id
    loop
      exit when v_available_capacity <= 0;

      v_transfer_quantity := least(v_available_capacity, coalesce(v_source_slot.quantity, 0));
      if v_transfer_quantity <= 0 then
        continue;
      end if;

      v_transfer_result := public.transfer_store_warehouse_slot_to_store_slot(
        p_player_id,
        v_source_slot.id,
        v_store_slot.id,
        v_transfer_quantity
      );

      if coalesce((v_transfer_result ->> 'success')::boolean, false) then
        v_total_transferred_quantity := v_total_transferred_quantity + v_transfer_quantity;
        v_available_capacity := v_available_capacity - v_transfer_quantity;
        v_used_source_slot_count := v_used_source_slot_count + 1;

        if not (v_store_slot.id = any(v_affected_store_slot_ids)) then
          v_affected_store_slot_ids := array_append(v_affected_store_slot_ids, v_store_slot.id);
          v_filled_slot_count := v_filled_slot_count + 1;
        end if;

        if not (v_source_slot.id = any(v_affected_warehouse_slot_ids)) then
          v_affected_warehouse_slot_ids := array_append(v_affected_warehouse_slot_ids, v_source_slot.id);
        end if;
      end if;
    end loop;
  end loop;

  -- Build detailed updated slot snapshots for in-memory client patching
  if array_length(v_affected_store_slot_ids, 1) > 0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', ss.id,
      'quantity', ss.quantity,
      'cost', ss.cost
    )), '[]'::jsonb)
    into v_updated_store_slots
    from public.store_slots ss
    where ss.id = any(v_affected_store_slot_ids);
  end if;

  if array_length(v_affected_warehouse_slot_ids, 1) > 0 then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', ws.id,
      'quantity', ws.quantity,
      'cost', ws.cost
    )), '[]'::jsonb)
    into v_updated_warehouse_slots
    from public.warehouse_slots ws
    where ws.id = any(v_affected_warehouse_slot_ids);
  end if;

  return jsonb_build_object(
    'success', true,
    'store_id', p_store_id,
    'warehouse_id', v_store_warehouse.id,
    'examined_slot_count', v_examined_slot_count,
    'filled_slot_count', v_filled_slot_count,
    'used_source_slot_count', v_used_source_slot_count,
    'transferred_quantity', v_total_transferred_quantity,
    'store_slot_ids', coalesce(to_jsonb(v_affected_store_slot_ids), '[]'::jsonb),
    'warehouse_slot_ids', coalesce(to_jsonb(v_affected_warehouse_slot_ids), '[]'::jsonb),
    'updated_store_slots', v_updated_store_slots,
    'updated_warehouse_slots', v_updated_warehouse_slots,
    'message', case
      when v_total_transferred_quantity > 0 then 'Magaza raflari depodan dolduruldu.'
      else 'Doldurulacak uygun depo stogu bulunamadi.'
    end
  );
end;
$function$;

-- Function: filter_profanity_text
CREATE OR REPLACE FUNCTION public.filter_profanity_text(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_cleaned text := p_text;
  v_word text;
  v_bad_words text[] := array[
    'oç', 'orospu', 'piç', 'amk', 'aq', 'sik', 'sikerim', 'sikeyim', 'yarak', 'yarrak',
    'göt', 'pezevenk', 'gavat', 'kahpe', 'ibne', 'puşt', 'amcık', 'meme', 'taşak'
  ];
begin
  if v_cleaned is null or btrim(v_cleaned) = '' then
    return v_cleaned;
  end if;

  foreach v_word in array v_bad_words loop
    v_cleaned := regexp_replace(v_cleaned, '\y' || v_word || '\y', '***', 'gi');
  end loop;

  return v_cleaned;
end;
$function$;

-- Function: finish_arge_with_gold
CREATE OR REPLACE FUNCTION public.finish_arge_with_gold(p_player_id uuid, p_research_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_research arge_researches%rowtype;
  v_player players%rowtype;
  v_now timestamptz := timezone('utc', now());
  v_remaining_minutes integer;
  v_gold_cost integer;
begin
  select * into v_research
  from arge_researches
  where id = p_research_id and player_id = p_player_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Arastirma bulunamadi.');
  end if;

  if v_research.status <> 'in_progress' then
    return jsonb_build_object('success', false, 'message', 'Bu arastirma zaten tamamlanmis.');
  end if;

  if v_research.finish_at <= v_now then
    return public.complete_arge_research(p_research_id);
  end if;

  v_remaining_minutes := ceil(extract(epoch from (v_research.finish_at - v_now)) / 60.0);
  v_gold_cost := greatest(1, ceil(v_remaining_minutes::numeric / 30.0)::integer);

  select * into v_player from players where id = p_player_id;
  if v_player.gold < v_gold_cost then
    return jsonb_build_object(
      'success', false,
      'message', format('Yetersiz altin. Gerekli: %s ★, Mevcut: %s ★.', v_gold_cost, v_player.gold::integer)
    );
  end if;

  update players
  set gold = gold - v_gold_cost
  where id = p_player_id;

  update arge_researches
  set finish_at = v_now
  where id = p_research_id;

  return public.complete_arge_research(p_research_id) || jsonb_build_object('gold_spent', v_gold_cost);
end;
$function$;

-- Function: finish_building_boost
CREATE OR REPLACE FUNCTION public.finish_building_boost(p_player_id uuid, p_boost_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
  v_boost public.building_boosts%rowtype;
begin
  select *
  into v_boost
  from public.building_boosts
  where id = p_boost_id
    and player_id = p_player_id
  for update;

  if not found then
    raise exception 'Boost bulunamadi.';
  end if;

  if v_boost.status <> 'in_progress' then
    raise exception 'Bu boost bitirilemez. Mevcut durum: %', v_boost.status;
  end if;

  if v_boost.building_kind = 'store' then
    update public.store_slots
    set boost_multiplier = 1.00,
        updated_at = v_now
    where store_id = v_boost.entity_id;
  elsif v_boost.building_kind in ('field', 'farm') then
    update public.production_slots
    set boost_multiplier = 1.00,
        updated_at = v_now
    where owner_kind = v_boost.building_kind
      and owner_id = v_boost.entity_id;
  elsif v_boost.building_kind = 'factory' then
    update public.factories
    set boost_multiplier = 1.00,
        updated_at = v_now
    where id = v_boost.entity_id
      and player_id = p_player_id;
  elsif v_boost.building_kind = 'mine' then
    update public.mines
    set boost_multiplier = 1.00,
        updated_at = v_now
    where id = v_boost.entity_id
      and player_id = p_player_id;
  else
    raise exception 'Bu building_kind icin boost bitirme destegi henuz yok: %', v_boost.building_kind;
  end if;

  update public.building_boosts
  set status = 'completed',
      completed_at = v_now,
      updated_at = v_now
  where id = p_boost_id;

  return jsonb_build_object(
    'success', true,
    'boost_id', p_boost_id,
    'building_kind', v_boost.building_kind,
    'entity_id', v_boost.entity_id,
    'completed_at', v_now
  );
end;
$function$;

-- Function: finish_building_upgrade_with_gold
CREATE OR REPLACE FUNCTION public.finish_building_upgrade_with_gold(p_player_id uuid, p_upgrade_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_upgrade record;
  v_player_gold numeric;
  v_gold_cost integer;
  v_remaining_minutes numeric;
  v_result jsonb;
begin
  if p_player_id is null or p_player_id <> auth.uid() then
    raise exception 'Gecersiz oyuncu.';
  end if;

  select *
  into v_upgrade
  from public.building_upgrades
  where id = p_upgrade_id
    and player_id = p_player_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Yukseltme bulunamadi.');
  end if;

  if v_upgrade.status <> 'in_progress' then
    return jsonb_build_object(
      'success', false,
      'message', 'Bu yukseltme zaten tamamlanmis veya gecersiz.'
    );
  end if;

  v_remaining_minutes := extract(epoch from (v_upgrade.finish_at - timezone('utc'::text, now()))) / 60.0;

  if v_remaining_minutes <= 0 then
    return public.complete_building_upgrade(p_player_id, p_upgrade_id) || jsonb_build_object('gold_spent', 0);
  end if;

  v_gold_cost := ceil(v_remaining_minutes / 10.0);

  select gold
  into v_player_gold
  from public.players
  where id = p_player_id
  for update;

  if coalesce(v_player_gold, 0) < v_gold_cost then
    return jsonb_build_object(
      'success', false,
      'message', format('Yetersiz yildiz. Gerekli: %s, Mevcut: %s.', v_gold_cost, coalesce(v_player_gold, 0)::integer)
    );
  end if;

  update public.players
  set gold = gold - v_gold_cost
  where id = p_player_id;

  update public.building_upgrades
  set
    finish_at = timezone('utc'::text, now()),
    updated_at = timezone('utc'::text, now())
  where id = p_upgrade_id;

  v_result := public.complete_building_upgrade(p_player_id, p_upgrade_id);

  return v_result || jsonb_build_object('gold_spent', v_gold_cost);
end;
$function$;

-- Function: finish_construction_with_gold
CREATE OR REPLACE FUNCTION public.finish_construction_with_gold(p_player_id uuid, p_construction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_gold numeric;
  v_gold_cost integer;
  v_construction record;
  v_remaining_minutes float;
BEGIN
  -- 1. İnşaat kaydını kontrol et
  SELECT * INTO v_construction FROM public.building_constructions 
  WHERE id = p_construction_id AND player_id = p_player_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'İnşaat kaydı bulunamadı.');
  END IF;

  IF v_construction.status <> 'in_progress' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bu inşaat zaten tamamlanmış veya iptal edilmiş.');
  END IF;

  -- 2. Dinamik maliyet hesapla (Her 10 dk için 1 altın, yukarı yuvarla)
  -- extract(epoch from ...) saniye farkını verir, 60'a bölerek dakikayı buluruz.
  v_remaining_minutes := EXTRACT(EPOCH FROM (v_construction.finish_at - timezone('utc'::text, now()))) / 60.0;
  
  -- Eğer süre zaten dolmuşsa maliyet 0 veya 1 olsun (garanti olsun)
  IF v_remaining_minutes <= 0 THEN
    v_gold_cost := 0;
  ELSE
    v_gold_cost := ceil(v_remaining_minutes / 10.0);
  END IF;

  -- 3. Oyuncunun altınını kontrol et
  SELECT gold INTO v_player_gold FROM public.players WHERE id = p_player_id FOR UPDATE;
  
  IF v_player_gold < v_gold_cost THEN
    RETURN jsonb_build_object('success', false, 'message', 'Yetersiz altın. Gereken: ' || v_gold_cost);
  END IF;

  -- 4. Altını düş
  UPDATE public.players SET gold = gold - v_gold_cost WHERE id = p_player_id;

  -- 5. İnşaatın bitiş süresini geçmişe çek
  UPDATE public.building_constructions 
  SET finish_at = timezone('utc'::text, now()) - interval '1 second'
  WHERE id = p_construction_id;

  -- 6. Mevcut tamamlama fonksiyonunu çağır
  RETURN public.complete_building_construction(p_player_id, p_construction_id);
END;
$function$;

-- Function: finish_logistics_transfer_with_ad_reward
CREATE OR REPLACE FUNCTION public.finish_logistics_transfer_with_ad_reward(p_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_transfer public.logistics_transfers%ROWTYPE;
  v_remaining_seconds integer;
  v_usage_number integer;
BEGIN
  IF v_player_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  END IF;

  SELECT * INTO v_transfer
  FROM public.logistics_transfers
  WHERE id = p_transfer_id AND buyer_player_id = v_player_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Transfer kaydi bulunamadi.');
  END IF;
  IF v_transfer.status = 'completed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bu transfer zaten tamamlanmis.');
  END IF;
  IF v_transfer.status <> 'in_transit' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bu transfer reklam odulu ile tamamlanabilir durumda degil.');
  END IF;

  v_remaining_seconds := GREATEST(
    CEIL(EXTRACT(EPOCH FROM (v_transfer.finish_at - timezone('utc'::text, now()))))::integer,
    0
  );
  IF v_remaining_seconds > 600 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Reklamla hizli tamamlama sadece son 10 dakika icindeki transferlerde kullanilabilir.');
  END IF;

  v_usage_number := public.consume_rewarded_ad_usage_v2(
    v_player_id, 'transfer_finish', 60, 4,
    jsonb_build_object('transfer_id', p_transfer_id)
  );

  UPDATE public.logistics_transfers
  SET finish_at = timezone('utc'::text, now()) - interval '1 second'
  WHERE id = p_transfer_id;

  RETURN public.complete_logistics_transfer(p_transfer_id)
    || jsonb_build_object('reward_daily_usage', v_usage_number, 'reward_daily_limit', 4);
END;
$function$;

-- Function: finish_logistics_transfer_with_gold
CREATE OR REPLACE FUNCTION public.finish_logistics_transfer_with_gold(p_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_player_gold numeric;
  v_gold_cost integer;
  v_transfer logistics_transfers%rowtype;
  v_remaining_minutes float;
BEGIN
  -- 1. Oturum kontrolü
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  -- 2. Transfer kaydını kontrol et
  SELECT * INTO v_transfer FROM public.logistics_transfers 
  WHERE id = p_transfer_id AND buyer_player_id = v_player_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Transfer kaydı bulunamadı.');
  END IF;

  IF v_transfer.status = 'completed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bu transfer zaten tamamlanmış.');
  END IF;

  IF v_transfer.status <> 'in_transit' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Bu transfer tamamlanabilir durumda değil.');
  END IF;

  -- 3. Dinamik maliyet hesapla (Her 10 dk için 1 altın/yıldız, yukarı yuvarla)
  v_remaining_minutes := EXTRACT(EPOCH FROM (v_transfer.finish_at - timezone('utc'::text, now()))) / 60.0;
  
  IF v_remaining_minutes <= 0 THEN
    v_gold_cost := 0;
  ELSE
    v_gold_cost := ceil(v_remaining_minutes / 10.0);
  END IF;

  -- 4. Oyuncunun altınını kontrol et
  SELECT gold INTO v_player_gold FROM public.players WHERE id = v_player_id FOR UPDATE;
  
  IF v_player_gold < v_gold_cost THEN
    RETURN jsonb_build_object('success', false, 'message', 'Yetersiz altın/yıldız. Gereken: ' || v_gold_cost);
  END IF;

  -- 5. Altını düş
  IF v_gold_cost > 0 THEN
    UPDATE public.players SET gold = gold - v_gold_cost WHERE id = v_player_id;
  END IF;

  -- 6. Transferin bitiş süresini geçmişe çek
  UPDATE public.logistics_transfers 
  SET finish_at = timezone('utc'::text, now()) - interval '1 second'
  WHERE id = p_transfer_id;

  -- 7. Mevcut tamamlama fonksiyonunu çağır
  RETURN public.complete_logistics_transfer(p_transfer_id);
END;
$function$;

-- Function: generate_open_tenders
CREATE OR REPLACE FUNCTION public.generate_open_tenders(p_target_open_count integer DEFAULT 20, p_max_generate integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_open_count integer := 0;
  v_missing_count integer := 0;
  v_generate_count integer := 0;
  v_generated_count integer := 0;
  v_iteration integer := 0;
  v_pick record;
  v_tier_roll double precision;
  v_tier_type integer; -- 1: Yerel/Hızlı, 2: Kurumsal/Belediye, 3: Stratejik/Mega
  v_target_min_revenue numeric;
  v_target_max_revenue numeric;
  v_target_revenue numeric;
  v_quality_level integer;
  v_quality_multiplier numeric;
  v_wholesale_markup numeric;
  v_unit_price numeric;
  v_required_quantity integer;
  v_reward_cash numeric;
  v_bond_amount numeric;
  v_award_type text;
  v_accept_hours integer;
  v_delivery_hours integer;
  v_accept_until timestamptz;
  v_delivery_minutes integer;
  v_min_player_level integer;
  v_title text;
  v_description text;
begin
  if coalesce(p_target_open_count, 0) <= 0 then
    return jsonb_build_object(
      'success', true,
      'open_count', 0,
      'generated_count', 0,
      'message', 'Hedef acik ihale sayisi sifir veya negatif.'
    );
  end if;

  select count(*)
  into v_open_count
  from public.tenders t
  where t.status = 'open'
    and t.accept_until > timezone('utc'::text, now());

  v_missing_count := greatest(p_target_open_count - v_open_count, 0);
  v_generate_count := least(
    v_missing_count,
    greatest(coalesce(p_max_generate, p_target_open_count), 0)
  );

  if v_generate_count <= 0 then
    return jsonb_build_object(
      'success', true,
      'open_count', v_open_count,
      'generated_count', 0
    );
  end if;

  for v_iteration in 1..v_generate_count loop
    select
      chosen_city.id as city_id,
      chosen_city.name as city_name,
      chosen_product.id as product_id,
      chosen_product.urun_adi,
      chosen_product.baz_satis_fiyati,
      chosen_product.uretim_birimi,
      chosen_product.kategori
    into v_pick
    from (
      select c.id, c.name
      from public.cities c
      order by random()
      limit 1
    ) chosen_city
    cross join lateral (
      select p.id, p.urun_adi, p.baz_satis_fiyati, p.uretim_birimi, p.kategori
      from public.products p
      where coalesce(p.baz_satis_fiyati, 0) > 0
        and not exists (
          select 1
          from public.tenders t
          where t.status = 'open'
            and t.accept_until > timezone('utc'::text, now())
            and t.city_id = chosen_city.id
            and t.product_id = p.id
        )
      order by random()
      limit 1
    ) chosen_product;

    if not found then
      continue;
    end if;

    -- 1. Tier Belirleme
    v_tier_roll := random();
    if v_tier_roll < 0.45 then
      -- Tier 1: Yerel & Flaş Tedarik (Küçük Ölçek)
      v_tier_type := 1;
      v_target_min_revenue := 50000;
      v_target_max_revenue := 250000;
      v_accept_hours := 1 + floor(random() * 3)::integer; -- 1 - 3 saat
      v_delivery_hours := 3 + floor(random() * 6)::integer; -- 3 - 8 saat
      v_quality_level := 1;
      v_min_player_level := 1;
    elsif v_tier_roll < 0.80 then
      -- Tier 2: Kurumsal & Belediye Tedariği (Orta Ölçek)
      v_tier_type := 2;
      v_target_min_revenue := 300000;
      v_target_max_revenue := 1500000;
      v_accept_hours := 3 + floor(random() * 5)::integer; -- 3 - 7 saat
      v_delivery_hours := 8 + floor(random() * 16)::integer; -- 8 - 24 saat
      v_quality_level := case when random() < 0.70 then 2 else 1 end;
      v_min_player_level := 3 + floor(random() * 4)::integer; -- Seviye 3 - 6
    else
      -- Tier 3: Stratejik, Askeri & Mega İhracat (Büyük Ölçek)
      v_tier_type := 3;
      v_target_min_revenue := 2000000;
      v_target_max_revenue := 10000000;
      v_accept_hours := 6 + floor(random() * 12)::integer; -- 6 - 18 saat
      v_delivery_hours := 24 + floor(random() * 24)::integer; -- 24 - 48 saat
      v_quality_level := case when random() < 0.50 then 3 when random() < 0.85 then 2 else 1 end;
      v_min_player_level := 7 + floor(random() * 6)::integer; -- Seviye 7 - 12
    end if;

    -- 2. Fiyat ve Kârlılık Katsayıları
    v_quality_multiplier := 1 + ((v_quality_level - 1) * 0.20);
    v_wholesale_markup := round((1.25 + (random() * 0.20))::numeric, 2); -- %25 - %45 garantili kâr marjı
    v_unit_price := coalesce(v_pick.baz_satis_fiyati, 50) * v_quality_multiplier * v_wholesale_markup;

    -- Hedef ciro
    v_target_revenue := v_target_min_revenue + (random() * (v_target_max_revenue - v_target_min_revenue));

    -- Mantıklı Adet Hesaplama
    v_required_quantity := greatest(round(v_target_revenue / v_unit_price)::integer, 10);

    -- Temiz yuvarlak adet formatlaması
    if v_required_quantity >= 10000 then
      v_required_quantity := (round(v_required_quantity / 1000.0) * 1000)::integer;
    elsif v_required_quantity >= 1000 then
      v_required_quantity := (round(v_required_quantity / 100.0) * 100)::integer;
    elsif v_required_quantity >= 100 then
      v_required_quantity := (round(v_required_quantity / 10.0) * 10)::integer;
    else
      v_required_quantity := (round(v_required_quantity / 5.0) * 5)::integer;
    end if;
    v_required_quantity := greatest(v_required_quantity, 10);

    -- Toplam Ödül ve Teminat
    v_reward_cash := round(v_required_quantity * v_unit_price);
    v_bond_amount := round(v_reward_cash * 0.10); -- Standart %10 teminat
    v_award_type := case when random() < 0.45 then 'first_claim' else 'lowest_bid' end;

    v_accept_until := timezone('utc'::text, now()) + make_interval(hours => v_accept_hours);
    v_delivery_minutes := v_delivery_hours * 60;

    -- 3. Gerçekçi Başlık ve Açıklamalar
    if v_tier_type = 1 then
      case coalesce(v_pick.uretim_birimi, '')
        when 'TARLA' then
          v_title := format('%s Restoran ve Oteller Birliği Alımı', v_pick.city_name);
          v_description := format('%s bölgesi turizm ve yeme-içme tesisleri için toptan %s adet %s kalite %s tedarik ihalesi.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'CIFTLIK' then
          v_title := format('%s İlçe Yemekhaneleri Besi Alımı', v_pick.city_name);
          v_description := format('%s ilçe merkezindeki yemekhaneler için acil %s adet %s kalite %s tedariği.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'MADEN' then
          v_title := format('%s Sanayi Sitesi Maden Tedariği', v_pick.city_name);
          v_description := format('%s küçük sanayi sitesi atölyeleri için toptan %s adet %s kalite %s alımı.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'FABRIKA' then
          v_title := format('%s İmalatçı Tedarik İhalesi', v_pick.city_name);
          v_description := format('%s bölgesindeki yerel üreticiler için %s adet %s kalite %s temini.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        else
          v_title := format('%s Yerel Tedarik İhalesi', v_pick.city_name);
          v_description := format('%s için acil %s adet %s kalite %s teslimi beklenmektedir.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
      end case;
    elsif v_tier_type = 2 then
      case coalesce(v_pick.uretim_birimi, '')
        when 'TARLA' then
          v_title := format('%s BŞB Sosyal Yardım Gıda Alımı', v_pick.city_name);
          v_description := format('%s Büyükşehir Belediyesi sosyal yardım paketleri ve aşevleri için %s adet %s kalite %s alım ihalesi.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'CIFTLIK' then
          v_title := format('%s Kamu Hastaneleri Gıda Konsorsiyumu', v_pick.city_name);
          v_description := format('%s ili kamu sağlık tesisleri ve hastaneler için %s adet %s kalite %s tedarik programı.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'MADEN' then
          v_title := format('%s Organize Sanayi Hammadde Alımı', v_pick.city_name);
          v_description := format('%s Organize Sanayi Bölgesi metal ve maden işleme hatları için %s adet %s kalite %s ihalesi.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'FABRIKA' then
          v_title := format('%s Altyapı ve İnşaat Tedarik Paketi', v_pick.city_name);
          v_description := format('%s kentsel gelişim ve sanayi projeleri kapsamında %s adet %s kalite %s alımı yapılacaktır.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        else
          v_title := format('%s Kurumsal Tedarik İhalesi', v_pick.city_name);
          v_description := format('%s kamu ve kurumsal projeleri için %s adet %s kalite %s alımı.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
      end case;
    else
      case coalesce(v_pick.uretim_birimi, '')
        when 'TARLA' then
          v_title := format('%s Uluslararası Tarım İhracat Konsorsiyumu', v_pick.city_name);
          v_description := format('%s lojistik merkezinden yurt dışına sevk edilmek üzere stratejik %s adet %s kalite %s ihracat partisi.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'CIFTLIK' then
          v_title := format('%s MSB Stratejik İaşe Rezerv Alımı', v_pick.city_name);
          v_description := format('Milli Savunma Bakanlığı ve AFAD stratejik iaşe stokları için %s ili teslimatlı %s adet %s kalite %s tedariği.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'MADEN' then
          v_title := format('%s Devlet Demiryolları ve Ağır Sanayi Alımı', v_pick.city_name);
          v_description := format('Ulusal altyapı ve ağır sanayi tesisleri için %s teslimatlı yüksek hacimli %s adet %s kalite %s alım ihalesi.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        when 'FABRIKA' then
          v_title := format('%s Liman Bölgesi Küresel İhracat Partisi', v_pick.city_name);
          v_description := format('%s Limanı üzerinden global pazara ihraç edilecek %s adet %s kalite %s mega tedarik kontratı.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
        else
          v_title := format('%s Stratejik Mega Tedarik İhalesi', v_pick.city_name);
          v_description := format('%s için yüksek hacimli uluslararası standartta %s adet %s kalite %s alım kontratı.', v_pick.city_name, v_required_quantity, v_quality_level, v_pick.urun_adi);
      end case;
    end if;

    insert into public.tenders (
      title,
      description,
      city_id,
      product_id,
      quality_level,
      required_quantity,
      reward_cash,
      bond_amount,
      award_type,
      accept_until,
      delivery_duration_minutes,
      status,
      visibility,
      min_player_level
    )
    values (
      v_title,
      v_description,
      v_pick.city_id,
      v_pick.product_id,
      v_quality_level,
      v_required_quantity,
      v_reward_cash,
      v_bond_amount,
      v_award_type,
      v_accept_until,
      v_delivery_minutes,
      'open',
      'public',
      v_min_player_level
    );

    v_generated_count := v_generated_count + 1;
  end loop;

  return jsonb_build_object(
    'success', true,
    'open_count', v_open_count + v_generated_count,
    'generated_count', v_generated_count,
    'target_open_count', p_target_open_count
  );
end;
$function$;

-- Function: get_active_arge_researches
CREATE OR REPLACE FUNCTION public.get_active_arge_researches(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'player_id', player_id,
    'product_id', product_id,
    'product_name', product_name,
    'current_quality', current_quality,
    'target_quality', target_quality,
    'cost_paid', cost_paid,
    'status', status,
    'started_at', started_at,
    'finish_at', finish_at,
    'completed_at', completed_at,
    'created_at', created_at
  ) order by started_at desc), '[]'::jsonb)
  into v_result
  from public.arge_researches
  where player_id = p_player_id
    and status = 'in_progress';
  return v_result;
end;
$function$;

-- Function: get_active_cities
CREATE OR REPLACE FUNCTION public.get_active_cities()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.get_cities_catalog(true);
$function$;

-- Function: get_active_marketing_campaigns
CREATE OR REPLACE FUNCTION public.get_active_marketing_campaigns()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_player_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
  INTO v_result
  FROM public.brand_marketing_campaigns c
  WHERE c.player_id = v_player_id
    AND c.active_until > timezone('utc'::text, now())
  ORDER BY c.active_until ASC;

  RETURN v_result;
END;
$function$;

-- Function: get_all_products_catalog
CREATE OR REPLACE FUNCTION public.get_all_products_catalog()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(p) order by p.urun_adi),
    '[]'::jsonb
  )
  from public.products p;
$function$;

-- Function: get_arge_products_with_quality
CREATE OR REPLACE FUNCTION public.get_arge_products_with_quality()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'urun_adi', p.urun_adi,
        'urun_iconu', p.urun_iconu,
        'baz_satis_fiyati', p.baz_satis_fiyati,
        'uretim_birimi', p.uretim_birimi,
        'hammadde_1_id', p.hammadde_1_id,
        'hammadde_2_id', p.hammadde_2_id,
        'hammadde_3_id', p.hammadde_3_id,
        'current_quality_level', coalesce(ppql.max_quality_level, 1),
        'is_produced', exists (
          SELECT 1 FROM public.production_slots ps
          WHERE ps.product_id = p.id
            AND ps.is_active = true
            AND ps.owner_id IN (
              SELECT id FROM public.fields WHERE player_id = auth.uid()
              UNION ALL
              SELECT id FROM public.farms WHERE player_id = auth.uid()
              UNION ALL
              SELECT id FROM public.factories WHERE player_id = auth.uid()
              UNION ALL
              SELECT id FROM public.mines WHERE player_id = auth.uid()
            )
        )
      )
      ORDER BY p.urun_adi
    ),
    '[]'::jsonb
  )
  FROM public.products p
  LEFT JOIN public.player_product_quality_levels ppql
    ON ppql.product_id = p.id
   AND ppql.player_id = auth.uid();
$function$;

-- Function: get_available_products_for_store
CREATE OR REPLACE FUNCTION public.get_available_products_for_store(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_store_warehouse_id uuid;
    v_products jsonb;
begin
    select w.id
    into v_store_warehouse_id
    from public.warehouses w
    where w.store_id = p_store_id
      and w.warehouse_kind = 'store'
      and w.is_active = true
    limit 1;

    if v_store_warehouse_id is null then
      return jsonb_build_object(
        'success', false,
        'message', 'Bu magazaya bagli aktif magaza deposu bulunamadi.'
      );
    end if;

    select jsonb_agg(
      jsonb_build_object(
        'warehouse_slot_id', ws.id,
        'product_id', p.id,
        'name', p.urun_adi,
        'icon', p.urun_iconu,
        'base_price', p.baz_satis_fiyati,
        'brand_id', ws.brand_id,
        'quality_level', ws.quality_level,
        'quantity', ws.quantity,
        'cost', ws.cost
      )
      order by p.urun_adi, ws.quality_level, ws.quantity desc, ws.id
    )
    into v_products
    from public.warehouse_slots ws
    join public.products p on p.id = ws.product_id
    where ws.warehouse_id = v_store_warehouse_id
      and ws.product_id is not null
      and coalesce(ws.quantity, 0) > 0;

    return jsonb_build_object(
      'success', true,
      'products', coalesce(v_products, '[]'::jsonb)
    );
exception when others then
    return jsonb_build_object(
        'success', false,
        'message', SQLERRM
    );
end;
$function$;

-- Function: get_building_upgrade_quote
CREATE OR REPLACE FUNCTION public.get_building_upgrade_quote(p_building_kind text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_quote jsonb;
  v_active public.building_upgrades%rowtype;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  v_quote := public.get_building_upgrade_quote_impl(
    p_building_kind,
    p_entity_id
  );

  if v_quote->>'block_reason' = 'maximum_level' then
    return v_quote;
  end if;

  select * into v_active
  from public.building_upgrades
  where player_id = v_player_id and status = 'in_progress'
  order by finish_at asc, started_at asc
  limit 1;

  if found then
    return v_quote || jsonb_build_object(
      'can_upgrade', false,
      'block_reason', 'active_upgrade',
      'active_upgrade_id', v_active.id,
      'active_building_kind', v_active.building_kind,
      'active_entity_id', v_active.entity_id,
      'active_finish_at', v_active.finish_at
    );
  end if;

  return v_quote;
end;
$function$;

-- Function: get_building_upgrade_quote_impl
CREATE OR REPLACE FUNCTION public.get_building_upgrade_quote_impl(p_building_kind text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_player_level integer;
  v_type_id uuid;
  v_name text;
  v_current_level integer;
  v_is_active boolean;
  v_input_capacity numeric := 0;
  v_output_capacity numeric := 0;
  v_slot_capacity numeric := 0;
  v_max_slot_count numeric := 0;
  v_capacity numeric := 0;
  v_definition public.building_upgrade_definitions%rowtype;
  v_effects jsonb := '[]'::jsonb;
  v_params jsonb := '{}'::jsonb;
  v_can_upgrade boolean;
  v_block_reason text;
begin
  if v_player_id is null then raise exception 'Oturum acilmamis.'; end if;
  if p_building_kind not in ('store', 'warehouse', 'field', 'farm', 'factory', 'mine') then
    raise exception 'Desteklenmeyen isletme turu: %', p_building_kind;
  end if;

  select level into v_player_level from public.players where id = v_player_id;
  if not found then raise exception 'Oyuncu bulunamadi.'; end if;

  if p_building_kind = 'store' then
    select store_type_id, name, level, is_active, slot_capacity, max_slot_count
      into v_type_id, v_name, v_current_level, v_is_active, v_slot_capacity, v_max_slot_count
    from public.stores where id = p_entity_id and player_id = v_player_id;
  elsif p_building_kind = 'warehouse' then
    select warehouse_type_id, name, level, is_active, capacity
      into v_type_id, v_name, v_current_level, v_is_active, v_capacity
    from public.warehouses where id = p_entity_id and player_id = v_player_id;
  elsif p_building_kind = 'field' then
    select field_type_id, name, level, is_active, input_capacity, output_capacity, max_slot_count
      into v_type_id, v_name, v_current_level, v_is_active, v_input_capacity, v_output_capacity, v_max_slot_count
    from public.fields where id = p_entity_id and player_id = v_player_id;
  elsif p_building_kind = 'farm' then
    select farm_type_id, name, level, is_active, input_capacity, output_capacity, max_slot_count
      into v_type_id, v_name, v_current_level, v_is_active, v_input_capacity, v_output_capacity, v_max_slot_count
    from public.farms where id = p_entity_id and player_id = v_player_id;
  elsif p_building_kind = 'factory' then
    select factory_type_id, name, level, is_active, input_capacity, output_capacity
      into v_type_id, v_name, v_current_level, v_is_active, v_input_capacity, v_output_capacity
    from public.factories where id = p_entity_id and player_id = v_player_id;
  elsif p_building_kind = 'mine' then
    select mine_type_id, name, level, is_active, output_capacity
      into v_type_id, v_name, v_current_level, v_is_active, v_output_capacity
    from public.mines where id = p_entity_id and player_id = v_player_id;
  end if;

  if v_type_id is null then raise exception 'Isletme bulunamadi veya size ait degil.'; end if;

  if v_current_level >= 5 then
    return jsonb_build_object(
      'success', true, 'can_upgrade', false, 'block_reason', 'maximum_level',
      'building_kind', p_building_kind, 'entity_id', p_entity_id,
      'building_type_id', v_type_id, 'name', v_name,
      'current_level', v_current_level, 'max_level', 5, 'effects', '[]'::jsonb
    );
  end if;

  select * into v_definition
  from public.building_upgrade_definitions
  where building_kind = p_building_kind and building_type_id = v_type_id
    and from_level = v_current_level and is_active;
  if not found then raise exception 'Bu seviye icin aktif yukseltme tanimi bulunamadi.'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'metric_key', e.metric_key, 'operation', e.operation, 'value', e.value,
    'previous_value', case e.metric_key
      when 'store_slot_capacity' then v_slot_capacity
      when 'store_max_slot_count' then v_max_slot_count
      when 'warehouse_capacity' then v_capacity
      when 'input_capacity' then v_input_capacity
      when 'output_capacity' then v_output_capacity end,
    'next_value', case e.metric_key
      when 'store_slot_capacity' then case e.operation when 'add' then v_slot_capacity + e.value when 'multiply' then v_slot_capacity * e.value else e.value end
      when 'store_max_slot_count' then case e.operation when 'add' then v_max_slot_count + e.value when 'multiply' then v_max_slot_count * e.value else e.value end
      when 'warehouse_capacity' then case e.operation when 'add' then v_capacity + e.value when 'multiply' then v_capacity * e.value else e.value end
      when 'input_capacity' then case e.operation when 'add' then v_input_capacity + e.value when 'multiply' then v_input_capacity * e.value else e.value end
      when 'output_capacity' then case e.operation when 'add' then v_output_capacity + e.value when 'multiply' then v_output_capacity * e.value else e.value end end
  ) order by e.display_order), '[]'::jsonb)
  into v_effects from public.building_upgrade_effects e
  where e.upgrade_definition_id = v_definition.id;

  v_can_upgrade := coalesce(v_is_active, false) and v_player_level >= v_definition.required_player_level;
  v_block_reason := case
    when not coalesce(v_is_active, false) then 'inactive'
    when v_player_level < v_definition.required_player_level then 'player_level'
    else null end;

  return jsonb_build_object(
    'success', true, 'can_upgrade', v_can_upgrade, 'block_reason', v_block_reason,
    'definition_id', v_definition.id, 'building_kind', p_building_kind,
    'entity_id', p_entity_id, 'building_type_id', v_type_id, 'name', v_name,
    'current_level', v_current_level, 'target_level', v_definition.target_level,
    'max_level', 5, 'required_player_level', v_definition.required_player_level,
    'cash_cost', v_definition.cash_cost,
    'duration_seconds', v_definition.duration_seconds,
    'duration_minutes', ceil(v_definition.duration_seconds / 60.0),
    'instant_finish_enabled', v_definition.instant_finish_enabled,
    'effects', v_effects
  );
end;
$function$;

-- Function: get_buyer_transfer_history_items
CREATE OR REPLACE FUNCTION public.get_buyer_transfer_history_items()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with base as (
    select
      lt.id,
      coalesce(lt.quantity, 0) as quantity,
      greatest(coalesce(lt.item_count, 1), 1) as item_count,
      coalesce(nullif(lt.total_quantity, 0), lt.quantity, 0) as total_quantity,
      greatest(coalesce(lt.quality_level, 1), 1) as quality_level,
      coalesce(
        lt.brand_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      ) as brand_id,
      coalesce(lt.status, 'completed') as status,
      coalesce(nullif(lt.transfer_type, ''), 'market_transfer') as transfer_type,
      coalesce(lt.is_rental, false) as is_rental,
      coalesce(lt.total_price, 0)::double precision as total_price,
      coalesce(lt.rental_cost, 0)::double precision as rental_cost,
      coalesce(lt.transport_cost, 0)::double precision as transport_cost,
      lt.started_at,
      lt.finish_at,
      lt.completed_at,
      coalesce(
        nullif(lt.seller_entity_kind, ''),
        case
          when lt.seller_warehouse_id is not null then 'warehouse'
          when lt.seller_store_id is not null then 'store'
          when lt.seller_production_inventory_id is not null then 'production_inventory'
          else 'warehouse'
        end
      ) as seller_entity_kind,
      coalesce(
        nullif(lt.buyer_entity_kind, ''),
        case
          when lt.buyer_warehouse_id is not null then 'warehouse'
          when lt.buyer_store_id is not null then 'store'
          when lt.buyer_production_inventory_id is not null then 'production_inventory'
          else 'warehouse'
        end
      ) as buyer_entity_kind,
      jsonb_build_object(
        'id', coalesce(p.id, ''),
        'urun_adi', coalesce(p.urun_adi, 'Urun'),
        'urun_iconu', coalesce(p.urun_iconu, 'default.webp')
      ) as product,
      case
        when sw.id is null then null
        else jsonb_build_object(
          'id', sw.id,
          'name', coalesce(sw.name, 'Depo'),
          'kind', 'warehouse',
          'city', jsonb_build_object(
            'id', swc.id,
            'name', coalesce(swc.name, 'Sehir'),
            'map_position_x', coalesce(swc.map_position_x, 0),
            'map_position_y', coalesce(swc.map_position_y, 0)
          )
        )
      end as seller_warehouse,
      case
        when bw.id is null then null
        else jsonb_build_object(
          'id', bw.id,
          'name', coalesce(bw.name, 'Depo'),
          'kind', 'warehouse',
          'city', jsonb_build_object(
            'id', bwc.id,
            'name', coalesce(bwc.name, 'Sehir'),
            'map_position_x', coalesce(bwc.map_position_x, 0),
            'map_position_y', coalesce(bwc.map_position_y, 0)
          )
        )
      end as buyer_warehouse,
      case
        when ss.id is null then null
        else jsonb_build_object(
          'id', ss.id,
          'name', coalesce(ss.name, 'Magaza'),
          'kind', 'store',
          'city', jsonb_build_object(
            'id', ssc.id,
            'name', coalesce(ssc.name, 'Sehir'),
            'map_position_x', coalesce(ssc.map_position_x, 0),
            'map_position_y', coalesce(ssc.map_position_y, 0)
          )
        )
      end as seller_store,
      case
        when bs.id is null then null
        else jsonb_build_object(
          'id', bs.id,
          'name', coalesce(bs.name, 'Magaza'),
          'kind', 'store',
          'city', jsonb_build_object(
            'id', bsc.id,
            'name', coalesce(bsc.name, 'Sehir'),
            'map_position_x', coalesce(bsc.map_position_x, 0),
            'map_position_y', coalesce(bsc.map_position_y, 0)
          )
        )
      end as buyer_store,
      case
        when spi.id is null then null
        else jsonb_build_object(
          'id', spi.id,
          'name', coalesce(sf.name, sfa.name, sfi.name, sm.name, 'Uretim'),
          'kind', 'production_inventory',
          'city', jsonb_build_object(
            'id', coalesce(sfc.id, sfac.id, sfic.id, smc.id),
            'name', coalesce(sfc.name, sfac.name, sfic.name, smc.name, 'Sehir'),
            'map_position_x', coalesce(sfc.map_position_x, sfac.map_position_x, sfic.map_position_x, smc.map_position_x, 0),
            'map_position_y', coalesce(sfc.map_position_y, sfac.map_position_y, sfic.map_position_y, smc.map_position_y, 0)
          )
        )
      end as seller_production_inventory,
      case
        when bpi.id is null then null
        else jsonb_build_object(
          'id', bpi.id,
          'name', coalesce(bf.name, bfa.name, bfi.name, bm.name, 'Uretim'),
          'kind', 'production_inventory',
          'city', jsonb_build_object(
            'id', coalesce(bfc.id, bfac.id, bfic.id, bmc.id),
            'name', coalesce(bfc.name, bfac.name, bfic.name, bmc.name, 'Sehir'),
            'map_position_x', coalesce(bfc.map_position_x, bfac.map_position_x, bfic.map_position_x, bmc.map_position_x, 0),
            'map_position_y', coalesce(bfc.map_position_y, bfac.map_position_y, bfic.map_position_y, bmc.map_position_y, 0)
          )
        )
      end as buyer_production_inventory
    from public.logistics_transfers lt
    left join public.products p on p.id = lt.product_id
    left join public.warehouses sw on sw.id = lt.seller_warehouse_id
    left join public.cities swc on swc.id = sw.city_id
    left join public.warehouses bw on bw.id = lt.buyer_warehouse_id
    left join public.cities bwc on bwc.id = bw.city_id
    left join public.stores ss on ss.id = lt.seller_store_id
    left join public.cities ssc on ssc.id = ss.city_id
    left join public.stores bs on bs.id = lt.buyer_store_id
    left join public.cities bsc on bsc.id = bs.city_id
    left join public.production_inventory spi on spi.id = lt.seller_production_inventory_id
    left join public.factories sf on spi.owner_kind = 'factory' and sf.id = spi.owner_id
    left join public.cities sfc on sfc.id = sf.city_id
    left join public.farms sfa on spi.owner_kind = 'farm' and sfa.id = spi.owner_id
    left join public.cities sfac on sfac.id = sfa.city_id
    left join public.fields sfi on spi.owner_kind = 'field' and sfi.id = spi.owner_id
    left join public.cities sfic on sfic.id = sfi.city_id
    left join public.mines sm on spi.owner_kind = 'mine' and sm.id = spi.owner_id
    left join public.cities smc on smc.id = sm.city_id
    left join public.production_inventory bpi on bpi.id = lt.buyer_production_inventory_id
    left join public.factories bf on bpi.owner_kind = 'factory' and bf.id = bpi.owner_id
    left join public.cities bfc on bfc.id = bf.city_id
    left join public.farms bfa on bpi.owner_kind = 'farm' and bfa.id = bpi.owner_id
    left join public.cities bfac on bfac.id = bfa.city_id
    left join public.fields bfi on bpi.owner_kind = 'field' and bfi.id = bpi.owner_id
    left join public.cities bfic on bfic.id = bfi.city_id
    left join public.mines bm on bpi.owner_kind = 'mine' and bm.id = bpi.owner_id
    left join public.cities bmc on bmc.id = bm.city_id
    where lt.buyer_player_id = auth.uid()
      and lt.status = 'completed'
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'quantity', quantity,
        'item_count', item_count,
        'total_quantity', total_quantity,
        'quality_level', quality_level,
        'brand_id', brand_id,
        'status', status,
        'transfer_type', transfer_type,
        'is_rental', is_rental,
        'total_price', total_price,
        'rental_cost', rental_cost,
        'transport_cost', transport_cost,
        'started_at', started_at,
        'finish_at', finish_at,
        'completed_at', completed_at,
        'seller_entity_kind', seller_entity_kind,
        'buyer_entity_kind', buyer_entity_kind,
        'product', product,
        'seller_warehouse', seller_warehouse,
        'buyer_warehouse', buyer_warehouse,
        'seller_store', seller_store,
        'buyer_store', buyer_store,
        'seller_production_inventory', seller_production_inventory,
        'buyer_production_inventory', buyer_production_inventory
      )
      order by completed_at desc nulls last, finish_at desc, started_at desc, id desc
    ),
    '[]'::jsonb
  )
  from base;
$function$;

-- Function: get_buyer_transfer_map_items
CREATE OR REPLACE FUNCTION public.get_buyer_transfer_map_items()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_result jsonb;
begin
  if v_player_id is null then
    return '[]'::jsonb;
  end if;

  -- Süresi dolmuş transferleri anında tamamla
  perform public.complete_due_market_transfers(v_player_id, 50);

  with base as (
    select
      lt.id,
      coalesce(lt.quantity, 0) as quantity,
      greatest(coalesce(lt.item_count, 1), 1) as item_count,
      coalesce(nullif(lt.total_quantity, 0), lt.quantity, 0) as total_quantity,
      greatest(coalesce(lt.quality_level, 1), 1) as quality_level,
      coalesce(
        lt.brand_id,
        '00000000-0000-0000-0000-000000000000'::uuid
      ) as brand_id,
      coalesce(lt.status, 'in_transit') as status,
      coalesce(nullif(lt.transfer_type, ''), 'market_transfer') as transfer_type,
      coalesce(lt.is_rental, false) as is_rental,
      coalesce(lt.total_price, 0)::double precision as total_price,
      coalesce(lt.rental_cost, 0)::double precision as rental_cost,
      coalesce(lt.transport_cost, 0)::double precision as transport_cost,
      lt.started_at,
      lt.finish_at,
      lt.completed_at,
      coalesce(
        nullif(lt.seller_entity_kind, ''),
        case
          when lt.seller_warehouse_id is not null then 'warehouse'
          when lt.seller_store_id is not null then 'store'
          when lt.seller_production_inventory_id is not null then 'production_inventory'
          else 'warehouse'
        end
      ) as seller_entity_kind,
      coalesce(
        nullif(lt.buyer_entity_kind, ''),
        case
          when lt.buyer_warehouse_id is not null then 'warehouse'
          when lt.buyer_store_id is not null then 'store'
          when lt.buyer_production_inventory_id is not null then 'production_inventory'
          else 'warehouse'
        end
      ) as buyer_entity_kind,
      jsonb_build_object(
        'id', coalesce(p.id, ''),
        'urun_adi', coalesce(p.urun_adi, 'Urun'),
        'urun_iconu', coalesce(p.urun_iconu, 'default.webp')
      ) as product,
      case
        when sw.id is null then null
        else jsonb_build_object(
          'id', sw.id,
          'name', coalesce(sw.name, 'Depo'),
          'kind', 'warehouse',
          'city', jsonb_build_object(
            'id', swc.id,
            'name', coalesce(swc.name, 'Sehir'),
            'map_position_x', coalesce(swc.map_position_x, 0),
            'map_position_y', coalesce(swc.map_position_y, 0)
          )
        )
      end as seller_warehouse,
      case
        when bw.id is null then null
        else jsonb_build_object(
          'id', bw.id,
          'name', coalesce(bw.name, 'Depo'),
          'kind', 'warehouse',
          'city', jsonb_build_object(
            'id', bwc.id,
            'name', coalesce(bwc.name, 'Sehir'),
            'map_position_x', coalesce(bwc.map_position_x, 0),
            'map_position_y', coalesce(bwc.map_position_y, 0)
          )
        )
      end as buyer_warehouse,
      case
        when ss.id is null then null
        else jsonb_build_object(
          'id', ss.id,
          'name', coalesce(ss.name, 'Magaza'),
          'kind', 'store',
          'city', jsonb_build_object(
            'id', ssc.id,
            'name', coalesce(ssc.name, 'Sehir'),
            'map_position_x', coalesce(ssc.map_position_x, 0),
            'map_position_y', coalesce(ssc.map_position_y, 0)
          )
        )
      end as seller_store,
      case
        when bs.id is null then null
        else jsonb_build_object(
          'id', bs.id,
          'name', coalesce(bs.name, 'Magaza'),
          'kind', 'store',
          'city', jsonb_build_object(
            'id', bsc.id,
            'name', coalesce(bsc.name, 'Sehir'),
            'map_position_x', coalesce(bsc.map_position_x, 0),
            'map_position_y', coalesce(bsc.map_position_y, 0)
          )
        )
      end as buyer_store,
      case
        when spi.id is null then null
        else jsonb_build_object(
          'id', spi.id,
          'name', coalesce(sf.name, sfa.name, sfi.name, sm.name, 'Uretim'),
          'kind', 'production_inventory',
          'city', jsonb_build_object(
            'id', coalesce(sfc.id, sfac.id, sfic.id, smc.id),
            'name', coalesce(sfc.name, sfac.name, sfic.name, smc.name, 'Sehir'),
            'map_position_x', coalesce(sfc.map_position_x, sfac.map_position_x, sfic.map_position_x, smc.map_position_x, 0),
            'map_position_y', coalesce(sfc.map_position_y, sfac.map_position_y, sfic.map_position_y, smc.map_position_y, 0)
          )
        )
      end as seller_production_inventory,
      case
        when bpi.id is null then null
        else jsonb_build_object(
          'id', bpi.id,
          'name', coalesce(bf.name, bfa.name, bfi.name, bm.name, 'Uretim'),
          'kind', 'production_inventory',
          'city', jsonb_build_object(
            'id', coalesce(bfc.id, bfac.id, bfic.id, bmc.id),
            'name', coalesce(bfc.name, bfac.name, bfic.name, bmc.name, 'Sehir'),
            'map_position_x', coalesce(bfc.map_position_x, bfac.map_position_x, bfic.map_position_x, bmc.map_position_x, 0),
            'map_position_y', coalesce(bfc.map_position_y, bfac.map_position_y, bfic.map_position_y, bmc.map_position_y, 0)
          )
        )
      end as buyer_production_inventory
    from public.logistics_transfers lt
    left join public.products p on p.id = lt.product_id
    left join public.warehouses sw on sw.id = lt.seller_warehouse_id
    left join public.cities swc on swc.id = sw.city_id
    left join public.warehouses bw on bw.id = lt.buyer_warehouse_id
    left join public.cities bwc on bwc.id = bw.city_id
    left join public.stores ss on ss.id = lt.seller_store_id
    left join public.cities ssc on ssc.id = ss.city_id
    left join public.stores bs on bs.id = lt.buyer_store_id
    left join public.cities bsc on bsc.id = bs.city_id
    left join public.production_inventory spi on spi.id = lt.seller_production_inventory_id
    left join public.factories sf on spi.owner_kind = 'factory' and sf.id = spi.owner_id
    left join public.cities sfc on sfc.id = sf.city_id
    left join public.farms sfa on spi.owner_kind = 'farm' and sfa.id = spi.owner_id
    left join public.cities sfac on sfac.id = sfa.city_id
    left join public.fields sfi on spi.owner_kind = 'field' and sfi.id = spi.owner_id
    left join public.cities sfic on sfic.id = sfi.city_id
    left join public.mines sm on spi.owner_kind = 'mine' and sm.id = spi.owner_id
    left join public.cities smc on smc.id = sm.city_id
    left join public.production_inventory bpi on bpi.id = lt.buyer_production_inventory_id
    left join public.factories bf on bpi.owner_kind = 'factory' and bf.id = bpi.owner_id
    left join public.cities bfc on bfc.id = bf.city_id
    left join public.farms bfa on bpi.owner_kind = 'farm' and bfa.id = bpi.owner_id
    left join public.cities bfac on bfac.id = bfa.city_id
    left join public.fields bfi on bpi.owner_kind = 'field' and bfi.id = bpi.owner_id
    left join public.cities bfic on bfic.id = bfi.city_id
    left join public.mines bm on bpi.owner_kind = 'mine' and bm.id = bpi.owner_id
    left join public.cities bmc on bmc.id = bm.city_id
    where lt.buyer_player_id = v_player_id
      and lt.status = 'in_transit'
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'quantity', quantity,
        'item_count', item_count,
        'total_quantity', total_quantity,
        'quality_level', quality_level,
        'brand_id', brand_id,
        'status', status,
        'transfer_type', transfer_type,
        'is_rental', is_rental,
        'total_price', total_price,
        'rental_cost', rental_cost,
        'transport_cost', transport_cost,
        'started_at', started_at,
        'finish_at', finish_at,
        'completed_at', completed_at,
        'seller_entity_kind', seller_entity_kind,
        'buyer_entity_kind', buyer_entity_kind,
        'product', product,
        'seller_warehouse', seller_warehouse,
        'buyer_warehouse', buyer_warehouse,
        'seller_store', seller_store,
        'buyer_store', buyer_store,
        'seller_production_inventory', seller_production_inventory,
        'buyer_production_inventory', buyer_production_inventory
      )
      order by finish_at asc, started_at asc, id asc
    ),
    '[]'::jsonb
  )
  into v_result
  from base;

  return v_result;
end;
$function$;

-- Function: get_cities_catalog
CREATE OR REPLACE FUNCTION public.get_cities_catalog(p_only_active boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(c) order by c.name),
    '[]'::jsonb
  )
  from public.cities c
  where (not p_only_active) or c.is_active = true;
$function$;

-- Function: get_city_consolidated_transfer_candidates
CREATE OR REPLACE FUNCTION public.get_city_consolidated_transfer_candidates(p_source_city_id uuid, p_target_entity_kind text DEFAULT NULL::text, p_target_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_candidates jsonb := '[]'::jsonb;
  v_accepted_product_ids text[];
BEGIN
  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Oturum acilmamis.';
  END IF;

  -- Hedef tesis belirtildiyse kabul ettiği ürünleri belirle
  IF p_target_entity_kind = 'factory' AND p_target_entity_id IS NOT NULL THEN
    SELECT array_agg(DISTINCT pi.product_id)
    INTO v_accepted_product_ids
    FROM public.production_inventory pi
    WHERE pi.owner_kind = 'factory' AND pi.owner_id = p_target_entity_id AND pi.inventory_type = 'input';
  ELSIF p_target_entity_kind = 'store' AND p_target_entity_id IS NOT NULL THEN
    SELECT string_to_array(st.accepted_product_ids, ',')
    INTO v_accepted_product_ids
    FROM public.stores s
    JOIN public.store_types st ON st.id = s.store_type_id
    WHERE s.id = p_target_entity_id;
  END IF;
  -- Depo ('warehouse') ise veya hedef belirtilmediyse (NULL) tüm ürünler döner.

  WITH city_products AS (
    -- 1. Depolardaki Ürünler
    SELECT
      'warehouse'::text AS source_kind,
      'Depo'::text AS source_kind_display,
      w.id AS source_id,
      w.name AS source_name,
      ws.id AS item_id,
      ws.product_id,
      p.urun_adi AS product_name,
      p.urun_iconu AS product_icon,
      p.birim_hacim,
      ws.quantity,
      ws.quality_level,
      coalesce(ws.cost, 0)::numeric AS unit_cost,
      ws.brand_id,
      coalesce(b.brand_name, 'Standart') AS brand_name
    FROM public.warehouses w
    JOIN public.warehouse_slots ws ON ws.warehouse_id = w.id
    JOIN public.products p ON p.id = ws.product_id
    LEFT JOIN public.brand_companies b ON b.id = ws.brand_id
    WHERE w.player_id = v_player_id
      AND w.city_id = p_source_city_id
      AND w.is_active = true
      AND ws.quantity > 0
      AND (v_accepted_product_ids IS NULL OR ws.product_id = ANY(v_accepted_product_ids))

    UNION ALL

    -- 2. Fabrika Çıktı Ürünleri
    SELECT
      'factory'::text AS source_kind,
      'Fabrika'::text AS source_kind_display,
      f.id AS source_id,
      f.name AS source_name,
      pi.id AS item_id,
      pi.product_id,
      p.urun_adi AS product_name,
      p.urun_iconu AS product_icon,
      p.birim_hacim,
      pi.quantity,
      pi.quality_level,
      coalesce(pi.cost, 0)::numeric AS unit_cost,
      pi.brand_id,
      coalesce(b.brand_name, 'Standart') AS brand_name
    FROM public.factories f
    JOIN public.production_inventory pi ON pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'output'
    JOIN public.products p ON p.id = pi.product_id
    LEFT JOIN public.brand_companies b ON b.id = pi.brand_id
    WHERE f.player_id = v_player_id
      AND f.city_id = p_source_city_id
      AND pi.quantity > 0
      AND (v_accepted_product_ids IS NULL OR pi.product_id = ANY(v_accepted_product_ids))

    UNION ALL

    -- 3. Tarla Çıktı Ürünleri
    SELECT
      'farm'::text AS source_kind,
      'Tarla'::text AS source_kind_display,
      fa.id AS source_id,
      fa.name AS source_name,
      pi.id AS item_id,
      pi.product_id,
      p.urun_adi AS product_name,
      p.urun_iconu AS product_icon,
      p.birim_hacim,
      pi.quantity,
      pi.quality_level,
      coalesce(pi.cost, 0)::numeric AS unit_cost,
      pi.brand_id,
      coalesce(b.brand_name, 'Standart') AS brand_name
    FROM public.farms fa
    JOIN public.production_inventory pi ON pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'output'
    JOIN public.products p ON p.id = pi.product_id
    LEFT JOIN public.brand_companies b ON b.id = pi.brand_id
    WHERE fa.player_id = v_player_id
      AND fa.city_id = p_source_city_id
      AND pi.quantity > 0
      AND (v_accepted_product_ids IS NULL OR pi.product_id = ANY(v_accepted_product_ids))

    UNION ALL

    -- 4. Çiftlik Çıktı Ürünleri
    SELECT
      'field'::text AS source_kind,
      'Çiftlik'::text AS source_kind_display,
      fld.id AS source_id,
      fld.name AS source_name,
      pi.id AS item_id,
      pi.product_id,
      p.urun_adi AS product_name,
      p.urun_iconu AS product_icon,
      p.birim_hacim,
      pi.quantity,
      pi.quality_level,
      coalesce(pi.cost, 0)::numeric AS unit_cost,
      pi.brand_id,
      coalesce(b.brand_name, 'Standart') AS brand_name
    FROM public.fields fld
    JOIN public.production_inventory pi ON pi.owner_kind = 'field' AND pi.owner_id = fld.id AND pi.inventory_type = 'output'
    JOIN public.products p ON p.id = pi.product_id
    LEFT JOIN public.brand_companies b ON b.id = pi.brand_id
    WHERE fld.player_id = v_player_id
      AND fld.city_id = p_source_city_id
      AND pi.quantity > 0
      AND (v_accepted_product_ids IS NULL OR pi.product_id = ANY(v_accepted_product_ids))

    UNION ALL

    -- 5. Maden Çıktı Ürünleri
    SELECT
      'mine'::text AS source_kind,
      'Maden'::text AS source_kind_display,
      m.id AS source_id,
      m.name AS source_name,
      pi.id AS item_id,
      pi.product_id,
      p.urun_adi AS product_name,
      p.urun_iconu AS product_icon,
      p.birim_hacim,
      pi.quantity,
      pi.quality_level,
      coalesce(pi.cost, 0)::numeric AS unit_cost,
      pi.brand_id,
      coalesce(b.brand_name, 'Standart') AS brand_name
    FROM public.mines m
    JOIN public.production_inventory pi ON pi.owner_kind = 'mine' AND pi.owner_id = m.id AND pi.inventory_type = 'output'
    JOIN public.products p ON p.id = pi.product_id
    LEFT JOIN public.brand_companies b ON b.id = pi.brand_id
    WHERE m.player_id = v_player_id
      AND m.city_id = p_source_city_id
      AND pi.quantity > 0
      AND (v_accepted_product_ids IS NULL OR pi.product_id = ANY(v_accepted_product_ids))
  )
  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'source_kind', cp.source_kind,
      'source_kind_display', cp.source_kind_display,
      'source_id', cp.source_id,
      'source_name', cp.source_name,
      'item_id', cp.item_id,
      'product_id', cp.product_id,
      'product_name', cp.product_name,
      'product_icon', cp.product_icon,
      'birim_hacim', cp.birim_hacim,
      'quantity', cp.quantity,
      'quality_level', cp.quality_level,
      'unit_cost', cp.unit_cost,
      'brand_id', cp.brand_id,
      'brand_name', cp.brand_name
    )
    ORDER BY cp.source_kind, cp.source_name, cp.product_name
  ), '[]'::jsonb)
  INTO v_candidates
  FROM city_products cp;

  RETURN v_candidates;
END;
$function$;

-- Function: get_city_consolidated_transfer_source_cities
CREATE OR REPLACE FUNCTION public.get_city_consolidated_transfer_source_cities()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_cities jsonb := '[]'::jsonb;
BEGIN
  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Oturum acilmamis.';
  END IF;

  WITH city_entities AS (
    -- Depolar (Tüm aktif depolar)
    SELECT w.city_id, 'warehouse' as kind, w.id as entity_id,
           coalesce((SELECT sum(ws.quantity) FROM public.warehouse_slots ws WHERE ws.warehouse_id = w.id AND ws.quantity > 0), 0) as stock
    FROM public.warehouses w
    WHERE w.player_id = v_player_id AND w.is_active = true

    UNION ALL

    -- Fabrikalar (Çıktı Deposu)
    SELECT f.city_id, 'factory' as kind, f.id as entity_id,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'output' AND pi.quantity > 0), 0) as stock
    FROM public.factories f
    WHERE f.player_id = v_player_id

    UNION ALL

    -- Tarlalar (Çıktı Deposu)
    SELECT fa.city_id, 'farm' as kind, fa.id as entity_id,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'output' AND pi.quantity > 0), 0) as stock
    FROM public.farms fa
    WHERE fa.player_id = v_player_id

    UNION ALL

    -- Çiftlikler (Çıktı Deposu)
    SELECT fld.city_id, 'field' as kind, fld.id as entity_id,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'field' AND pi.owner_id = fld.id AND pi.inventory_type = 'output' AND pi.quantity > 0), 0) as stock
    FROM public.fields fld
    WHERE fld.player_id = v_player_id

    UNION ALL

    -- Madenler (Çıktı Deposu)
    SELECT m.city_id, 'mine' as kind, m.id as entity_id,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'mine' AND pi.owner_id = m.id AND pi.inventory_type = 'output' AND pi.quantity > 0), 0) as stock
    FROM public.mines m
    WHERE m.player_id = v_player_id
  ),
  city_summaries AS (
    SELECT
      c.id AS city_id,
      c.name AS city_name,
      c.map_position_x,
      c.map_position_y,
      count(DISTINCT ce.entity_id) AS facility_count,
      sum(ce.stock)::integer AS total_stock
    FROM city_entities ce
    JOIN public.cities c ON c.id = ce.city_id
    GROUP BY c.id, c.name, c.map_position_x, c.map_position_y
    HAVING sum(ce.stock) > 0
  )
  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'city_id', cs.city_id,
      'city_name', cs.city_name,
      'map_position_x', cs.map_position_x,
      'map_position_y', cs.map_position_y,
      'facility_count', cs.facility_count,
      'total_stock', cs.total_stock
    )
    ORDER BY cs.total_stock DESC, cs.city_name
  ), '[]'::jsonb)
  INTO v_cities
  FROM city_summaries cs;

  RETURN v_cities;
END;
$function$;

-- Function: get_city_consolidated_transfer_targets
CREATE OR REPLACE FUNCTION public.get_city_consolidated_transfer_targets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_targets jsonb := '[]'::jsonb;
BEGIN
  IF v_player_id IS NULL THEN
    RAISE EXCEPTION 'Oturum acilmamis.';
  END IF;

  WITH all_targets AS (
    -- Depolar (Normal/Genel Depolar ve Özel Depolar)
    SELECT
      w.id,
      w.name,
      'warehouse'::text AS entity_kind,
      'Depo'::text AS entity_kind_display,
      w.city_id,
      c.name AS city_name,
      coalesce(w.capacity, 0)::numeric AS total_capacity,
      coalesce((
        SELECT sum(ws.quantity * coalesce(p.birim_hacim, 1))
        FROM public.warehouse_slots ws
        JOIN public.products p ON p.id = ws.product_id
        WHERE ws.warehouse_id = w.id
      ), 0)::numeric AS used_capacity,
      coalesce(w.reserved_capacity, 0)::numeric AS reserved_capacity,
      CASE 
        WHEN wt.accepted_product_ids IS NOT NULL AND trim(wt.accepted_product_ids) <> '' AND wt.name <> 'Genel Depo'
        THEN regexp_split_to_array(trim(wt.accepted_product_ids), '\s*,\s*')
        ELSE NULL::text[]
      END AS accepted_product_ids,
      '{}'::jsonb AS accepted_product_qualities,
      1::integer AS min_quality_level
    FROM public.warehouses w
    JOIN public.cities c ON c.id = w.city_id
    LEFT JOIN public.warehouse_types wt ON wt.id = w.warehouse_type_id
    WHERE w.player_id = v_player_id
      AND w.is_active = true
      AND (w.warehouse_kind = 'normal' OR w.warehouse_kind = 'general' OR w.store_id IS NULL)

    UNION ALL

    -- Fabrikalar (Girdi Deposu) -> Reçetesindeki girdi ürünlerini ve gereken kalitelerini kabul eder
    SELECT
      f.id,
      f.name,
      'factory'::text AS entity_kind,
      'Fabrika'::text AS entity_kind_display,
      f.city_id,
      c.name AS city_name,
      coalesce(f.input_capacity, 0)::numeric AS total_capacity,
      coalesce((
        SELECT sum(pi.quantity * coalesce(p.birim_hacim, 1))
        FROM public.production_inventory pi
        JOIN public.products p ON p.id = pi.product_id
        WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'input'
      ), 0)::numeric AS used_capacity,
      0::numeric AS reserved_capacity,
      coalesce((
        SELECT array_agg(DISTINCT pi.product_id)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'input'
      ), ARRAY[]::text[]) AS accepted_product_ids,
      coalesce((
        SELECT jsonb_object_agg(pi.product_id, pi.quality_level)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'input'
      ), '{}'::jsonb) AS accepted_product_qualities,
      coalesce(
        (SELECT min(pi.quality_level) FROM public.production_inventory pi WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'input'),
        CASE WHEN coalesce(f.quality_level, 1) <= 2 THEN 1 ELSE coalesce(f.quality_level, 1) - 1 END
      )::integer AS min_quality_level
    FROM public.factories f
    JOIN public.cities c ON c.id = f.city_id
    WHERE f.player_id = v_player_id AND f.is_active = true

    UNION ALL

    -- Tarlalar (Girdi Alanı) -> Ekili ürünlerin gerektirdiği gübre/tohum girdilerini kabul eder
    SELECT
      fa.id,
      fa.name,
      'farm'::text AS entity_kind,
      'Tarla'::text AS entity_kind_display,
      fa.city_id,
      c.name AS city_name,
      coalesce(fa.input_capacity, 0)::numeric AS total_capacity,
      coalesce((
        SELECT sum(pi.quantity * coalesce(p.birim_hacim, 1))
        FROM public.production_inventory pi
        JOIN public.products p ON p.id = pi.product_id
        WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'input'
      ), 0)::numeric AS used_capacity,
      0::numeric AS reserved_capacity,
      coalesce((
        SELECT array_agg(DISTINCT pi.product_id)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'input'
      ), ARRAY[]::text[]) AS accepted_product_ids,
      coalesce((
        SELECT jsonb_object_agg(pi.product_id, pi.quality_level)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'input'
      ), '{}'::jsonb) AS accepted_product_qualities,
      coalesce(
        (SELECT min(pi.quality_level) FROM public.production_inventory pi WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'input'),
        CASE WHEN coalesce(fa.level, 1) <= 2 THEN 1 ELSE coalesce(fa.level, 1) - 1 END
      )::integer AS min_quality_level
    FROM public.farms fa
    JOIN public.cities c ON c.id = fa.city_id
    WHERE fa.player_id = v_player_id AND fa.is_active = true

    UNION ALL

    -- Çiftlikler (Girdi / Yem Deposu) -> Beslenen hayvanların yem/hammadde girdilerini kabul eder
    SELECT
      fi.id,
      fi.name,
      'field'::text AS entity_kind,
      'Çiftlik'::text AS entity_kind_display,
      fi.city_id,
      c.name AS city_name,
      coalesce(fi.input_capacity, 0)::numeric AS total_capacity,
      coalesce((
        SELECT sum(pi.quantity * coalesce(p.birim_hacim, 1))
        FROM public.production_inventory pi
        JOIN public.products p ON p.id = pi.product_id
        WHERE pi.owner_kind = 'field' AND pi.owner_id = fi.id AND pi.inventory_type = 'input'
      ), 0)::numeric AS used_capacity,
      0::numeric AS reserved_capacity,
      coalesce((
        SELECT array_agg(DISTINCT pi.product_id)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'field' AND pi.owner_id = fi.id AND pi.inventory_type = 'input'
      ), ARRAY[]::text[]) AS accepted_product_ids,
      coalesce((
        SELECT jsonb_object_agg(pi.product_id, pi.quality_level)
        FROM public.production_inventory pi
        WHERE pi.owner_kind = 'field' AND pi.owner_id = fi.id AND pi.inventory_type = 'input'
      ), '{}'::jsonb) AS accepted_product_qualities,
      coalesce(
        (SELECT min(pi.quality_level) FROM public.production_inventory pi WHERE pi.owner_kind = 'field' AND pi.owner_id = fi.id AND pi.inventory_type = 'input'),
        CASE WHEN coalesce(fi.level, 1) <= 2 THEN 1 ELSE coalesce(fi.level, 1) - 1 END
      )::integer AS min_quality_level
    FROM public.fields fi
    JOIN public.cities c ON c.id = fi.city_id
    WHERE fi.player_id = v_player_id AND fi.is_active = true

    UNION ALL

    -- Mağazalar (Mağaza Deposu) -> Mağaza türünün kabul ettiği ürünleri kabul eder
    SELECT
      s.id,
      s.name,
      'store'::text AS entity_kind,
      'Mağaza'::text AS entity_kind_display,
      s.city_id,
      c.name AS city_name,
      coalesce(w.capacity, 0)::numeric AS total_capacity,
      coalesce((
        SELECT sum(ws.quantity * coalesce(p.birim_hacim, 1))
        FROM public.warehouse_slots ws
        JOIN public.products p ON p.id = ws.product_id
        WHERE ws.warehouse_id = w.id
      ), 0)::numeric AS used_capacity,
      coalesce(w.reserved_capacity, 0)::numeric AS reserved_capacity,
      string_to_array(st.accepted_product_ids, ',') AS accepted_product_ids,
      '{}'::jsonb AS accepted_product_qualities,
      1::integer AS min_quality_level
    FROM public.stores s
    JOIN public.cities c ON c.id = s.city_id
    JOIN public.store_types st ON st.id = s.store_type_id
    JOIN public.warehouses w ON w.store_id = s.id AND w.warehouse_kind = 'store' AND w.is_active = true
    WHERE s.player_id = v_player_id AND s.is_active = true
  )
  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'id', t.id,
      'name', t.name,
      'entity_kind', t.entity_kind,
      'entity_kind_display', t.entity_kind_display,
      'city_id', t.city_id,
      'city_name', t.city_name,
      'total_capacity', t.total_capacity,
      'used_capacity', t.used_capacity,
      'empty_capacity', greatest(0, round(t.total_capacity - t.used_capacity - t.reserved_capacity, 2)),
      'accepted_product_ids', t.accepted_product_ids,
      'accepted_product_qualities', t.accepted_product_qualities,
      'min_quality_level', t.min_quality_level
    )
    ORDER BY t.city_name, t.entity_kind, t.name
  ), '[]'::jsonb)
  INTO v_targets
  FROM all_targets t;

  RETURN v_targets;
END;
$function$;

-- Function: get_city_map_detail
CREATE OR REPLACE FUNCTION public.get_city_map_detail(p_city_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'map_position_x', c.map_position_x,
    'map_position_y', c.map_position_y
  )
  from public.cities c
  where c.id = p_city_id;
$function$;

-- Function: get_city_store_saturations
CREATE OR REPLACE FUNCTION public.get_city_store_saturations(p_city_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pop integer;
  v_result jsonb := '[]'::jsonb;
BEGIN
  SELECT population INTO v_pop FROM public.cities WHERE id = p_city_id;
  IF NOT FOUND OR coalesce(v_pop, 0) <= 0 THEN
    v_pop := 500000;
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'store_type_id', st.id,
    'store_type_name', st.name,
    'city_id', p_city_id,
    'population', v_pop,
    'ideal_capacity', calc.ideal_capacity,
    'current_count', calc.current_count,
    'saturation_pct', calc.saturation_pct,
    'demand_multiplier', calc.demand_multiplier,
    'status', calc.status,
    'status_label', calc.status_label
  ) ORDER BY st.required_level, st.cost), '[]'::jsonb)
  INTO v_result
  FROM public.store_types st
  CROSS JOIN LATERAL (
    SELECT
      ideal_cap.val AS ideal_capacity,
      curr_cnt.val AS current_count,
      round((curr_cnt.val::numeric / ideal_cap.val::numeric) * 100, 1) AS saturation_pct,
      mult.val AS demand_multiplier,
      CASE
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) < 0.5 THEN 'opportunity'
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) <= 1.0 THEN 'balanced'
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) <= 1.5 THEN 'competitive'
        ELSE 'saturated'
      END AS status,
      CASE
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) < 0.5 THEN format('Pazar Boşluğu (+%%%s Talep)', round((mult.val - 1.0) * 100)::text)
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) <= 1.0 THEN 'Dengeli Pazar'
        WHEN (curr_cnt.val::numeric / ideal_cap.val::numeric) <= 1.5 THEN format('Yüksek Rekabet (-%%%s Talep)', round((1.0 - mult.val) * 100)::text)
        ELSE format('Aşırı Doygun (-%%%s Talep)', round((1.0 - mult.val) * 100)::text)
      END AS status_label
    FROM (
      SELECT greatest(1, round(v_pop::numeric / (CASE st.name
        WHEN 'Büfe' THEN 50000
        WHEN 'Manav' THEN 60000
        WHEN 'Market' THEN 75000
        WHEN 'Fırın' THEN 80000
        WHEN 'Kasap' THEN 90000
        WHEN 'Kuruyemişçi' THEN 100000
        WHEN 'Süpermarket' THEN 150000
        WHEN 'Tekstil Mağazası' THEN 180000
        WHEN 'Mobilya Mağazası' THEN 220000
        WHEN 'Kozmetik Mağazası' THEN 250000
        WHEN 'Beyaz Eşya' THEN 280000
        WHEN 'Teknoloji ve Elektronik' THEN 320000
        WHEN 'İnşaat Malzemeleri' THEN 350000
        WHEN 'Kuyumcu' THEN 400000
        WHEN 'Oto Galeri' THEN 500000
        ELSE 100000
      END))::integer) AS val
    ) ideal_cap
    CROSS JOIN (
      SELECT count(*)::integer AS val
      FROM public.stores s
      WHERE s.city_id = p_city_id
        AND s.store_type_id = st.id
        AND s.is_active = true
    ) curr_cnt
    CROSS JOIN (
      SELECT public.calculate_store_saturation_multiplier(p_city_id, st.id) AS val
    ) mult
  ) calc;

  RETURN coalesce(v_result, '[]'::jsonb);
END;
$function$;

-- Function: get_experience_required_for_level
CREATE OR REPLACE FUNCTION public.get_experience_required_for_level(p_level integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  return greatest(250, 250 * greatest(coalesce(p_level, 1), 1));
end;
$function$;

-- Function: get_factory_detail_data
CREATE OR REPLACE FUNCTION public.get_factory_detail_data(p_factory_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'factory',
      to_jsonb(f) || jsonb_build_object(
        'boost_multiplier',
        coalesce((
          select bb.multiplier
          from public.building_boosts bb
          where bb.player_id = auth.uid()
            and bb.building_kind = 'factory'
            and bb.entity_id = f.id
            and bb.status = 'in_progress'
            and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
          order by bb.started_at desc
          limit 1
        ), 1.00)
      ),
    'factory_type', to_jsonb(ft),
    'city_name', coalesce(c.name, 'Bilinmeyen Sehir'),
    'product', case when p.id is null then null else to_jsonb(p) end,
    'inventories',
      coalesce((
        select jsonb_agg(
          to_jsonb(pi) || jsonb_build_object(
            'product',
            case when prod.id is null then null else to_jsonb(prod) end
          )
          order by pi.id
        )
        from public.production_inventory pi
        left join public.products prod on prod.id = pi.product_id
        where pi.owner_kind = 'factory'
          and pi.owner_id = f.id
      ), '[]'::jsonb)
  )
  from public.factories f
  left join public.factory_types ft on ft.id = f.factory_type_id
  left join public.cities c on c.id = f.city_id
  left join public.products p on p.id = f.product_id
  where f.id = p_factory_id
    and f.player_id = auth.uid();
$function$;

-- Function: get_factory_list_items
CREATE OR REPLACE FUNCTION public.get_factory_list_items()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'factory',
          to_jsonb(f) || jsonb_build_object(
            'boost_multiplier',
            coalesce((
              select bb.multiplier
              from public.building_boosts bb
              where bb.player_id = auth.uid()
                and bb.building_kind = 'factory'
                and bb.entity_id = f.id
                and bb.status = 'in_progress'
                and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
              order by bb.started_at desc
              limit 1
            ), 1.00)
          ),
        'city_name', c.name,
        'factory_type_name', coalesce(ft.name, 'Bilinmeyen Fabrika'),
        'factory_type_icon', coalesce(ft.icon, 'factory.webp'),
        'input_stock_quantity',
          coalesce((
            select sum(pi.quantity)::int
            from public.production_inventory pi
            where pi.owner_kind = 'factory'
              and pi.owner_id = f.id
              and pi.inventory_type = 'input'
          ), 0),
        'output_stock_quantity',
          coalesce((
            select sum(pi.quantity)::int
            from public.production_inventory pi
            where pi.owner_kind = 'factory'
              and pi.owner_id = f.id
              and pi.inventory_type = 'output'
          ), 0),
        'selected_product',
          case when p.id is null then null else to_jsonb(p) end
      )
      order by f.created_at
    ),
    '[]'::jsonb
  )
  from public.factories f
  left join public.cities c on c.id = f.city_id
  left join public.factory_types ft on ft.id = f.factory_type_id
  left join public.products p on p.id = f.product_id
  where f.player_id = auth.uid();
$function$;

-- Function: get_factory_types_catalog
CREATE OR REPLACE FUNCTION public.get_factory_types_catalog()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(ft) order by ft.required_level, ft.cost),
    '[]'::jsonb
  )
  from public.factory_types ft;
$function$;

-- Function: get_farm_detail
CREATE OR REPLACE FUNCTION public.get_farm_detail(p_player_id uuid, p_farm_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_auth_user uuid := auth.uid();
  v_farm record;
  v_farm_type record;
  v_city_name text;
  v_slots jsonb := '[]'::jsonb;
  v_inventories jsonb := '[]'::jsonb;
  v_active_boost_multiplier numeric := 1.00;
begin
  if v_auth_user is null then
    raise exception 'Oturum bulunamadi.';
  end if;

  if v_auth_user <> p_player_id then
    raise exception 'Yetkisiz istek.';
  end if;

  select f.*, c.name as city_name
  into v_farm
  from public.farms f
  left join public.cities c on c.id = f.city_id
  where f.id = p_farm_id
    and f.player_id = p_player_id;

  if not found then
    raise exception 'Tarla bulunamadi veya oyuncuya ait degil.';
  end if;

  select *
  into v_farm_type
  from public.farm_types
  where id = v_farm.farm_type_id;

  select coalesce(bb.multiplier, 1.00)
  into v_active_boost_multiplier
  from public.building_boosts bb
  where bb.player_id = p_player_id
    and bb.building_kind = 'farm'
    and bb.entity_id = p_farm_id
    and bb.status = 'in_progress'
    and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
  order by bb.started_at desc
  limit 1;

  v_city_name := coalesce(v_farm.city_name, 'Bilinmeyen Sehir');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', ps.id,
        'owner_kind', ps.owner_kind,
        'owner_id', ps.owner_id,
        'slot_index', ps.slot_index,
        'product_id', ps.product_id,
        'brand_id', ps.brand_id,
        'quality_level', ps.quality_level,
        'boost_multiplier', coalesce(v_active_boost_multiplier, 1.00),
        'is_active', ps.is_active,
        'product', case
          when p.id is null then null
          else jsonb_build_object(
            'id', p.id,
            'urun_adi', p.urun_adi,
            'urun_iconu', p.urun_iconu,
            'birim_hacim', p.birim_hacim,
            'birim_agirlik', p.birim_agirlik,
            'hammadde_1_id', p.hammadde_1_id,
            'hammadde_1_miktar', p.hammadde_1_miktar,
            'hammadde_2_id', p.hammadde_2_id,
            'hammadde_2_miktar', p.hammadde_2_miktar,
            'hammadde_3_id', p.hammadde_3_id,
            'hammadde_3_miktar', p.hammadde_3_miktar,
            'uretim_birimi', p.uretim_birimi,
            'baz_satis_fiyati', p.baz_satis_fiyati,
            'uretim_adedi', p.uretim_adedi,
            'satis_adedi', p.satis_adedi,
            'en_dusuk_fiyat', p.en_dusuk_fiyat,
            'en_yuksek_fiyat', p.en_yuksek_fiyat,
            'ortalama_fiyat', p.ortalama_fiyat,
            'satici_sayisi', p.satici_sayisi,
            'piyasadaki_stok', p.piyasadaki_stok,
            'created_at', p.created_at
          )
        end
      )
      order by ps.slot_index
    ),
    '[]'::jsonb
  )
  into v_slots
  from public.production_slots ps
  left join public.products p on p.id = ps.product_id
  where ps.owner_kind = 'farm'
    and ps.owner_id = p_farm_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pi.id,
        'owner_kind', pi.owner_kind,
        'owner_id', pi.owner_id,
        'inventory_type', pi.inventory_type,
        'product_id', pi.product_id,
        'brand_id', pi.brand_id,
        'quality_level', pi.quality_level,
        'quantity', pi.quantity,
        'pending_quantity', pi.pending_quantity,
        'cost', pi.cost,
        'product', case
          when p.id is null then null
          else jsonb_build_object(
            'id', p.id,
            'urun_adi', p.urun_adi,
            'urun_iconu', p.urun_iconu,
            'birim_hacim', p.birim_hacim,
            'birim_agirlik', p.birim_agirlik,
            'hammadde_1_id', p.hammadde_1_id,
            'hammadde_1_miktar', p.hammadde_1_miktar,
            'hammadde_2_id', p.hammadde_2_id,
            'hammadde_2_miktar', p.hammadde_2_miktar,
            'hammadde_3_id', p.hammadde_3_id,
            'hammadde_3_miktar', p.hammadde_3_miktar,
            'uretim_birimi', p.uretim_birimi,
            'baz_satis_fiyati', p.baz_satis_fiyati,
            'uretim_adedi', p.uretim_adedi,
            'satis_adedi', p.satis_adedi,
            'en_dusuk_fiyat', p.en_dusuk_fiyat,
            'en_yuksek_fiyat', p.en_yuksek_fiyat,
            'ortalama_fiyat', p.ortalama_fiyat,
            'satici_sayisi', p.satici_sayisi,
            'piyasadaki_stok', p.piyasadaki_stok,
            'created_at', p.created_at
          )
        end
      )
      order by pi.inventory_type, pi.product_id, pi.quality_level
    ),
    '[]'::jsonb
  )
  into v_inventories
  from public.production_inventory pi
  left join public.products p on p.id = pi.product_id
  where pi.owner_kind = 'farm'
    and pi.owner_id = p_farm_id;

  return jsonb_build_object(
    'success', true,
    'farm', jsonb_build_object(
      'farm', to_jsonb(v_farm) - 'city_name',
      'farm_type', to_jsonb(v_farm_type),
      'city_name', v_city_name,
      'slots', v_slots,
      'inventories', v_inventories
    )
  );
end;
$function$;

-- Function: get_farm_list_items
CREATE OR REPLACE FUNCTION public.get_farm_list_items()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'farm', to_jsonb(f),
        'city_name', c.name,
        'farm_type_name', coalesce(ft.name, 'Bilinmeyen Tarla'),
        'farm_type_icon', coalesce(ft.icon, 'farm.webp'),
        'output_stock_quantity',
          coalesce((
            select sum(pi.quantity)::int
            from public.production_inventory pi
            where pi.owner_kind = 'farm'
              and pi.owner_id = f.id
              and pi.inventory_type = 'output'
          ), 0),
        'input_stock_quantity',
          coalesce((
            select sum(pi.quantity)::int
            from public.production_inventory pi
            where pi.owner_kind = 'farm'
              and pi.owner_id = f.id
              and pi.inventory_type = 'input'
          ), 0),
        'slots',
          coalesce((
            select jsonb_agg(
              (to_jsonb(ps) - 'boost_multiplier') || jsonb_build_object(
                'boost_multiplier',
                coalesce((
                  select bb.multiplier
                  from public.building_boosts bb
                  where bb.player_id = auth.uid()
                    and bb.building_kind = 'farm'
                    and bb.entity_id = f.id
                    and bb.status = 'in_progress'
                    and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
                  order by bb.started_at desc
                  limit 1
                ), 1.00),
                'product',
                case when p.id is null then null else to_jsonb(p) end
              )
              order by ps.slot_index
            )
            from public.production_slots ps
            left join public.products p on p.id = ps.product_id
            where ps.owner_kind = 'farm'
              and ps.owner_id = f.id
          ), '[]'::jsonb)
      )
      order by f.created_at
    ),
    '[]'::jsonb
  )
  from public.farms f
  left join public.cities c on c.id = f.city_id
  left join public.farm_types ft on ft.id = f.farm_type_id
  where f.player_id = auth.uid();
$function$;

-- Function: get_farm_types_catalog
CREATE OR REPLACE FUNCTION public.get_farm_types_catalog()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(ft) order by ft.required_level, ft.cost),
    '[]'::jsonb
  )
  from public.farm_types ft;
$function$;

-- Function: get_field_detail_data
CREATE OR REPLACE FUNCTION public.get_field_detail_data(p_field_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'field', to_jsonb(f),
    'field_type', to_jsonb(ft),
    'city_name', coalesce(c.name, 'Bilinmeyen Sehir'),
    'slots',
      coalesce((
        select jsonb_agg(
          (to_jsonb(ps) - 'boost_multiplier') || jsonb_build_object(
            'boost_multiplier',
            coalesce((
              select bb.multiplier
              from public.building_boosts bb
              where bb.player_id = auth.uid()
                and bb.building_kind = 'field'
                and bb.entity_id = f.id
                and bb.status = 'in_progress'
                and coalesce(bb.finish_at, timezone('utc'::text, now())) > timezone('utc'::text, now())
              order by bb.started_at desc
              limit 1
            ), 1.00),
            'product',
            case when p.id is null then null else to_jsonb(p) end
          )
          order by ps.slot_index
        )
        from public.production_slots ps
        left join public.products p on p.id = ps.product_id
        where ps.owner_kind = 'field'
          and ps.owner_id = f.id
      ), '[]'::jsonb),
    'inventories',
      coalesce((
        select jsonb_agg(
          to_jsonb(pi) || jsonb_build_object(
            'product',
            case when p.id is null then null else to_jsonb(p) end
          )
          order by pi.id
        )
        from public.production_inventory pi
        left join public.products p on p.id = pi.product_id
        where pi.owner_kind = 'field'
          and pi.owner_id = f.id
      ), '[]'::jsonb)
  )
  from public.fields f
  left join public.field_types ft on ft.id = f.field_type_id
  left join public.cities c on c.id = f.city_id
  where f.id = p_field_id
    and f.player_id = auth.uid();
$function$;

