-- Function: get_market_listings_for_city
CREATE OR REPLACE FUNCTION public.get_market_listings_for_city(p_city_id uuid)
 RETURNS TABLE(slot_id uuid, product_id text, product_name text, product_icon text, brand_id uuid, unit_volume numeric, warehouse_id uuid, warehouse_name text, warehouse_icon text, city_id uuid, city_name text, city_x numeric, city_y numeric, seller_player_id uuid, seller_player_name text, seller_avatar_id text, seller_google_avatar_url text, quantity integer, quality_level integer, price numeric, cost numeric, is_available_for_sale boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    ws.id as slot_id,
    ws.product_id,
    coalesce(pr.urun_adi, 'Urun') as product_name,
    coalesce(pr.urun_iconu, 'default.webp') as product_icon,
    coalesce(ws.brand_id, '00000000-0000-0000-0000-000000000000'::uuid) as brand_id,
    coalesce(pr.birim_hacim, 0) as unit_volume,
    w.id as warehouse_id,
    w.name as warehouse_name,
    wt.icon as warehouse_icon,
    c.id as city_id,
    c.name as city_name,
    c.map_position_x as city_x,
    c.map_position_y as city_y,
    w.player_id as seller_player_id,
    coalesce(pl.player_name, 'Oyuncu') as seller_player_name,
    coalesce(pl.avatar_id, 'ae1.webp') as seller_avatar_id,
    pl.google_avatar_url as seller_google_avatar_url,
    ws.quantity,
    ws.quality_level,
    ws.price,
    ws.cost,
    ws.is_available_for_sale
  from public.warehouse_slots ws
  join public.products pr on pr.id = ws.product_id
  join public.warehouses w on w.id = ws.warehouse_id
  join public.players pl on pl.id = w.player_id
  join public.cities c on c.id = w.city_id
  left join public.warehouse_types wt on wt.id = w.warehouse_type_id
  where w.city_id = p_city_id
    and ws.is_available_for_sale = true
    and ws.quantity > 0
    and coalesce(ws.price, 0) > 0
    and w.is_active = true
    and w.player_id <> auth.uid()
  order by ws.price asc, pr.urun_adi asc, ws.quality_level desc, ws.quantity desc, ws.updated_at desc;
$function$;

-- Function: get_market_listings_for_player
CREATE OR REPLACE FUNCTION public.get_market_listings_for_player(p_player_id uuid)
 RETURNS TABLE(slot_id uuid, product_id text, product_name text, product_icon text, brand_id uuid, brand_name text, brand_logo_id text, brand_theme_color text, unit_volume numeric, warehouse_id uuid, warehouse_name text, warehouse_icon text, city_id uuid, city_name text, city_x numeric, city_y numeric, seller_player_id uuid, seller_player_name text, seller_avatar_id text, seller_google_avatar_url text, quantity integer, quality_level integer, price numeric, cost numeric, is_available_for_sale boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    ws.id AS slot_id,
    ws.product_id,
    COALESCE(pr.urun_adi, 'Urun') AS product_name,
    COALESCE(pr.urun_iconu, 'default.webp') AS product_icon,
    COALESCE(ws.brand_id, '00000000-0000-0000-0000-000000000000'::uuid) AS brand_id,
    bc.brand_name AS brand_name,
    bc.logo_id AS brand_logo_id,
    bc.theme_color AS brand_theme_color,
    COALESCE(pr.birim_hacim, 0) AS unit_volume,
    w.id AS warehouse_id,
    w.name AS warehouse_name,
    wt.icon AS warehouse_icon,
    c.id AS city_id,
    c.name AS city_name,
    c.map_position_x AS city_x,
    c.map_position_y AS city_y,
    w.player_id AS seller_player_id,
    COALESCE(p.player_name, 'Oyuncu') AS seller_player_name,
    COALESCE(p.avatar_id, 'ae1.webp') AS seller_avatar_id,
    p.google_avatar_url AS seller_google_avatar_url,
    ws.quantity,
    ws.quality_level,
    ws.price,
    ws.cost,
    ws.is_available_for_sale
  FROM public.warehouse_slots ws
  JOIN public.products pr ON pr.id = ws.product_id
  JOIN public.warehouses w ON w.id = ws.warehouse_id
  JOIN public.players p ON p.id = w.player_id
  LEFT JOIN public.warehouse_types wt ON wt.id = w.warehouse_type_id
  LEFT JOIN public.cities c ON c.id = w.city_id
  LEFT JOIN public.brand_companies bc ON bc.id = ws.brand_id AND bc.is_active = true
  WHERE w.player_id = p_player_id
    AND ws.is_available_for_sale = true
    AND ws.quantity > 0
    AND COALESCE(ws.price, 0) > 0
    AND w.is_active = true
  ORDER BY ws.price ASC, ws.quality_level DESC, ws.quantity DESC, ws.updated_at DESC;
$function$;

-- Function: get_market_listings_for_product
CREATE OR REPLACE FUNCTION public.get_market_listings_for_product(p_product_id text)
 RETURNS TABLE(slot_id uuid, product_id text, product_name text, product_icon text, brand_id uuid, brand_name text, brand_logo_id text, brand_theme_color text, unit_volume numeric, warehouse_id uuid, warehouse_name text, warehouse_icon text, city_id uuid, city_name text, city_x numeric, city_y numeric, seller_player_id uuid, seller_player_name text, seller_avatar_id text, seller_google_avatar_url text, quantity integer, quality_level integer, price numeric, cost numeric, is_available_for_sale boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    ws.id AS slot_id,
    ws.product_id,
    COALESCE(pr.urun_adi, 'Urun') AS product_name,
    COALESCE(pr.urun_iconu, 'default.webp') AS product_icon,
    COALESCE(ws.brand_id, '00000000-0000-0000-0000-000000000000'::uuid) AS brand_id,
    bc.brand_name AS brand_name,
    bc.logo_id AS brand_logo_id,
    bc.theme_color AS brand_theme_color,
    COALESCE(pr.birim_hacim, 0) AS unit_volume,
    w.id AS warehouse_id,
    w.name AS warehouse_name,
    wt.icon AS warehouse_icon,
    c.id AS city_id,
    c.name AS city_name,
    c.map_position_x AS city_x,
