-- Function: get_npc_logistics_player_id
CREATE OR REPLACE FUNCTION public.get_npc_logistics_player_id()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid;
BEGIN
  SELECT value_text::uuid
  INTO v_player_id
  FROM public.game_settings
  WHERE key = 'npc_logistics_player_id';

  IF v_player_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.players WHERE id = v_player_id) THEN
    v_player_id := public.ensure_npc_logistics_account();
  END IF;

  RETURN v_player_id;
END;
$function$;

-- Function: get_npc_rental_vehicle_option
CREATE OR REPLACE FUNCTION public.get_npc_rental_vehicle_option(p_from_city_id uuid, p_to_city_id uuid, p_distance_km numeric)
 RETURNS TABLE(vehicle_id uuid, vehicle_owner_player_id uuid, vehicle_name text, is_rental boolean, capacity integer, speed_kmh integer, current_fuel integer, fuel_capacity integer, fuel_rate numeric, condition integer, rental_price numeric, distance_km numeric, fuel_needed numeric, condition_needed numeric, rental_cost numeric, estimated_duration_seconds integer, can_select boolean, disabled_reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_distance numeric := coalesce(p_distance_km, 0);
  v_type record;
  v_vehicle public.logistics_vehicles%rowtype;
begin
  if p_from_city_id is null or p_to_city_id is null or p_from_city_id = p_to_city_id then
    return;
  end if;

  for v_type in 
    select * 
    from public.logistics_vehicle_types 
    order by capacity asc, purchase_price asc
  loop
    v_vehicle := public.ensure_npc_rental_vehicle(p_from_city_id, p_to_city_id, v_type.id);

    vehicle_id := v_vehicle.id;
    vehicle_owner_player_id := v_vehicle.player_id;
    vehicle_name := v_type.name;
    is_rental := true;
    capacity := v_vehicle.capacity;
    speed_kmh := v_vehicle.speed_kmh;
    current_fuel := v_vehicle.current_fuel;
    fuel_capacity := v_vehicle.fuel_capacity;
    fuel_rate := v_vehicle.fuel_rate;
    condition := v_vehicle.condition;
    rental_price := v_vehicle.rental_price;
    distance_km := v_distance;
    fuel_needed := ceil(v_distance * coalesce(v_vehicle.fuel_rate, 0))::numeric;
    condition_needed := greatest(1, ceil(v_distance / 200.0))::numeric;
    rental_cost := ceil(v_distance * coalesce(v_vehicle.rental_price, 0))::numeric;
    estimated_duration_seconds := greatest(60, ceil((greatest(v_distance, 1) / greatest(v_vehicle.speed_kmh, 1)) * 120))::integer;
    can_select := true;
    disabled_reason := null::text;

    return next;
  end loop;
end;
$function$;

-- Function: get_player_achievement_dashboard
CREATE OR REPLACE FUNCTION public.get_player_achievement_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_featured_badges jsonb := '[]'::jsonb;
  v_active_achievements jsonb := '[]'::jsonb;
  v_unlocked_achievements jsonb := '[]'::jsonb;
  v_unlocked_count integer := 0;
  v_claimable_count integer := 0;
  v_total_count integer := 0;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  perform public.ensure_player_achievement_rows(v_player_id);
  perform public.sync_player_achievement_snapshot(v_player_id);

  select coalesce(
    jsonb_agg(public.build_player_achievement_payload(v_player_id, achievement_id) order by unlocked_at desc nulls last, display_order asc),
    '[]'::jsonb
  )
  into v_featured_badges
  from (
    select pa.achievement_id, pa.unlocked_at, ad.display_order
    from public.player_achievements pa
    join public.achievement_definitions ad on ad.id = pa.achievement_id
    where pa.player_id = v_player_id
      and pa.is_unlocked = true
      and ad.is_active = true
    order by (pa.reward_granted_at is null) desc, pa.unlocked_at desc nulls last, ad.display_order asc
    limit 6
  ) featured_pick;

  select coalesce(
    jsonb_agg(public.build_player_achievement_payload(v_player_id, achievement_id) order by sort_claimable desc, sort_ratio desc, display_order asc),
    '[]'::jsonb
  )
  into v_active_achievements
  from (
    select
      pa.achievement_id,
      ad.display_order,
      case when (pa.is_unlocked = true and pa.reward_granted_at is null) then 1 else 0 end as sort_claimable,
      least(1.0, greatest(pa.progress_count, 0)::numeric / greatest(ad.target_count, 1)::numeric) as sort_ratio
    from public.player_achievements pa
    join public.achievement_definitions ad on ad.id = pa.achievement_id
    where pa.player_id = v_player_id
      and ad.is_active = true
      and (pa.is_unlocked = false or pa.reward_granted_at is null)
    order by sort_claimable desc, sort_ratio desc, ad.display_order asc
  ) active_pick;

  select coalesce(
    jsonb_agg(public.build_player_achievement_payload(v_player_id, achievement_id) order by unlocked_at desc nulls last, display_order asc),
    '[]'::jsonb
  )
  into v_unlocked_achievements
  from (
    select pa.achievement_id, pa.unlocked_at, ad.display_order
    from public.player_achievements pa
    join public.achievement_definitions ad on ad.id = pa.achievement_id
    where pa.player_id = v_player_id
      and ad.is_active = true
      and pa.is_unlocked = true
      and pa.reward_granted_at is not null
    order by pa.unlocked_at desc nulls last, ad.display_order asc
  ) unlocked_pick;

  select
    count(*) filter (where pa.is_unlocked = true),
    count(*) filter (where pa.is_unlocked = true and pa.reward_granted_at is null),
    count(*)
  into v_unlocked_count, v_claimable_count, v_total_count
  from public.player_achievements pa
  join public.achievement_definitions ad on ad.id = pa.achievement_id
  where pa.player_id = v_player_id
    and ad.is_active = true;

  return jsonb_build_object(
    'success', true,
    'featured_badges', v_featured_badges,
    'active_achievements', v_active_achievements,
    'unlocked_achievements', v_unlocked_achievements,
    'summary', jsonb_build_object(
      'unlocked_count', coalesce(v_unlocked_count, 0),
      'claimable_count', coalesce(v_claimable_count, 0),
      'total_count', coalesce(v_total_count, 0)
    )
  );
end;
$function$;

