-- Function: get_player_active_products_data
CREATE OR REPLACE FUNCTION public.get_player_active_products_data(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stores jsonb;
  v_factories jsonb;
  v_farms jsonb;
  v_mines jsonb;
  v_fields jsonb;
  v_inventories jsonb;
BEGIN
  -- Query active stores and their filled slots
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'name', s.name,
    'store_slots', COALESCE(
      (
        SELECT jsonb_agg(jsonb_build_object(
          'product_id', ss.product_id,
          'quantity', ss.quantity,
          'products', jsonb_build_object(
            'urun_adi', p.urun_adi,
            'urun_iconu', p.urun_iconu
          )
        ))
        FROM public.store_slots ss
        JOIN public.products p ON p.id = ss.product_id
        WHERE ss.store_id = s.id AND ss.is_active = true AND ss.quantity > 0
      ),
      '[]'::jsonb
    )
  )), '[]'::jsonb)
  INTO v_stores
  FROM public.stores s
  WHERE s.player_id = p_player_id AND s.is_active = true;

  -- Query active factories
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', f.id,
    'name', f.name
  )), '[]'::jsonb)
  INTO v_factories
  FROM public.factories f
  WHERE f.player_id = p_player_id AND f.is_active = true;

  -- Query active farms
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', fm.id,
    'name', fm.name
  )), '[]'::jsonb)
  INTO v_farms
  FROM public.farms fm
  WHERE fm.player_id = p_player_id AND fm.is_active = true;

  -- Query active mines
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'name', m.name
  )), '[]'::jsonb)
  INTO v_mines
  FROM public.mines m
  WHERE m.player_id = p_player_id AND m.is_active = true;

  -- Query active fields
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', fld.id,
    'name', fld.name
  )), '[]'::jsonb)
  INTO v_fields
  FROM public.fields fld
  WHERE fld.player_id = p_player_id AND fld.is_active = true;

  -- Query active inventories
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'owner_id', pi.owner_id,
    'product_id', pi.product_id,
    'quantity', pi.quantity,
    'inventory_type', pi.inventory_type,
    'products', jsonb_build_object(
      'urun_adi', pr.urun_adi,
      'urun_iconu', pr.urun_iconu
    )
  )), '[]'::jsonb)
  INTO v_inventories
  FROM public.production_inventory pi
  JOIN public.products pr ON pr.id = pi.product_id
  WHERE pi.owner_id IN (
    SELECT id FROM public.factories WHERE player_id = p_player_id AND is_active = true
    UNION ALL
    SELECT id FROM public.farms WHERE player_id = p_player_id AND is_active = true
    UNION ALL
    SELECT id FROM public.fields WHERE player_id = p_player_id AND is_active = true
    UNION ALL
    SELECT id FROM public.mines WHERE player_id = p_player_id AND is_active = true
  )
  AND pi.quantity > 0;

  RETURN jsonb_build_object(
    'stores', v_stores,
    'factories', v_factories,
    'farms', v_farms,
    'mines', v_mines,
    'fields', v_fields,
    'inventories', v_inventories
  );
END;
$function$;

-- Function: get_player_active_warehouse_upgrade
CREATE OR REPLACE FUNCTION public.get_player_active_warehouse_upgrade(p_warehouse_id uuid)
 RETURNS building_upgrades
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select bu.*
  from public.building_upgrades bu
  join public.warehouses w on w.id = bu.entity_id
  where bu.building_kind = 'warehouse'
    and bu.entity_id = p_warehouse_id
    and bu.status = 'in_progress'
    and coalesce(bu.finish_at, timezone('utc', now())) > timezone('utc', now())
    and w.player_id = auth.uid()
  order by bu.started_at desc
  limit 1;
$function$;

-- Function: get_player_active_warehouses_basic
CREATE OR REPLACE FUNCTION public.get_player_active_warehouses_basic()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      (
        to_jsonb(w) ||
        jsonb_build_object(
          'reserved_capacity', w.reserved_capacity + coalesce(
            (
              select sum(coalesce(ws.quantity, 0) * coalesce(p.birim_hacim, 0))
              from public.warehouse_slots ws
              join public.products p on p.id = ws.product_id
              where ws.warehouse_id = w.id
            ),
            0
          ),
          'warehouse_slots',
          coalesce(
            (
              select jsonb_agg(
                to_jsonb(ws) ||
                jsonb_build_object('product', to_jsonb(p))
                order by ws.id
              )
              from public.warehouse_slots ws
              left join public.products p on p.id = ws.product_id
              where ws.warehouse_id = w.id
            ),
            '[]'::jsonb
          ),
          'city',
          (
            select jsonb_build_object('name', c.name)
            from public.cities c
            where c.id = w.city_id
          )
        )
      )
      order by w.created_at
    ),
    '[]'::jsonb
  )
  from public.warehouses w
  where w.player_id = auth.uid()
    and w.is_active = true;
$function$;

-- Function: get_player_active_warehouses_with_slots
CREATE OR REPLACE FUNCTION public.get_player_active_warehouses_with_slots(p_city_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      (
        to_jsonb(w) ||
        jsonb_build_object(
          'city',
          (
            select jsonb_build_object('name', c.name)
            from public.cities c
            where c.id = w.city_id
          ),
          'warehouse_slots',
          coalesce(
            (
              select jsonb_agg(
                to_jsonb(ws) ||
                jsonb_build_object('product', to_jsonb(p))
                order by ws.id
              )
              from public.warehouse_slots ws
              left join public.products p on p.id = ws.product_id
              where ws.warehouse_id = w.id
            ),
            '[]'::jsonb
          )
        )
      )
      order by w.created_at
    ),
    '[]'::jsonb
  )
  from public.warehouses w
  where w.player_id = auth.uid()
    and w.is_active = true
    and (p_city_id is null or w.city_id = p_city_id);
$function$;

-- Function: get_player_any_active_building_upgrade
CREATE OR REPLACE FUNCTION public.get_player_any_active_building_upgrade()
 RETURNS building_upgrades
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select bu.*
  from public.building_upgrades bu
  where bu.player_id = auth.uid()
    and bu.status = 'in_progress'
    and coalesce(bu.finish_at, timezone('utc', now())) > timezone('utc', now())
  order by bu.started_at desc
  limit 1;
$function$;

-- Function: get_player_arge_center
CREATE OR REPLACE FUNCTION public.get_player_arge_center()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
