-- Function: get_player_brand_company
CREATE OR REPLACE FUNCTION public.get_player_brand_company()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select to_jsonb(bc)
  from public.brand_companies bc
  where bc.player_id = auth.uid()
  limit 1;
$function$;

-- Function: get_player_brand_company_products
CREATE OR REPLACE FUNCTION public.get_player_brand_company_products()
 RETURNS TABLE(product_id text, product_name text, product_icon text, max_quality_level integer, is_branded boolean, branded_at timestamp with time zone, watermark_asset_id text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with company as (
    select bc.id
    from public.brand_companies bc
    where bc.player_id = auth.uid()
    limit 1
  ),
  eligible as (
    select ppql.product_id, max(ppql.max_quality_level)::integer as max_quality_level
    from public.player_product_quality_levels ppql
    where ppql.player_id = auth.uid()
    group by ppql.product_id
  ),
  branded as (
    select bcp.product_id, bcp.created_at, bcp.watermark_asset_id
    from public.brand_company_products bcp
    join company c on c.id = bcp.brand_company_id
    where bcp.player_id = auth.uid()
      and bcp.is_active = true
  )
  select
    p.id as product_id,
    p.urun_adi as product_name,
    p.urun_iconu as product_icon,
    coalesce(e.max_quality_level, 1) as max_quality_level,
    (b.product_id is not null) as is_branded,
    b.created_at as branded_at,
    b.watermark_asset_id
  from public.products p
  left join eligible e on e.product_id = p.id
  left join branded b on b.product_id = p.id
  where coalesce(e.max_quality_level, 0) >= 2
     or b.product_id is not null
  order by case when b.product_id is not null then 0 else 1 end, p.urun_adi asc;
$function$;

-- Function: get_player_building_constructions
CREATE OR REPLACE FUNCTION public.get_player_building_constructions(p_building_kind text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(bc) order by bc.started_at),
    '[]'::jsonb
  )
  from public.building_constructions bc
  where bc.player_id = auth.uid()
    and bc.building_kind = p_building_kind
    and (p_status is null or bc.status = p_status);
$function$;

-- Function: get_player_cash_ledger
CREATE OR REPLACE FUNCTION public.get_player_cash_ledger(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_rows      jsonb;
  v_total     integer;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  SELECT count(*)
  INTO v_total
  FROM public.player_cash_ledger
  WHERE player_id = v_player_id;

  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',             l.id,
        'created_at',     l.created_at,
        'amount',         l.amount,
        'balance_before', l.balance_before,
        'balance_after',  l.balance_after,
        'category',       l.category,
        'note',           l.note,
        'ref_id',         l.ref_id,
        'ref_kind',       l.ref_kind
      )
      ORDER BY l.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT *
    FROM public.player_cash_ledger
    WHERE player_id = v_player_id
    ORDER BY created_at DESC
    LIMIT p_limit OFFSET p_offset
  ) l;

  RETURN jsonb_build_object(
    'success', true,
    'total',   v_total,
    'limit',   p_limit,
    'offset',  p_offset,
    'items',   v_rows
  );
end;
$function$;

-- Function: get_player_daily_production_stats
CREATE OR REPLACE FUNCTION public.get_player_daily_production_stats(p_owner_kind text DEFAULT NULL::text, p_owner_id uuid DEFAULT NULL::uuid, p_date_from date DEFAULT ((timezone('utc'::text, now()))::date - 6), p_date_to date DEFAULT (timezone('utc'::text, now()))::date)
 RETURNS TABLE(production_date date, owner_kind text, owner_id uuid, product_id text, product_name text, product_icon text, base_sale_price numeric, produced_quantity bigint, total_cost numeric, estimated_revenue numeric, estimated_profit numeric)
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select
    s.production_date,
    s.owner_kind,
    s.owner_id,
    s.product_id,
    coalesce(p.urun_adi, 'Urun') as product_name,
    coalesce(p.urun_iconu, '') as product_icon,
    coalesce(p.baz_satis_fiyati, 0) as base_sale_price,
    s.produced_quantity,
    coalesce(s.total_cost, 0) as total_cost,
    (coalesce(p.baz_satis_fiyati, 0) * s.produced_quantity) as estimated_revenue,
    ((coalesce(p.baz_satis_fiyati, 0) * s.produced_quantity) - coalesce(s.total_cost, 0)) as estimated_profit
  from public.player_daily_production_stats s
  left join public.products p on p.id = s.product_id
  where s.player_id = auth.uid()
    and (p_owner_kind is null or s.owner_kind = p_owner_kind)
    and (p_owner_id is null or s.owner_id = p_owner_id)
    and s.production_date between coalesce(p_date_from, s.production_date)
      and coalesce(p_date_to, s.production_date)
  order by s.production_date desc, s.owner_kind, product_name;
$function$;

-- Function: get_player_facility_cities_summary
CREATE OR REPLACE FUNCTION public.get_player_facility_cities_summary(p_player_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid;
  v_result jsonb;
BEGIN
  v_player_id := coalesce(p_player_id, auth.uid());
  IF v_player_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz erişim.');
  END IF;

  WITH player_facs AS (
    -- Depolar
    SELECT 'warehouse' as kind, 'Depo' as kind_display, w.id, w.name, w.city_id, c.name as city_name,
           w.capacity as total_capacity,
           coalesce((SELECT sum(ws.quantity) FROM public.warehouse_slots ws WHERE ws.warehouse_id = w.id), 0)::integer as total_stock
    FROM public.warehouses w
    JOIN public.cities c ON c.id = w.city_id
    WHERE w.player_id = v_player_id AND w.is_active = true

    UNION ALL

    -- Fabrikalar
    SELECT 'factory' as kind, 'Fabrika' as kind_display, f.id, coalesce(f.name, p.urun_adi, 'Fabrika') as name, f.city_id, c.name as city_name,
           f.output_capacity as total_capacity,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'factory' AND pi.owner_id = f.id AND pi.inventory_type = 'output'), 0)::integer as total_stock
    FROM public.factories f
    JOIN public.cities c ON c.id = f.city_id
    LEFT JOIN public.products p ON p.id = f.product_id
    WHERE f.player_id = v_player_id AND f.is_active = true

    UNION ALL

    -- Tarlalar
    SELECT 'farm' as kind, 'Tarla' as kind_display, fa.id, fa.name, fa.city_id, c.name as city_name,
           fa.output_capacity as total_capacity,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'farm' AND pi.owner_id = fa.id AND pi.inventory_type = 'output'), 0)::integer as total_stock
    FROM public.farms fa
    JOIN public.cities c ON c.id = fa.city_id
    WHERE fa.player_id = v_player_id AND fa.is_active = true

    UNION ALL

    -- Çiftlikler
    SELECT 'field' as kind, 'Çiftlik' as kind_display, fi.id, fi.name, fi.city_id, c.name as city_name,
           fi.output_capacity as total_capacity,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'field' AND pi.owner_id = fi.id AND pi.inventory_type = 'output'), 0)::integer as total_stock
    FROM public.fields fi
    JOIN public.cities c ON c.id = fi.city_id
    WHERE fi.player_id = v_player_id AND fi.is_active = true

    UNION ALL

    -- Madenler
    SELECT 'mine' as kind, 'Maden' as kind_display, m.id, coalesce(m.name, p.urun_adi, 'Maden') as name, m.city_id, c.name as city_name,
           m.output_capacity as total_capacity,
           coalesce((SELECT sum(pi.quantity) FROM public.production_inventory pi WHERE pi.owner_kind = 'mine' AND pi.owner_id = m.id AND pi.inventory_type = 'output'), 0)::integer as total_stock
    FROM public.mines m
    JOIN public.cities c ON c.id = m.city_id
    LEFT JOIN public.products p ON p.id = m.product_id
    WHERE m.player_id = v_player_id AND m.is_active = true

    UNION ALL

    -- Mağazalar
    SELECT 'store' as kind, 'Mağaza' as kind_display, s.id, s.name, s.city_id, c.name as city_name,
           (s.slot_capacity * coalesce(s.current_slot_count, 1)) as total_capacity,
           coalesce((SELECT sum(ss.quantity) FROM public.store_slots ss WHERE ss.store_id = s.id AND ss.is_active = true), 0)::integer as total_stock
    FROM public.stores s
    JOIN public.cities c ON c.id = s.city_id
    WHERE s.player_id = v_player_id AND s.is_active = true
  ),
  city_grouped AS (
    SELECT
      city_id,
      city_name,
      count(*)::integer as facility_count,
      sum(total_stock)::integer as total_city_stock,
      jsonb_agg(
        jsonb_build_object(
          'id', id,
          'name', name,
          'kind', kind,
          'kind_display', kind_display,
          'total_capacity', total_capacity,
          'total_stock', total_stock
        ) ORDER BY total_stock DESC, kind, name
      ) as facilities
    FROM player_facs
    GROUP BY city_id, city_name
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'city_id', city_id,
      'city_name', city_name,
      'facility_count', facility_count,
      'total_city_stock', total_city_stock,
      'facilities', facilities
    ) ORDER BY total_city_stock DESC, facility_count DESC
  ) INTO v_result
  FROM city_grouped;

  RETURN jsonb_build_object(
    'success', true,
    'cities', coalesce(v_result, '[]'::jsonb)
  );
END;
$function$;

-- Function: get_player_hourly_income_estimate
CREATE OR REPLACE FUNCTION public.get_player_hourly_income_estimate(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH inventory_totals AS (
    SELECT
      owner_kind,
      owner_id,
      coalesce(sum(quantity) FILTER (WHERE inventory_type = 'input'), 0)::numeric
        AS input_quantity,
      coalesce(sum(quantity) FILTER (WHERE inventory_type = 'output'), 0)::numeric
        AS output_quantity
    FROM public.production_inventory
    GROUP BY owner_kind, owner_id
  ),
  active_boosts AS (
    SELECT DISTINCT ON (building_kind, entity_id)
      building_kind,
      entity_id,
      multiplier
    FROM public.building_boosts
    WHERE player_id = p_player_id
      AND status = 'in_progress'
      AND coalesce(finish_at, timezone('utc'::text, now()))
        > timezone('utc'::text, now())
    ORDER BY building_kind, entity_id, started_at DESC, id DESC
  ),
  store_rows AS (
    SELECT
      ss.quantity::numeric AS available_quantity,
      ss.price,
      greatest(coalesce(p.satis_adedi, 0), 0)::numeric
        * (1 + ((greatest(least(ss.quality_level, 5), 1) - 1) * 0.10))
        * CASE
            WHEN ss.brand_id IS NULL
              OR ss.brand_id = '00000000-0000-0000-0000-000000000000'::uuid
              THEN 1.0
            ELSE 1.10
          END
        * CASE
            WHEN coalesce(p.baz_satis_fiyati, 0) <= 0 THEN 1.0
            WHEN ss.price / (
              p.baz_satis_fiyati
              * CASE greatest(least(ss.quality_level, 5), 1)
                  WHEN 2 THEN 1.10
                  WHEN 3 THEN 1.22
                  WHEN 4 THEN 1.35
                  WHEN 5 THEN 1.50
                  ELSE 1.00
                END
              * CASE
                  WHEN ss.brand_id IS NULL OR ss.brand_id = '00000000-0000-0000-0000-000000000000'::uuid THEN 1.0
                  ELSE 1.25
                END
            ) <= 1 THEN greatest(
              least(
                1 + (
                  1 - ss.price / (
                    p.baz_satis_fiyati
                    * CASE greatest(least(ss.quality_level, 5), 1)
                        WHEN 2 THEN 1.10
                        WHEN 3 THEN 1.22
                        WHEN 4 THEN 1.35
                        WHEN 5 THEN 1.50
                        ELSE 1.00
                      END
                    * CASE
                        WHEN ss.brand_id IS NULL OR ss.brand_id = '00000000-0000-0000-0000-000000000000'::uuid THEN 1.0
                        ELSE 1.25
                      END
                  )
                ) * 0.75,
                1.75
              ),
              0.05
            )
            ELSE greatest(
              least(
                1 - (
                  ss.price / (
                    p.baz_satis_fiyati
                    * CASE greatest(least(ss.quality_level, 5), 1)
                        WHEN 2 THEN 1.10
                        WHEN 3 THEN 1.22
                        WHEN 4 THEN 1.35
                        WHEN 5 THEN 1.50
                        ELSE 1.00
                      END
                    * CASE
                        WHEN ss.brand_id IS NULL OR ss.brand_id = '00000000-0000-0000-0000-000000000000'::uuid THEN 1.0
                        ELSE 1.25
                      END
                  ) - 1
                ) * 0.95,
                1.75
              ),
              0.05
            )
          END
        * CASE
            WHEN coalesce(ab.multiplier, ss.boost_multiplier, 1) <= 0 THEN 1.0
            ELSE coalesce(ab.multiplier, ss.boost_multiplier, 1)
          END AS estimated_units
    FROM public.stores s
    JOIN public.store_slots ss ON ss.store_id = s.id
    JOIN public.products p ON p.id = ss.product_id
    LEFT JOIN active_boosts ab
      ON ab.building_kind = 'store' AND ab.entity_id = s.id
    WHERE s.player_id = p_player_id
      AND s.is_active = true
      AND ss.is_active = true
      AND ss.product_id IS NOT NULL
      AND ss.quantity > 0
      AND coalesce(ss.price, 0) > 0
      AND coalesce(p.satis_adedi, 0) > 0
  ),
  store_value AS (
    SELECT coalesce(
      sum(least(greatest(estimated_units, 0), available_quantity) * price),
      0
    ) AS value
    FROM store_rows
  ),
  production_rows AS (
    SELECT
      greatest(coalesce(p.uretim_adedi, 0), 0)::numeric AS hourly_units,
      CASE
        WHEN coalesce(p.ortalama_fiyat, 0) > 0 THEN p.ortalama_fiyat
        WHEN coalesce(p.baz_satis_fiyati, 0) > 0 THEN p.baz_satis_fiyati
        ELSE 0
      END AS unit_value,
      CASE
        WHEN coalesce(ab.multiplier, f.boost_multiplier, 1) <= 0 THEN 1.0
        ELSE coalesce(ab.multiplier, f.boost_multiplier, 1)
      END AS multiplier,
      CASE
        WHEN coalesce(f.output_capacity, 0) <= 0 THEN 0
        ELSE least(
          greatest(coalesce(inv.output_quantity, 0) / f.output_capacity, 0),
          1
        )
      END AS output_ratio,
      coalesce(inv.input_quantity, 0) AS input_quantity,
      (
        nullif(p.hammadde_1_id, '') IS NOT NULL
        OR nullif(p.hammadde_2_id, '') IS NOT NULL
        OR nullif(p.hammadde_3_id, '') IS NOT NULL
      ) AS requires_input
    FROM public.factories f
    JOIN public.products p ON p.id = f.product_id
    LEFT JOIN inventory_totals inv
      ON inv.owner_kind = 'factory' AND inv.owner_id = f.id
    LEFT JOIN active_boosts ab
      ON ab.building_kind = 'factory' AND ab.entity_id = f.id
    WHERE f.player_id = p_player_id
      AND f.is_active = true
      AND f.product_id IS NOT NULL

    UNION ALL

    SELECT
      greatest(coalesce(p.uretim_adedi, 0), 0)::numeric,
      CASE
        WHEN coalesce(p.ortalama_fiyat, 0) > 0 THEN p.ortalama_fiyat
        WHEN coalesce(p.baz_satis_fiyati, 0) > 0 THEN p.baz_satis_fiyati
        ELSE 0
      END,
      CASE
        WHEN coalesce(ab.multiplier, m.boost_multiplier, 1) <= 0 THEN 1.0
        ELSE coalesce(ab.multiplier, m.boost_multiplier, 1)
      END,
      CASE
        WHEN coalesce(m.output_capacity, 0) <= 0 THEN 0
        ELSE least(
          greatest(coalesce(inv.output_quantity, 0) / m.output_capacity, 0),
          1
        )
      END,
      0::numeric,
      false
    FROM public.mines m
    JOIN public.products p ON p.id = m.product_id
    LEFT JOIN inventory_totals inv
      ON inv.owner_kind = 'mine' AND inv.owner_id = m.id
    LEFT JOIN active_boosts ab
      ON ab.building_kind = 'mine' AND ab.entity_id = m.id
    WHERE m.player_id = p_player_id
      AND m.is_active = true
      AND m.product_id IS NOT NULL

    UNION ALL

    SELECT
      greatest(coalesce(p.uretim_adedi, 0), 0)::numeric,
      CASE
        WHEN coalesce(p.ortalama_fiyat, 0) > 0 THEN p.ortalama_fiyat
        WHEN coalesce(p.baz_satis_fiyati, 0) > 0 THEN p.baz_satis_fiyati
        ELSE 0
      END,
      1.0::numeric,
      CASE
        WHEN coalesce(f.output_capacity, 0) <= 0 THEN 0
        ELSE least(
          greatest(coalesce(inv.output_quantity, 0) / f.output_capacity, 0),
          1
        )
      END,
      coalesce(inv.input_quantity, 0),
      (
        nullif(p.hammadde_1_id, '') IS NOT NULL
        OR nullif(p.hammadde_2_id, '') IS NOT NULL
        OR nullif(p.hammadde_3_id, '') IS NOT NULL
      )
    FROM public.fields f
    JOIN public.production_slots ps
      ON ps.owner_kind = 'field' AND ps.owner_id = f.id
    JOIN public.products p ON p.id = ps.product_id
    LEFT JOIN inventory_totals inv
      ON inv.owner_kind = 'field' AND inv.owner_id = f.id
    WHERE f.player_id = p_player_id
      AND f.is_active = true
      AND ps.is_active = true
      AND ps.product_id IS NOT NULL

    UNION ALL

    SELECT
      greatest(coalesce(p.uretim_adedi, 0), 0)::numeric,
      CASE
        WHEN coalesce(p.ortalama_fiyat, 0) > 0 THEN p.ortalama_fiyat
        WHEN coalesce(p.baz_satis_fiyati, 0) > 0 THEN p.baz_satis_fiyati
        ELSE 0
      END,
      1.0::numeric,
      CASE
        WHEN coalesce(f.output_capacity, 0) <= 0 THEN 0
        ELSE least(
          greatest(coalesce(inv.output_quantity, 0) / f.output_capacity, 0),
          1
        )
      END,
      coalesce(inv.input_quantity, 0),
      (
        nullif(p.hammadde_1_id, '') IS NOT NULL
        OR nullif(p.hammadde_2_id, '') IS NOT NULL
        OR nullif(p.hammadde_3_id, '') IS NOT NULL
      )
    FROM public.farms f
    JOIN public.production_slots ps
      ON ps.owner_kind = 'farm' AND ps.owner_id = f.id
    JOIN public.products p ON p.id = ps.product_id
    LEFT JOIN inventory_totals inv
      ON inv.owner_kind = 'farm' AND inv.owner_id = f.id
    WHERE f.player_id = p_player_id
      AND f.is_active = true
      AND ps.is_active = true
      AND ps.product_id IS NOT NULL
  ),
  production_value AS (
    SELECT coalesce(sum(
      hourly_units * unit_value * multiplier * (1 - output_ratio)
    ), 0) AS value
    FROM production_rows
    WHERE output_ratio < 0.98
      AND (requires_input = false OR input_quantity > 0)
  )
  SELECT jsonb_build_object(
    'total', store_value.value + production_value.value,
    'store_revenue', store_value.value,
    'production_value', production_value.value
  )
  FROM store_value
  CROSS JOIN production_value;
$function$;

-- Function: get_player_leaderboard_rank_info
CREATE OR REPLACE FUNCTION public.get_player_leaderboard_rank_info(p_player_id uuid, p_sort_by_field text DEFAULT 'company_value'::text, p_city_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sort_col text;
  v_where_clause text := '';
  v_sql text;
  v_rank bigint;
  v_entry jsonb;
BEGIN
  -- Önce oyuncunun güncel istatistiğini yenile
  PERFORM public.refresh_player_leaderboard_stats(p_player_id);

  v_sort_col := CASE lower(trim(coalesce(p_sort_by_field, 'company_value')))
    WHEN 'company_value' THEN 'company_value'
    WHEN 'level' THEN 'level'
    WHEN 'achievement_unlocked_count' THEN 'achievement_unlocked_count'
    WHEN 'cash' THEN 'cash'
    WHEN 'gold' THEN 'gold'
    WHEN 'experience' THEN 'experience'
    WHEN 'business_value' THEN 'business_value'
    WHEN 'inventory_value' THEN 'inventory_value'
    WHEN 'vehicle_value' THEN 'vehicle_value'
    ELSE 'company_value'
  END;

  IF p_city_id IS NOT NULL THEN
    v_where_clause := format('WHERE headquarters_city_id = %L', p_city_id);
  END IF;

  v_sql := format(
    'WITH ranked AS (
       SELECT 
         player_id,
         row_number() OVER (ORDER BY %I DESC NULLS LAST, level DESC, player_name ASC) as rank_pos,
         to_jsonb(pls) as entry_data
       FROM public.player_leaderboard_stats pls
       %s
     )
     SELECT rank_pos, entry_data
     FROM ranked
     WHERE player_id = %L',
    v_sort_col,
    v_where_clause,
    p_player_id
  );

  EXECUTE v_sql INTO v_rank, v_entry;

  IF v_rank IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'rank', v_rank,
    'entry', v_entry
  );
END;
$function$;

-- Function: get_player_loan_limit
CREATE OR REPLACE FUNCTION public.get_player_loan_limit(p_player_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_level integer;
  v_company_val jsonb;
  v_business_val numeric := 0;
  v_base_limit numeric;
  v_asset_limit numeric;
begin
  select coalesce(level, 1) into v_level from public.players where id = p_player_id;
  v_base_limit := v_level * 50000.0;

  -- Sirket varliklarina dayali kredi limiti (%25 teminat orani)
  v_company_val := public.calculate_player_company_value(p_player_id);
  v_business_val := coalesce((v_company_val ->> 'business_value')::numeric, 0) + coalesce((v_company_val ->> 'inventory_value')::numeric, 0);
  v_asset_limit := round(v_business_val * 0.25, 0);

  return greatest(v_base_limit, v_asset_limit);
end;
$function$;

-- Function: get_player_logistics_company
CREATE OR REPLACE FUNCTION public.get_player_logistics_company()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select to_jsonb(lc)
  from public.logistics_companies lc
  where lc.player_id = auth.uid()
  order by lc.created_at
  limit 1;
$function$;

-- Function: get_player_logistics_finance_entries
CREATE OR REPLACE FUNCTION public.get_player_logistics_finance_entries(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(entries) order by entries.created_at desc),
    '[]'::jsonb
  )
  from (
    select
      lfe.id,
      lfe.player_id,
      lfe.logistics_company_id,
      lfe.vehicle_id,
      lfe.entry_type,
      lfe.category,
      lfe.amount,
      lfe.quantity,
      lfe.unit_cost,
      lfe.related_transfer_id,
      lfe.related_warehouse_slot_id,
      lfe.related_market_listing_id,
      lfe.description,
      lfe.metadata,
      lfe.created_at
    from public.logistics_finance_entries lfe
    where lfe.player_id = auth.uid()
    order by lfe.created_at desc
    limit greatest(coalesce(p_limit, 100), 1)
  ) entries;
$function$;

-- Function: get_player_logistics_finance_summary
CREATE OR REPLACE FUNCTION public.get_player_logistics_finance_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_result jsonb;
  v_total_distance numeric := 0;
  v_total_trips integer := 0;
  v_total_cargo integer := 0;
  v_total_fuel numeric := 0;
begin
  select
    coalesce(sum(distance_km), 0),
    count(*)::int,
    coalesce(sum(total_quantity), 0)::int,
    coalesce(sum(fuel_used), 0)
  into
    v_total_distance,
    v_total_trips,
    v_total_cargo,
    v_total_fuel
  from public.logistics_transfers
  where vehicle_owner_player_id = v_player_id
    and logistics_vehicle_id is not null;

  select jsonb_build_object(
    'total_income', coalesce(sum(amount) filter (where entry_type = 'income'), 0),
    'total_expense', coalesce(sum(amount) filter (where entry_type = 'expense'), 0),
    'net_profit', coalesce(sum(case when entry_type = 'income' then amount else -amount end), 0),
    'vehicle_purchase_expense', coalesce(sum(amount) filter (where category = 'vehicle_purchase'), 0),
    'fuel_purchase_expense', coalesce(sum(amount) filter (where category = 'fuel_purchase'), 0),
    'maintenance_expense', coalesce(sum(amount) filter (where category = 'maintenance'), 0),
    'rental_income', coalesce(sum(amount) filter (where category = 'rental_income'), 0),
    'total_distance_km', v_total_distance::double precision,
    'total_trips', v_total_trips,
    'total_cargo_delivered', v_total_cargo,
    'total_fuel_used', v_total_fuel::double precision
  )
  into v_result
  from public.logistics_finance_entries
  where player_id = v_player_id;

  return v_result;
end;
$function$;

-- Function: get_player_logistics_vehicle_performance
CREATE OR REPLACE FUNCTION public.get_player_logistics_vehicle_performance()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(stats) order by stats.last_activity_at desc nulls last),
    '[]'::jsonb
  )
  from (
    select
      lt.logistics_vehicle_id as vehicle_id,
      count(*)::int as total_trips,
      count(*) filter (where lt.status = 'completed')::int as completed_trips,
      count(*) filter (where lt.status = 'in_transit')::int as active_trips,
      count(*) filter (where lt.is_rental = true)::int as rental_trips,
      coalesce(sum(case when lt.is_rental then lt.rental_cost else 0 end), 0)::double precision as rental_revenue,
      coalesce(sum(lt.distance_km), 0)::double precision as total_distance_km,
      coalesce(sum(lt.fuel_used), 0)::double precision as total_fuel_used,
      coalesce(sum(lt.total_quantity), 0)::int as total_cargo_quantity,
      coalesce(sum(lt.transport_cost), 0)::double precision as total_transport_cost,
      max(coalesce(lt.completed_at, lt.finish_at, lt.started_at)) as last_activity_at
    from public.logistics_transfers lt
    where lt.vehicle_owner_player_id = auth.uid()
      and lt.logistics_vehicle_id is not null
    group by lt.logistics_vehicle_id
  ) stats;
$function$;

-- Function: get_player_logistics_vehicles
CREATE OR REPLACE FUNCTION public.get_player_logistics_vehicles(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'player_id', player_id,
    'logistics_company_id', logistics_company_id,
    'logistics_vehicle_type_id', logistics_vehicle_type_id,
    'capacity', capacity,
    'speed_kmh', speed_kmh,
    'fuel_capacity', fuel_capacity,
    'current_fuel', current_fuel,
    'fuel_cost', fuel_cost,
    'fuel_rate', fuel_rate,
    'condition', condition,
    'status', status,
    'is_available_for_rent', is_available_for_rent,
    'rental_price', rental_price,
    'created_at', created_at,
    'updated_at', updated_at,
    'route_city_a_id', route_city_a_id,
    'route_city_b_id', route_city_b_id
  ) order by created_at asc), '[]'::jsonb)
  into v_result
  from public.logistics_vehicles
  where player_id = p_player_id;
  return v_result;
end;
$function$;

-- Function: get_player_max_deposit_limit
CREATE OR REPLACE FUNCTION public.get_player_max_deposit_limit(p_player_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_level integer;
  v_company_val jsonb;
  v_total_val numeric := 0;
  v_base_limit numeric;
  v_asset_limit numeric;
begin
  select coalesce(level, 1) into v_level from public.players where id = p_player_id;
  v_base_limit := v_level * 250000.0;

  v_company_val := public.calculate_player_company_value(p_player_id);
  v_total_val := coalesce((v_company_val ->> 'total_company_value')::numeric, 0);
  v_asset_limit := round(v_total_val * 0.50, 0);

  return greatest(v_base_limit, v_asset_limit);
end;
$function$;

-- Function: get_player_mission_dashboard
CREATE OR REPLACE FUNCTION public.get_player_mission_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_main_mission jsonb;
  v_main_missions jsonb := '[]'::jsonb;
  v_daily_missions jsonb := '[]'::jsonb;
  v_achievements jsonb := '[]'::jsonb;
  v_claimable_count integer := 0;
  v_daily_claimable_count integer := 0;
  v_achievement_claimable_count integer := 0;
  v_main_claimable_count integer := 0;
  v_completed_count integer := 0;
  v_total_count integer := 0;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  perform public.ensure_player_mission_rows(v_player_id);
  perform public.reset_player_daily_missions(v_player_id);
  perform public.sync_player_mission_snapshot(v_player_id);

  -- 1. Active Main Mission (First uncompleted or unclaimed main quest in the sequence)
  select public.build_player_mission_payload(v_player_id, mission_id)
  into v_main_mission
  from (
    select pm.mission_id, md.display_order
    from public.player_missions pm
    join public.mission_definitions md on md.id = pm.mission_id
    where pm.player_id = v_player_id
      and md.is_active = true
      and md.mission_type = 'main'
      and pm.is_claimed = false
      and (
        md.required_mission_id is null
        or exists (
          select 1
          from public.player_missions req
          where req.player_id = v_player_id
            and req.mission_id = md.required_mission_id
            and req.is_claimed = true
        )
      )
    order by pm.is_completed desc, md.display_order asc
    limit 1
  ) main_pick;

  -- 2. All Main Missions (Roadmap)
  select coalesce(jsonb_agg(public.build_player_mission_payload(v_player_id, md.id) order by md.display_order asc), '[]'::jsonb)
  into v_main_missions
  from public.mission_definitions md
  where md.is_active = true
    and md.mission_type = 'main';

  -- 3. Daily Missions (Exact 3 items)
  select coalesce(jsonb_agg(public.build_player_mission_payload(v_player_id, md.id) order by md.display_order asc), '[]'::jsonb)
  into v_daily_missions
  from public.mission_definitions md
  where md.is_active = true
    and md.mission_type = 'daily';

  -- 4. Achievements
  select coalesce(jsonb_agg(public.build_player_mission_payload(v_player_id, md.id) order by (case when coalesce(pm.is_completed, false) and not coalesce(pm.is_claimed, false) then 0 when coalesce(pm.is_claimed, false) then 2 else 1 end), md.display_order asc), '[]'::jsonb)
  into v_achievements
  from public.mission_definitions md
  left join public.player_missions pm
    on pm.mission_id = md.id
   and pm.player_id = v_player_id
  where md.is_active = true
    and md.mission_type = 'achievement';

  -- 5. Claimable counts
  select
    count(*) filter (where pm.is_completed = true and pm.is_claimed = false),
    count(*) filter (where md.mission_type = 'daily' and pm.is_completed = true and pm.is_claimed = false),
    count(*) filter (where md.mission_type = 'achievement' and pm.is_completed = true and pm.is_claimed = false),
    count(*) filter (where md.mission_type = 'main' and pm.is_completed = true and pm.is_claimed = false),
    count(*) filter (where pm.is_completed = true),
    count(*)
  into v_claimable_count, v_daily_claimable_count, v_achievement_claimable_count, v_main_claimable_count, v_completed_count, v_total_count
  from public.player_missions pm
  join public.mission_definitions md on md.id = pm.mission_id
  where pm.player_id = v_player_id
    and md.is_active = true;

  return jsonb_build_object(
    'success', true,
    'main_mission', v_main_mission,
    'main_missions', v_main_missions,
    'daily_missions', v_daily_missions,
    'achievements', v_achievements,
    'side_missions', v_achievements, -- backward compat
    'weekly_missions', '[]'::jsonb, -- backward compat
    'claimable_count', coalesce(v_claimable_count, 0),
    'daily_claimable_count', coalesce(v_daily_claimable_count, 0),
    'achievement_claimable_count', coalesce(v_achievement_claimable_count, 0),
    'main_claimable_count', coalesce(v_main_claimable_count, 0),
    'summary', jsonb_build_object(
      'completed_count', coalesce(v_completed_count, 0),
      'daily_completed_count', coalesce(v_daily_claimable_count, 0),
      'total_count', coalesce(v_total_count, 0)
    )
  );
end;
$function$;

-- Function: get_player_notifications
CREATE OR REPLACE FUNCTION public.get_player_notifications(p_limit integer DEFAULT 30, p_offset integer DEFAULT 0, p_category text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, player_id uuid, title text, message text, category text, entity_type text, entity_id uuid, is_read boolean, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    pn.id,
    pn.player_id,
    pn.title,
    pn.message,
    pn.category,
    pn.entity_type,
    pn.entity_id,
    pn.is_read,
    pn.created_at
  FROM public.player_notifications pn
  WHERE pn.player_id = auth.uid()
    AND (p_category IS NULL OR p_category = 'all' OR pn.category = p_category)
  ORDER BY pn.created_at DESC
  LIMIT greatest(1, least(p_limit, 100))
  OFFSET greatest(0, p_offset);
$function$;

-- Function: get_player_operational_alerts
CREATE OR REPLACE FUNCTION public.get_player_operational_alerts(p_player_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid;
  v_alerts jsonb := '[]'::jsonb;
  v_count integer;
  v_debt numeric;
  v_limit numeric;
BEGIN
  v_player_id := coalesce(p_player_id, auth.uid());
  IF v_player_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz erişim.');
  END IF;

  -- 1. VERGİ BLOKE VE LİMİT KONTROLÜ
  SELECT coalesce(pt.tax_debt, 0), public.get_player_tax_limit(coalesce(p.level, 1))
  INTO v_debt, v_limit
  FROM public.players p
  LEFT JOIN public.player_taxes pt ON pt.player_id = p.id
  WHERE p.id = v_player_id;

  IF v_debt > v_limit THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'tax_blocked',
      'severity', 'critical',
      'category', 'tax',
      'title', 'Şirket İşlemleri Bloke!',
      'description', 'Vergi borcunuz yasal limiti aştığı için şirket faaliyetleriniz durduruldu.',
      'route', '/tax',
      'count', 1
    ));
  ELSIF v_debt > (v_limit * 0.75) THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'tax_near_limit',
      'severity', 'warning',
      'category', 'tax',
      'title', 'Vergi Borcu Kritik Seviyede',
      'description', 'Vergi borcunuz yasal limitin %75''ine ulaştı. Kilitlenme riski var.',
      'route', '/tax',
      'count', 1
    ));
  END IF;

  -- 2. BANKA KREDİ TEMERRÜT KONTROLÜ
  SELECT count(*) INTO v_count
  FROM public.player_loans
  WHERE player_id = v_player_id
    AND status = 'active'
    AND next_installment_due_at < timezone('utc', now());

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'bank_loan_overdue',
      'severity', 'critical',
      'category', 'bank',
      'title', 'Kredi Taksiti Gecikti!',
      'description', v_count || ' adet gecikmiş kredi taksitiniz var. Temerrüt faizi işliyor.',
      'route', '/bank',
      'count', v_count
    ));
  END IF;

  -- 3. FABRİKA DURUMLARI
  -- 3a. Hammadde yok (Üretim Durdu)
  SELECT count(*) INTO v_count
  FROM public.factories f
  WHERE f.player_id = v_player_id
    AND f.is_active = true
    AND f.product_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.production_inventory pi
      WHERE pi.owner_kind = 'factory'
        AND pi.owner_id = f.id
        AND pi.inventory_type = 'input'
        AND (pi.quantity + coalesce(pi.pending_quantity, 0)) > 0
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'factory_no_input',
      'severity', 'critical',
      'category', 'factory',
      'title', v_count || ' Fabrikada Hammadde Bitti!',
      'description', 'Girdi stoğu tükendiği için üretim bantları tamamen durdu.',
      'route', '/factories',
      'count', v_count
    ));
  END IF;

  -- 3b. Çıkış deposu dolu (Üretim Kilitlendi)
  SELECT count(*) INTO v_count
  FROM public.factories f
  WHERE f.player_id = v_player_id
    AND f.is_active = true
    AND f.output_capacity > 0
    AND (
      SELECT coalesce(sum(pi.quantity), 0)
      FROM public.production_inventory pi
      WHERE pi.owner_kind = 'factory'
        AND pi.owner_id = f.id
        AND pi.inventory_type = 'output'
    ) >= f.output_capacity;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'factory_output_full',
      'severity', 'critical',
      'category', 'factory',
      'title', v_count || ' Fabrikada Depo Doldu!',
      'description', 'Çıkış ambarı %100 kapasiteye ulaştı, üretim yapılamıyor.',
      'route', '/factories',
      'count', v_count
    ));
  END IF;

  -- 3c. Ürün seçilmemiş (Atıl Tesis)
  SELECT count(*) INTO v_count
  FROM public.factories f
  WHERE f.player_id = v_player_id
    AND f.is_active = true
    AND f.product_id IS NULL;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'factory_idle',
      'severity', 'warning',
      'category', 'factory',
      'title', v_count || ' Fabrikada Ürün Seçilmedi',
      'description', 'Tesis aktif ancak üretim reçetesi atanmamış, boşta bekliyor.',
      'route', '/factories',
      'count', v_count
    ));
  END IF;

  -- 4. TARLALAR (farms tablosu)
  -- 4a. Tohum / Gübre / Girdi Yok
  SELECT count(DISTINCT fa.id) INTO v_count
  FROM public.farms fa
  JOIN public.production_slots ps ON ps.owner_kind = 'farm' AND ps.owner_id = fa.id
  JOIN public.products pr ON pr.id = ps.product_id
  WHERE fa.player_id = v_player_id
    AND fa.is_active = true
    AND ps.is_active = true
    AND ps.product_id IS NOT NULL
    AND (pr.hammadde_1_id IS NOT NULL OR pr.hammadde_2_id IS NOT NULL OR pr.hammadde_3_id IS NOT NULL)
    AND NOT EXISTS (
      SELECT 1 FROM public.production_inventory pi
      WHERE pi.owner_kind = 'farm'
        AND pi.owner_id = fa.id
        AND pi.inventory_type = 'input'
        AND (pi.quantity + coalesce(pi.pending_quantity, 0)) > 0
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'field_no_input',
      'severity', 'critical',
      'category', 'field',
      'title', v_count || ' Tarlada Tohum/Gübre Tükendi!',
      'description', 'Ekim için girdi stoğu bittiği için tarla üretimi durdu.',
      'route', '/farms',
      'count', v_count
    ));
  END IF;

  -- 4b. Çıkış deposu dolu
  SELECT count(*) INTO v_count
  FROM public.farms fa
  WHERE fa.player_id = v_player_id
    AND fa.is_active = true
    AND fa.output_capacity > 0
    AND (
      SELECT coalesce(sum(pi.quantity), 0)
      FROM public.production_inventory pi
      WHERE pi.owner_kind = 'farm'
        AND pi.owner_id = fa.id
        AND pi.inventory_type = 'output'
    ) >= fa.output_capacity;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'field_output_full',
      'severity', 'critical',
      'category', 'field',
      'title', v_count || ' Tarlada Depo Doldu!',
      'description', 'Hasat ambarı %100 doldu, yeni hasat depolanamıyor.',
      'route', '/farms',
      'count', v_count
    ));
  END IF;

  -- 4c. Ekim yapılmamış
  SELECT count(*) INTO v_count
  FROM public.farms fa
  WHERE fa.player_id = v_player_id
    AND fa.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.production_slots ps
      WHERE ps.owner_kind = 'farm'
        AND ps.owner_id = fa.id
        AND ps.is_active = true
        AND ps.product_id IS NOT NULL
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'field_idle',
      'severity', 'warning',
      'category', 'field',
      'title', v_count || ' Tarlada Ekim Yapılmadı',
      'description', 'Tarla aktif ancak ekilecek mahsul seçilmemiş, boşta bekliyor.',
      'route', '/farms',
      'count', v_count
    ));
  END IF;

  -- 5. ÇİFTLİKLER (fields tablosu)
  -- 5a. Yem / Hammadde Yok
  SELECT count(DISTINCT fld.id) INTO v_count
  FROM public.fields fld
  JOIN public.production_slots ps ON ps.owner_kind = 'field' AND ps.owner_id = fld.id
  JOIN public.products pr ON pr.id = ps.product_id
  WHERE fld.player_id = v_player_id
    AND fld.is_active = true
    AND ps.is_active = true
    AND ps.product_id IS NOT NULL
    AND (pr.hammadde_1_id IS NOT NULL OR pr.hammadde_2_id IS NOT NULL OR pr.hammadde_3_id IS NOT NULL)
    AND NOT EXISTS (
      SELECT 1 FROM public.production_inventory pi
      WHERE pi.owner_kind = 'field'
        AND pi.owner_id = fld.id
        AND pi.inventory_type = 'input'
        AND (pi.quantity + coalesce(pi.pending_quantity, 0)) > 0
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'farm_no_input',
      'severity', 'critical',
      'category', 'farm',
      'title', v_count || ' Çiftlikte Yem Tükendi!',
      'description', 'Hayvan yemi veya girdi bittiği için çiftlik üretimi durdu.',
      'route', '/fields',
      'count', v_count
    ));
  END IF;

  -- 5b. Çıkış deposu dolu
  SELECT count(*) INTO v_count
  FROM public.fields fld
  WHERE fld.player_id = v_player_id
    AND fld.is_active = true
    AND fld.output_capacity > 0
    AND (
      SELECT coalesce(sum(pi.quantity), 0)
      FROM public.production_inventory pi
      WHERE pi.owner_kind = 'field'
        AND pi.owner_id = fld.id
        AND pi.inventory_type = 'output'
    ) >= fld.output_capacity;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'farm_output_full',
      'severity', 'critical',
      'category', 'farm',
      'title', v_count || ' Çiftlikte Depo Doldu!',
      'description', 'Çiftlik ambarı %100 doldu, yeni üretim durduruldu.',
      'route', '/fields',
      'count', v_count
    ));
  END IF;

  -- 5c. Üretim seçilmemiş
  SELECT count(*) INTO v_count
  FROM public.fields fld
  WHERE fld.player_id = v_player_id
    AND fld.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.production_slots ps
      WHERE ps.owner_kind = 'field'
        AND ps.owner_id = fld.id
        AND ps.is_active = true
        AND ps.product_id IS NOT NULL
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'farm_idle',
      'severity', 'warning',
      'category', 'farm',
      'title', v_count || ' Çiftlikte Üretim Yok',
      'description', 'Çiftlik aktif ancak yetiştirilecek ürün veya hayvan seçilmemiş.',
      'route', '/fields',
      'count', v_count
    ));
  END IF;

  -- 6. MADENLER (Depo Dolu)
  SELECT count(*) INTO v_count
  FROM public.mines m
  WHERE m.player_id = v_player_id
    AND m.is_active = true
    AND m.output_capacity > 0
    AND (
      SELECT coalesce(sum(pi.quantity), 0)
      FROM public.production_inventory pi
      WHERE pi.owner_kind = 'mine'
        AND pi.owner_id = m.id
        AND pi.inventory_type = 'output'
    ) >= m.output_capacity;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'mine_output_full',
      'severity', 'critical',
      'category', 'mine',
      'title', v_count || ' Madende Çıktı Deposu Doldu!',
      'description', 'Maden cevher deposu tam kapasiteye ulaştı, kazı durdu.',
      'route', '/mines',
      'count', v_count
    ));
  END IF;

  -- 7. MAĞAZALAR
  -- 7a. Tüm rafları boş mağazalar
  SELECT count(*) INTO v_count
  FROM public.stores s
  WHERE s.player_id = v_player_id
    AND s.is_active = true
    AND NOT EXISTS (
      SELECT 1 FROM public.store_slots ss
      WHERE ss.store_id = s.id
        AND ss.is_active = true
        AND (ss.quantity + coalesce(ss.pending_quantity, 0)) > 0
    );

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'store_out_of_stock',
      'severity', 'critical',
      'category', 'store',
      'title', v_count || ' Mağazada Raflar Tamamen Boş!',
      'description', 'Stok kalmadığı için satış yapılamıyor ve ciro kaybı yaşanıyor.',
      'route', '/store',
      'count', v_count
    ));
  END IF;

  -- 7b. Fiyatı belirlenmemiş aktif mağaza ürünleri
  SELECT count(*) INTO v_count
  FROM public.store_slots ss
  JOIN public.stores s ON s.id = ss.store_id
  WHERE s.player_id = v_player_id
    AND s.is_active = true
    AND ss.is_active = true
    AND ss.product_id IS NOT NULL
    AND (ss.price IS NULL OR ss.price <= 0);

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'store_unpriced_items',
      'severity', 'warning',
      'category', 'store',
      'title', v_count || ' Mağaza Slotunda Fiyat Belirlenmedi',
      'description', 'Raflara ürün yerleştirilmiş ancak satış fiyatı girilmemiş.',
      'route', '/store',
      'count', v_count
    ));
  END IF;

  -- 8. LOJİSTİK & FİLO
  -- 8a. Yakıtı biten araçlar
  SELECT count(*) INTO v_count
  FROM public.logistics_vehicles lv
  WHERE lv.player_id = v_player_id
    AND coalesce(lv.status, '') != 'scrapped'
    AND lv.current_fuel <= 0;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'vehicle_no_fuel',
      'severity', 'critical',
      'category', 'logistics',
      'title', v_count || ' Aracın Yakıtı Bitti!',
      'description', 'Sevkiyat yapamaz durumda. Yakıt ikmali yapılması gerekiyor.',
      'route', '/transfer-map',
      'count', v_count
    ));
  END IF;

  -- 8b. Kondisyonu kritik araçlar (< %20)
  SELECT count(*) INTO v_count
  FROM public.logistics_vehicles lv
  WHERE lv.player_id = v_player_id
    AND coalesce(lv.status, '') != 'scrapped'
    AND lv.condition < 20;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'vehicle_maintenance_urgent',
      'severity', 'warning',
      'category', 'logistics',
      'title', v_count || ' Araç Acil Bakım Bekliyor',
      'description', 'Kondisyon %20''nin altına indi. Arıza ve kaza riski yüksek.',
      'route', '/transfer-map',
      'count', v_count
    ));
  END IF;

  -- 9. İHALELER (Son 2 saat ve teslimat tamamlanmamış)
  SELECT count(*) INTO v_count
  FROM public.player_tenders pt
  WHERE pt.player_id = v_player_id
    AND pt.status = 'active'
    AND pt.deadline_at <= (timezone('utc', now()) + interval '2 hours')
    AND pt.delivered_quantity < pt.required_quantity;

  IF v_count > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'id', 'tender_deadline_urgent',
      'severity', 'critical',
      'category', 'tender',
      'title', v_count || ' İhale Teslimatına Son 2 Saat!',
      'description', 'Teslimat süresi dolmak üzere. Teminatın yanmaması için teslimatı tamamlayın.',
      'route', '/tenders',
      'count', v_count
    ));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'alerts', v_alerts,
    'total_count', jsonb_array_length(v_alerts)
  );
END;
$function$;

-- Function: get_player_profile
CREATE OR REPLACE FUNCTION public.get_player_profile(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player record;
  v_city_name text;
  v_progress jsonb;
  v_featured_badges jsonb := '[]'::jsonb;
  v_unlocked_count integer := 0;
  v_total_count integer := 0;
  v_company_value jsonb := '{}'::jsonb;
begin
  if p_player_id is null then
    return null;
  end if;

  -- Ensure player row exists ONLY if user has valid active auth session
  if auth.uid() is not null and auth.uid() = p_player_id then
    perform public.ensure_player_record_exists(p_player_id);
  end if;

  select p.*, c.name as headquarters_city_name
  into v_player
  from public.players p
  left join public.cities c on c.id = p.headquarters_city_id
  where p.id = p_player_id;

  if not found then
    return null;
  end if;

  v_progress := public.build_level_progress_payload(
    coalesce(v_player.level, 1),
    coalesce(v_player.experience, 0)
  );

  perform public.ensure_player_achievement_rows(p_player_id);
  perform public.sync_player_achievement_snapshot(p_player_id);

  v_company_value := public.calculate_player_company_value(p_player_id);
  perform public.refresh_player_leaderboard_stats(p_player_id);

  select
    coalesce(
      jsonb_agg(public.build_player_achievement_payload(p_player_id, achievement_id) order by unlocked_at desc nulls last, display_order asc),
      '[]'::jsonb
    )
  into v_featured_badges
  from (
    select pa.achievement_id, pa.unlocked_at, ad.display_order
    from public.player_achievements pa
    join public.achievement_definitions ad on ad.id = pa.achievement_id
    where pa.player_id = p_player_id
      and ad.is_active = true
      and pa.is_unlocked = true
    order by pa.unlocked_at desc nulls last, ad.display_order asc
    limit 4
  ) featured_pick;

  select
    count(*) filter (where pa.is_unlocked = true),
    count(*)
  into v_unlocked_count, v_total_count
  from public.player_achievements pa
  join public.achievement_definitions ad on ad.id = pa.achievement_id
  where pa.player_id = p_player_id
    and ad.is_active = true;

  return jsonb_build_object(
    'id', v_player.id,
    'player_name', v_player.player_name,
    'company_name', v_player.company_name,
    'avatar_id', v_player.avatar_id,
    'headquarters_city_id', v_player.headquarters_city_id,
    'headquarters_city_name', v_player.headquarters_city_name,
    'level', coalesce(v_player.level, 1),
    'experience', v_player.experience,
    'cash', v_player.cash,
    'gold', v_player.gold,
    'company_value', coalesce((v_company_value ->> 'total_company_value')::numeric, 0),
    'company_value_breakdown', v_company_value,
    'created_at', v_player.created_at,
    'current_level_start_experience', coalesce((v_progress ->> 'current_level_start_experience')::integer, 0),
    'next_level_total_experience', coalesce((v_progress ->> 'next_level_total_experience')::integer, 0),
    'current_level_experience', coalesce((v_progress ->> 'current_level_experience')::integer, 0),
    'next_level_required_experience', coalesce((v_progress ->> 'next_level_required_experience')::integer, 1),
    'remaining_experience_to_next_level', coalesce((v_progress ->> 'remaining_experience_to_next_level')::integer, 0),
    'exp_progress_ratio', coalesce((v_progress ->> 'progress_ratio')::numeric, 0),
    'achievement_unlocked_count', coalesce(v_unlocked_count, 0),
    'achievement_total_count', coalesce(v_total_count, 0),
    'featured_badges', v_featured_badges
  );
end;
$function$;

-- Function: get_player_tax_debt
CREATE OR REPLACE FUNCTION public.get_player_tax_debt()
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_tax numeric;
BEGIN
  if v_player_id is null then
    return 0;
  end if;
  select tax_debt into v_tax from public.player_taxes where player_id = v_player_id;
  return coalesce(v_tax, 0);
END;
$function$;

-- Function: get_player_tax_limit
CREATE OR REPLACE FUNCTION public.get_player_tax_limit(p_level integer)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_level <= 1 then return 10000;
  elsif p_level = 2 then return 25000;
  elsif p_level = 3 then return 50000;
  elsif p_level = 4 then return 100000;
  elsif p_level = 5 then return 250000;
  elsif p_level = 6 then return 500000;
  elsif p_level = 7 then return 1000000;
  else return p_level * 200000;
  end if;
end;
$function$;

-- Function: get_player_tax_status
CREATE OR REPLACE FUNCTION public.get_player_tax_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_tax_debt numeric := 0;
  v_level integer := 1;
  v_limit numeric := 0;
  v_is_blocked boolean := false;
begin
  if v_player_id is null then
    return jsonb_build_object(
      'tax_debt', 0,
      'tax_limit', 0,
      'is_blocked', false
    );
  end if;

  select coalesce(tax_debt, 0) into v_tax_debt
  from public.player_taxes
  where player_id = v_player_id;

  select coalesce(level, 1) into v_level
  from public.players
  where id = v_player_id;

  v_limit := public.get_player_tax_limit(v_level);
  v_is_blocked := v_tax_debt > v_limit;

  return jsonb_build_object(
    'tax_debt', v_tax_debt,
    'tax_limit', v_limit,
    'is_blocked', v_is_blocked
  );
end;
$function$;

-- Function: get_player_warehouse_detail
CREATE OR REPLACE FUNCTION public.get_player_warehouse_detail(p_warehouse_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select (
    to_jsonb(w) ||
    jsonb_build_object(
      'warehouse_slots',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(ws) ||
            jsonb_build_object('product', to_jsonb(p))
            order by ws.id
          )
          from public.warehouse_slots ws
          left join public.products p on p.id = ws.product_id
          where ws.warehouse_id = w.id
        ),
        '[]'::jsonb
      ),
      'city',
      (
        select to_jsonb(c)
        from public.cities c
        where c.id = w.city_id
      ),
      'warehouse_type',
      (
        select to_jsonb(wt)
        from public.warehouse_types wt
        where wt.id = w.warehouse_type_id
      )
    )
  )
  from public.warehouses w
  where w.id = p_warehouse_id
    and w.player_id = auth.uid();
$function$;

-- Function: get_player_warehouses_raw
CREATE OR REPLACE FUNCTION public.get_player_warehouses_raw()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      (
        to_jsonb(w) ||
        jsonb_build_object(
          'reserved_capacity', w.reserved_capacity + coalesce(
            (
              select sum(coalesce(ws.quantity, 0) * coalesce(p.birim_hacim, 0))
              from public.warehouse_slots ws
              join public.products p on p.id = ws.product_id
              where ws.warehouse_id = w.id
            ),
            0
          ),
          'warehouse_slots',
          coalesce(
            (
              select jsonb_agg(
                to_jsonb(ws) ||
                jsonb_build_object('product', to_jsonb(p))
                order by ws.id
              )
              from public.warehouse_slots ws
              left join public.products p on p.id = ws.product_id
              where ws.warehouse_id = w.id
            ),
            '[]'::jsonb
          ),
          'city',
          (
            select to_jsonb(c)
            from public.cities c
            where c.id = w.city_id
          ),
          'warehouse_type',
          (
            select to_jsonb(wt)
            from public.warehouse_types wt
            where wt.id = w.warehouse_type_id
          )
        )
      )
      order by w.created_at
    ),
    '[]'::jsonb
  )
  from public.warehouses w
  where w.player_id = auth.uid();
$function$;

-- Function: get_producible_products_for_owner_type
CREATE OR REPLACE FUNCTION public.get_producible_products_for_owner_type(p_player_id uuid, p_owner_kind text, p_type_id uuid)
 RETURNS TABLE(id text, urun_adi text, urun_iconu text, birim_hacim numeric, birim_agirlik numeric, hammadde_1_id text, hammadde_1_miktar numeric, hammadde_2_id text, hammadde_2_miktar numeric, hammadde_3_id text, hammadde_3_miktar numeric, uretim_birimi text, baz_satis_fiyati numeric, uretim_adedi integer, satis_adedi integer, en_dusuk_fiyat numeric, en_yuksek_fiyat numeric, ortalama_fiyat numeric, satici_sayisi integer, piyasadaki_stok integer, created_at timestamp with time zone, max_quality_level integer, preferred_brand_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner_kind text := lower(trim(coalesce(p_owner_kind, '')));
  v_accepted_product_ids text;
  v_allowed_units text[];
  v_auth_player_id uuid;
begin
  v_auth_player_id := auth.uid();

  if v_auth_player_id is null then
    raise exception 'Oturum bulunamadi.';
  end if;

  if p_player_id is null or p_player_id <> v_auth_player_id then
    raise exception 'Gecersiz oyuncu kimligi.';
  end if;

  if p_type_id is null then
    raise exception 'Isletme turu bos olamaz.';
  end if;

  case v_owner_kind
    when 'field' then
      select ft.accepted_product_ids
      into v_accepted_product_ids
      from public.field_types ft
      where ft.id = p_type_id;
      v_allowed_units := array['farm', 'ciftlik', 'çiftlik'];
    when 'farm' then
      select ft.accepted_product_ids
      into v_accepted_product_ids
      from public.farm_types ft
      where ft.id = p_type_id;
      v_allowed_units := array['field', 'tarla'];
    when 'factory' then
      select ft.accepted_product_ids
      into v_accepted_product_ids
      from public.factory_types ft
      where ft.id = p_type_id;
      v_allowed_units := array['factory', 'fabrika'];
    when 'mine' then
      select mt.accepted_product_ids
      into v_accepted_product_ids
      from public.mine_types mt
      where mt.id = p_type_id;
      v_allowed_units := array['mine', 'maden'];
    else
      raise exception 'Desteklenmeyen owner_kind: %', p_owner_kind;
  end case;

  if not found then
    raise exception 'Isletme turu bulunamadi.';
  end if;

  if coalesce(trim(v_accepted_product_ids), '') = '' then
    return;
  end if;

  return query
  with quality_levels as (
    select
      ppql.product_id,
      max(ppql.max_quality_level)::integer as max_quality_level
    from public.player_product_quality_levels ppql
    where ppql.player_id = p_player_id
    group by ppql.product_id
  )
  select
    p.id,
    p.urun_adi,
    p.urun_iconu,
    p.birim_hacim,
    p.birim_agirlik,
    p.hammadde_1_id,
    p.hammadde_1_miktar,
    p.hammadde_2_id,
    p.hammadde_2_miktar,
    p.hammadde_3_id,
    p.hammadde_3_miktar,
    p.uretim_birimi,
    p.baz_satis_fiyati,
    p.uretim_adedi,
    p.satis_adedi,
    p.en_dusuk_fiyat,
    p.en_yuksek_fiyat,
    p.ortalama_fiyat,
    p.satici_sayisi,
    p.piyasadaki_stok,
    p.created_at,
    coalesce(ql.max_quality_level, 1) as max_quality_level,
    public.resolve_player_product_brand(p_player_id, p.id) as preferred_brand_id
  from public.products p
  left join quality_levels ql on ql.product_id = p.id
  where p.id = any(regexp_split_to_array(v_accepted_product_ids, '\s*,\s*'))
    and lower(trim(coalesce(p.uretim_birimi, ''))) = any(v_allowed_units)
  order by p.urun_adi asc;
end;
$function$;

-- Function: get_product_price_history
CREATE OR REPLACE FUNCTION public.get_product_price_history(p_product_id text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'product_id', ph.product_id,
    'price_day_4', COALESCE(ph.price_day_4, 0),
    'price_day_3', COALESCE(ph.price_day_3, 0),
    'price_day_2', COALESCE(ph.price_day_2, 0),
    'price_day_1', COALESCE(ph.price_day_1, 0),
    'price_day_0', COALESCE(ph.price_day_0, 0),
    'updated_at', COALESCE(ph.updated_at, timezone('utc', now()))
  )
  FROM public.product_price_history ph
  WHERE ph.product_id = p_product_id
  LIMIT 1;
$function$;

-- Function: get_rewarded_ad_reward_status
CREATE OR REPLACE FUNCTION public.get_rewarded_ad_reward_status(p_player_id uuid, p_reward_kind text, p_resource_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := timezone('utc'::text, now());
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_cooldown_seconds integer;
  v_daily_limit integer;
  v_resource_daily_limit integer;
  v_resource_key text;
  v_global_count integer;
  v_kind_count integer;
  v_resource_count integer := 0;
  v_last_used_at timestamptz;
  v_wait_seconds integer := 0;
  v_next_reward_minutes integer;
  v_message text;
BEGIN
  IF p_player_id IS NULL OR p_player_id <> auth.uid() THEN
    RETURN jsonb_build_object('allowed', false, 'message', 'Gecersiz oyuncu.');
  END IF;

  CASE p_reward_kind
    WHEN 'construction_time_reduce' THEN
      v_cooldown_seconds := 45;
      v_daily_limit := 8;
      v_resource_daily_limit := 3;
      v_resource_key := 'construction_id';
    WHEN 'upgrade_time_reduce' THEN
      v_cooldown_seconds := 45;
      v_daily_limit := 8;
      v_resource_daily_limit := 3;
      v_resource_key := 'upgrade_id';
    WHEN 'transfer_finish' THEN
      v_cooldown_seconds := 60;
      v_daily_limit := 4;
    WHEN 'building_boost_start' THEN
      v_cooldown_seconds := 90;
      v_daily_limit := 3;
      v_resource_daily_limit := 1;
      v_resource_key := 'resource_id';
    ELSE
      RETURN jsonb_build_object('allowed', false, 'message', 'Bilinmeyen reklam odulu turu.');
  END CASE;

  v_day_start := date_trunc('day', timezone('Europe/Istanbul', v_now))
    AT TIME ZONE 'Europe/Istanbul';
  v_day_end := v_day_start + interval '1 day';

  SELECT count(*)::integer
  INTO v_global_count
  FROM public.player_rewarded_ad_usages
  WHERE player_id = p_player_id
    AND created_at >= v_day_start
    AND created_at < v_day_end;

  SELECT count(*)::integer, max(created_at)
  INTO v_kind_count, v_last_used_at
  FROM public.player_rewarded_ad_usages
  WHERE player_id = p_player_id
    AND reward_kind = p_reward_kind
    AND created_at >= v_day_start
    AND created_at < v_day_end;

  IF v_resource_key IS NOT NULL AND p_resource_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_resource_count
    FROM public.player_rewarded_ad_usages
    WHERE player_id = p_player_id
      AND reward_kind = p_reward_kind
      AND created_at >= v_day_start
      AND created_at < v_day_end
      AND metadata ->> v_resource_key = p_resource_id;
  END IF;

  IF v_last_used_at IS NOT NULL THEN
    v_wait_seconds := GREATEST(
      CEIL(v_cooldown_seconds - EXTRACT(EPOCH FROM (v_now - v_last_used_at)))::integer,
      0
    );
  END IF;

  IF p_reward_kind IN ('construction_time_reduce', 'upgrade_time_reduce') THEN
    v_next_reward_minutes := CASE
      WHEN v_kind_count < 4 THEN 10
      WHEN v_kind_count < 6 THEN 7
      WHEN v_kind_count < 8 THEN 5
      ELSE 0
    END;
  ELSIF p_reward_kind = 'building_boost_start' THEN
    v_next_reward_minutes := 30;
  END IF;

  v_message := CASE
    WHEN v_global_count >= 15
      THEN 'Bugunku toplam 15 reklam odulu limitine ulastin. Yarin tekrar kullanabilirsin.'
    WHEN v_kind_count >= v_daily_limit
      THEN format('Bu reklam odulu icin bugunku %s kullanim hakkini doldurdun.', v_daily_limit)
    WHEN v_resource_daily_limit IS NOT NULL AND v_resource_count >= v_resource_daily_limit
      THEN 'Bu islem icin bugunku reklam odulu hakkini doldurdun. Baska bir islemde kullanabilir veya yarini bekleyebilirsin.'
    WHEN v_wait_seconds > 0
      THEN format('Yeni reklam odulu icin %s saniye beklemelisin.', v_wait_seconds)
    ELSE 'Reklam odulu kullanilabilir.'
  END;

  RETURN jsonb_build_object(
    'allowed', v_global_count < 15
      AND v_kind_count < v_daily_limit
      AND (v_resource_daily_limit IS NULL OR v_resource_count < v_resource_daily_limit)
      AND v_wait_seconds = 0,
    'message', v_message,
    'daily_used', v_kind_count,
    'daily_limit', v_daily_limit,
    'global_daily_used', v_global_count,
    'global_daily_limit', 15,
    'resource_daily_used', v_resource_count,
    'resource_daily_limit', v_resource_daily_limit,
    'cooldown_remaining_seconds', v_wait_seconds,
    'next_reward_minutes', v_next_reward_minutes
  );
END;
$function$;

-- Function: get_route_transfer_vehicle_options
CREATE OR REPLACE FUNCTION public.get_route_transfer_vehicle_options(p_source_city_id uuid, p_target_city_id uuid, p_total_volume numeric)
 RETURNS TABLE(vehicle_id uuid, vehicle_owner_player_id uuid, vehicle_name text, is_rental boolean, capacity integer, speed_kmh integer, current_fuel integer, fuel_capacity integer, fuel_rate numeric, condition integer, rental_price numeric, distance_km numeric, fuel_needed numeric, condition_needed numeric, rental_cost numeric, fuel_cost numeric, total_price numeric, estimated_duration_seconds integer, can_select boolean, disabled_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_default_vehicle_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_distance_km numeric := 0;
  v_required_capacity integer;
  v_npc_player_id uuid;
begin
  if v_player_id is null then
    raise exception 'Oturum acilmamis.';
  end if;

  if p_source_city_id is null or p_target_city_id is null then
    raise exception 'Kaynak ve hedef sehir secilmelidir.';
  end if;

  if p_total_volume is null or p_total_volume <= 0 then
    raise exception 'Toplam hacim 0 dan buyuk olmalidir.';
  end if;

  v_required_capacity := ceil(p_total_volume);
  v_npc_player_id := public.get_npc_logistics_player_id();

  if p_source_city_id = p_target_city_id then
    return query
    select
      v_default_vehicle_id as vehicle_id,
      v_player_id as vehicle_owner_player_id,
      'Anlik Transfer'::text as vehicle_name,
      false as is_rental,
      greatest(v_required_capacity, 1) as capacity,
      999 as speed_kmh,
      999 as current_fuel,
      999 as fuel_capacity,
      0::numeric as fuel_rate,
      100 as condition,
      0::numeric as rental_price,
      0::numeric as distance_km,
      0::numeric as fuel_needed,
      0::numeric as condition_needed,
      0::numeric as rental_cost,
      0::numeric as fuel_cost,
      0::numeric as total_price,
      0 as estimated_duration_seconds,
      true as can_select,
      null::text as disabled_reason;
    return;
  end if;

  select round(
    (
      6371 * 2 * asin(
        sqrt(
          power(
            sin(radians(coalesce(tc.map_position_x, 0) - coalesce(sc.map_position_x, 0)) / 2),
            2
          ) +
          cos(radians(coalesce(sc.map_position_x, 0))) *
          cos(radians(coalesce(tc.map_position_x, 0))) *
          power(
            sin(radians(coalesce(tc.map_position_y, 0) - coalesce(sc.map_position_y, 0)) / 2),
            2
          )
        )
      )
    )::numeric,
    2
  )
  into v_distance_km
  from public.cities sc
  join public.cities tc on tc.id = p_target_city_id
  where sc.id = p_source_city_id;

  return query
  with own_vehicles as (
    select
      lv.id as vehicle_id,
      lv.player_id as vehicle_owner_player_id,
      coalesce(lvt.name, 'Arac')::text as vehicle_name,
      false as is_rental,
      coalesce(lv.capacity, 0) as capacity,
      coalesce(lv.speed_kmh, 0) as speed_kmh,
      coalesce(lv.current_fuel, 0) as current_fuel,
      coalesce(lv.fuel_capacity, 0) as fuel_capacity,
      coalesce(lv.fuel_rate, 0) as fuel_rate,
      coalesce(lv.condition, 0) as condition,
      coalesce(lv.rental_price, 0) as rental_price,
      v_distance_km as distance_km,
      round(v_distance_km * coalesce(lv.fuel_rate, 0), 2) as fuel_needed,
      greatest(1, ceil(v_distance_km / 200.0))::numeric as condition_needed,
      0::numeric as rental_cost,
      round(v_distance_km * coalesce(lv.fuel_rate, 0) * coalesce(lv.fuel_cost, 0), 2) as fuel_cost,
      round(v_distance_km * coalesce(lv.fuel_rate, 0) * coalesce(lv.fuel_cost, 0), 2) as total_price,
      greatest(60, ceil((greatest(v_distance_km, 1) / greatest(coalesce(lv.speed_kmh, 0), 1)) * 120))::integer as estimated_duration_seconds,
      (
        coalesce(lv.status, '') = 'idle'
        and coalesce(lv.capacity, 0) >= v_required_capacity
        and coalesce(lv.speed_kmh, 0) > 0
        and coalesce(lv.current_fuel, 0) >= ceil(v_distance_km * coalesce(lv.fuel_rate, 0))
        and coalesce(lv.condition, 0) > 0
        and public.logistics_vehicle_matches_route(
          lv.route_city_a_id,
          lv.route_city_b_id,
          p_source_city_id,
          p_target_city_id
        )
      ) as can_select,
      case
        when coalesce(lv.status, '') <> 'idle' then 'Arac mesgul'
        when not public.logistics_vehicle_matches_route(
          lv.route_city_a_id,
          lv.route_city_b_id,
          p_source_city_id,
          p_target_city_id
        ) then 'Rota uyumsuz'
        when coalesce(lv.capacity, 0) < v_required_capacity then format('Kapasite yetersiz (Arac: %s m3, Yuk: %s m3)', coalesce(lv.capacity, 0), v_required_capacity)
        when coalesce(lv.speed_kmh, 0) <= 0 then 'Arac hizi gecersiz'
        when coalesce(lv.current_fuel, 0) < ceil(v_distance_km * coalesce(lv.fuel_rate, 0)) then 'Yeterli yakit yok'
        when coalesce(lv.condition, 0) <= 0 then 'Bakim gerekli'
        else null
      end::text as disabled_reason
    from public.logistics_vehicles lv
    left join public.logistics_vehicle_types lvt on lvt.id = lv.logistics_vehicle_type_id
    where lv.player_id = v_player_id
      and public.logistics_vehicle_matches_route(
        lv.route_city_a_id,
        lv.route_city_b_id,
        p_source_city_id,
        p_target_city_id
      )
  ),
  player_rental_vehicles as (
    select
      lv.id as vehicle_id,
      lv.player_id as vehicle_owner_player_id,
      coalesce(lvt.name, 'Kiralik Arac')::text as vehicle_name,
      true as is_rental,
      coalesce(lv.capacity, 0) as capacity,
      coalesce(lv.speed_kmh, 0) as speed_kmh,
      coalesce(lv.current_fuel, 0) as current_fuel,
      coalesce(lv.fuel_capacity, 0) as fuel_capacity,
      coalesce(lv.fuel_rate, 0) as fuel_rate,
      coalesce(lv.condition, 0) as condition,
      coalesce(lv.rental_price, 0) as rental_price,
      v_distance_km as distance_km,
      round(v_distance_km * coalesce(lv.fuel_rate, 0), 2) as fuel_needed,
      greatest(1, ceil(v_distance_km / 200.0))::numeric as condition_needed,
      round(v_distance_km * coalesce(lv.rental_price, 0), 2) as rental_cost,
      0::numeric as fuel_cost,
      round(v_distance_km * coalesce(lv.rental_price, 0), 2) as total_price,
      greatest(60, ceil((greatest(v_distance_km, 1) / greatest(coalesce(lv.speed_kmh, 0), 1)) * 120))::integer as estimated_duration_seconds,
      (
        coalesce(lv.status, '') = 'idle'
        and coalesce(lv.is_available_for_rent, false) = true
        and coalesce(lv.capacity, 0) >= v_required_capacity
        and coalesce(lv.speed_kmh, 0) > 0
        and coalesce(lv.current_fuel, 0) >= ceil(v_distance_km * coalesce(lv.fuel_rate, 0))
        and coalesce(lv.condition, 0) > 0
        and public.logistics_vehicle_matches_route(
          lv.route_city_a_id,
          lv.route_city_b_id,
          p_source_city_id,
          p_target_city_id
        )
      ) as can_select,
      case
        when coalesce(lv.status, '') <> 'idle' then 'Arac mesgul'
        when coalesce(lv.is_available_for_rent, false) = false then 'Kiraya acik degil'
        when not public.logistics_vehicle_matches_route(
          lv.route_city_a_id,
          lv.route_city_b_id,
          p_source_city_id,
          p_target_city_id
        ) then 'Rota uyumsuz'
        when coalesce(lv.capacity, 0) < v_required_capacity then format('Kapasite yetersiz (Arac: %s m3, Yuk: %s m3)', coalesce(lv.capacity, 0), v_required_capacity)
        when coalesce(lv.speed_kmh, 0) <= 0 then 'Arac hizi gecersiz'
        when coalesce(lv.current_fuel, 0) < ceil(v_distance_km * coalesce(lv.fuel_rate, 0)) then 'Yeterli yakit yok'
        when coalesce(lv.condition, 0) <= 0 then 'Bakim gerekli'
        else null
      end::text as disabled_reason
    from public.logistics_vehicles lv
    left join public.logistics_vehicle_types lvt on lvt.id = lv.logistics_vehicle_type_id
    where lv.player_id <> v_player_id
      and lv.player_id <> v_npc_player_id
      and coalesce(lv.is_available_for_rent, false) = true
      and public.logistics_vehicle_matches_route(
        lv.route_city_a_id,
        lv.route_city_b_id,
        p_source_city_id,
        p_target_city_id
      )
  ),
  npc_vehicle as (
    select
      n.vehicle_id,
      n.vehicle_owner_player_id,
      n.vehicle_name,
      n.is_rental,
      n.capacity,
      n.speed_kmh,
      n.current_fuel,
      n.fuel_capacity,
      n.fuel_rate,
      n.condition,
      n.rental_price,
      n.distance_km,
      n.fuel_needed,
      n.condition_needed,
      n.rental_cost,
      0::numeric as fuel_cost,
      coalesce(n.rental_cost, 0)::numeric as total_price,
      n.estimated_duration_seconds,
      (coalesce(n.capacity, 0) >= v_required_capacity) as can_select,
      case
        when coalesce(n.capacity, 0) < v_required_capacity then format('Kapasite yetersiz (Arac: %s m3, Yuk: %s m3)', coalesce(n.capacity, 0), v_required_capacity)
        else n.disabled_reason
      end::text as disabled_reason
    from public.get_npc_rental_vehicle_option(
      p_source_city_id,
      p_target_city_id,
      v_distance_km
    ) n
  ),
  all_union as (
    select * from own_vehicles
    union all
    select * from player_rental_vehicles
    union all
    select * from npc_vehicle
  )
  select * from all_union
  order by can_select desc, total_price asc, estimated_duration_seconds asc
  limit 8;
end;
$function$;

-- Function: get_seller_market_sales_history
CREATE OR REPLACE FUNCTION public.get_seller_market_sales_history(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_player_id uuid := auth.uid();
  v_sales jsonb := '[]'::jsonb;
  v_total_sales_count integer := 0;
  v_total_sold_quantity bigint := 0;
  v_total_revenue numeric := 0;
BEGIN
  IF v_player_id IS NULL THEN
    v_player_id := nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;
  END IF;

  IF v_player_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  END IF;

  -- Calculate summary stats
  SELECT
    count(*)::integer,
    coalesce(sum(coalesce(lt.total_quantity, lt.quantity, 0)), 0)::bigint,
    coalesce(sum(coalesce(lt.total_price, 0)), 0)::numeric
  INTO
    v_total_sales_count,
    v_total_sold_quantity,
    v_total_revenue
  FROM public.logistics_transfers lt
  WHERE lt.seller_player_id = v_player_id
    AND lt.buyer_player_id IS NOT NULL
    AND lt.buyer_player_id <> v_player_id
    AND lt.transfer_type IN ('market_to_warehouse_multi', 'market_transfer');

  -- Aggregate sales list with items and buyer details
  WITH transfer_items AS (
    SELECT
      lti.transfer_id,
      jsonb_agg(
        jsonb_build_object(
          'id', lti.id,
          'product_id', lti.product_id,
          'product_name', coalesce(p.urun_adi, 'Urun'),
          'product_icon', coalesce(p.urun_iconu, 'default.webp'),
          'quantity', coalesce(lti.quantity, 0),
          'quality_level', coalesce(lti.quality_level, 1),
          'unit_price', coalesce(lti.unit_price, 0)::double precision,
          'total_price', coalesce(lti.total_price, 0)::double precision,
          'brand_id', lti.brand_id
        )
        ORDER BY lti.created_at ASC, lti.id ASC
      ) AS items
    FROM public.logistics_transfer_items lti
    JOIN public.products p ON p.id = lti.product_id
    GROUP BY lti.transfer_id
  )
  SELECT coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', lt.id,
        'transfer_type', lt.transfer_type,
        'status', lt.status,
        'total_price', coalesce(lt.total_price, 0)::double precision,
        'total_quantity', coalesce(nullif(lt.total_quantity, 0), lt.quantity, 0),
        'item_count', greatest(coalesce(lt.item_count, 1), 1),
        'started_at', lt.started_at,
        'finish_at', lt.finish_at,
        'completed_at', coalesce(lt.completed_at, lt.finish_at, lt.started_at),
        'buyer_player_id', bp.id,
        'buyer_player_name', coalesce(bp.player_name, 'Oyuncu'),
        'buyer_company_name', coalesce(bp.company_name, 'Sirket'),
        'buyer_avatar_id', coalesce(bp.avatar_id, 'ae1.webp'),
        'seller_warehouse_name', coalesce(sw.name, 'Depo'),
        'seller_city_name', coalesce(swc.name, '-'),
        'buyer_city_name', coalesce(bwc.name, '-'),
        'items', coalesce(
          ti.items,
          case
            when lt.product_id is not null then
              jsonb_build_array(
                jsonb_build_object(
                  'id', lt.id,
                  'product_id', lt.product_id,
                  'product_name', coalesce(p_single.urun_adi, 'Urun'),
                  'product_icon', coalesce(p_single.urun_iconu, 'default.webp'),
                  'quantity', coalesce(lt.quantity, 0),
                  'quality_level', coalesce(lt.quality_level, 1),
                  'unit_price', coalesce(lt.unit_price, 0)::double precision,
                  'total_price', coalesce(lt.total_price, 0)::double precision,
                  'brand_id', lt.brand_id
                )
              )
            else '[]'::jsonb
          end
        )
      )
      ORDER BY coalesce(lt.completed_at, lt.started_at) DESC, lt.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_sales
  FROM (
    SELECT *
    FROM public.logistics_transfers
    WHERE seller_player_id = v_player_id
      AND buyer_player_id IS NOT NULL
      AND buyer_player_id <> v_player_id
      AND transfer_type IN ('market_to_warehouse_multi', 'market_transfer')
    ORDER BY coalesce(completed_at, started_at) DESC, id DESC
    LIMIT p_limit
  ) lt
  LEFT JOIN public.players bp ON bp.id = lt.buyer_player_id
  LEFT JOIN public.warehouses sw ON sw.id = lt.seller_warehouse_id
  LEFT JOIN public.cities swc ON swc.id = sw.city_id
  LEFT JOIN public.warehouses bw ON bw.id = lt.buyer_warehouse_id
  LEFT JOIN public.cities bwc ON bwc.id = bw.city_id
  LEFT JOIN transfer_items ti ON ti.transfer_id = lt.id
  LEFT JOIN public.products p_single ON p_single.id = lt.product_id;

  RETURN jsonb_build_object(
    'success', true,
    'total_sales_count', v_total_sales_count,
    'total_sold_quantity', v_total_sold_quantity,
    'total_revenue', v_total_revenue,
    'sales', v_sales
  );
END;
$function$;

-- Function: get_static_catalogs_bundle
CREATE OR REPLACE FUNCTION public.get_static_catalogs_bundle()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'cities', coalesce(public.get_active_cities(), '[]'::jsonb),
    'products', coalesce(public.get_all_products_catalog(), '[]'::jsonb),
    'store_types', coalesce(public.get_store_types_catalog(), '[]'::jsonb),
    'warehouse_types', coalesce(public.get_warehouse_types_catalog(), '[]'::jsonb),
    'factory_types', coalesce(public.get_factory_types_catalog(), '[]'::jsonb),
    'farm_types', coalesce(public.get_farm_types_catalog(), '[]'::jsonb),
    'field_types', coalesce(public.get_field_types_catalog(), '[]'::jsonb),
    'mine_types', coalesce(public.get_mine_types_catalog(), '[]'::jsonb),
    'logistics_company_types', coalesce(public.get_logistics_company_types_catalog(), '[]'::jsonb),
    'logistics_vehicle_types', coalesce(public.get_logistics_vehicle_types_catalog(), '[]'::jsonb)
  );
$function$;

-- Function: get_store_daily_performance
CREATE OR REPLACE FUNCTION public.get_store_daily_performance(p_player_id uuid, p_store_id uuid, p_days integer DEFAULT 14)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_store_id uuid;
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb;
  v_from_date date := timezone('Europe/Istanbul', now())::date - greatest(coalesce(p_days, 14), 1) + 1;
begin
  select s.id into v_store_id
  from stores s
  where s.id = p_store_id
    and s.player_id = p_player_id;

  if v_store_id is null then
    return jsonb_build_object(
      'success', false,
      'message', 'Magaza bulunamadi.'
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'performance_date', perf.performance_date,
        'store_slot_id', perf.store_slot_id,
        'slot_index', perf.slot_index,
        'product_id', perf.product_id,
        'product_name', perf.product_name,
        'quality_level', perf.quality_level,
        'sold_quantity', perf.sold_quantity,
        'revenue', perf.revenue,
        'profit', perf.profit,
        'sale_event_count', perf.sale_event_count,
        'last_sale_at', perf.last_sale_at
      )
      order by perf.performance_date desc, perf.slot_index asc
    ),
    '[]'::jsonb
  ) into v_rows
  from public.store_daily_performance perf
  where perf.store_id = p_store_id
    and perf.performance_date >= v_from_date;

  select jsonb_build_object(
    'total_revenue', coalesce(sum(perf.revenue), 0),
    'total_profit', coalesce(sum(perf.profit), 0),
    'total_sold_quantity', coalesce(sum(perf.sold_quantity), 0),
    'total_sale_events', coalesce(sum(perf.sale_event_count), 0)
  ) into v_summary
  from public.store_daily_performance perf
  where perf.store_id = p_store_id
    and perf.performance_date >= v_from_date;

  return jsonb_build_object(
    'success', true,
    'summary', v_summary,
    'rows', v_rows
  );
end;
$function$;

-- Function: get_store_history_items
CREATE OR REPLACE FUNCTION public.get_store_history_items(p_store_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with transfer_items as (
    select jsonb_build_object(
      'id', 'transfer_' || lt.id::text,
      'type',
        case when (lt.buyer_store_id = p_store_id or lt.buyer_warehouse_id in (select id from public.warehouses where store_id = p_store_id)) then 'incoming_transfer' else 'outgoing_transfer' end,
      'happened_at', coalesce(lt.completed_at, lt.finish_at, lt.started_at),
      'title',
        case
          when (lt.buyer_store_id = p_store_id or lt.buyer_warehouse_id in (select id from public.warehouses where store_id = p_store_id)) then
            case
              when lt.status = 'in_transit' then
                case when coalesce(lt.total_price, 0) > 0 then 'Pazardan Geliyor' else 'Depodan Geliyor' end
              else
                case when coalesce(lt.total_price, 0) > 0 then 'Pazardan Geldi' else 'Depodan Geldi' end
            end
          else
            case
              when lt.status = 'in_transit' then 'Depoya Gonderiliyor'
              else 'Depoya Gonderildi'
            end
        end,
      'subtitle',
        case
          when (lt.buyer_store_id = p_store_id or lt.buyer_warehouse_id in (select id from public.warehouses where store_id = p_store_id)) then
            coalesce(sw.name, 'Depo') || ' | ' || coalesce(sc.name, 'Sehir')
          else
            coalesce(bw.name, 'Depo') || ' | ' || coalesce(bc.name, 'Sehir')
        end,
      'product_name', coalesce(p.urun_adi, 'Urun'),
      'quantity', coalesce(lt.quantity, 0),
      'amount', coalesce(lt.total_price, 0),
      'secondary_amount', lt.rental_cost,
      'quality_level', lt.quality_level,
      'status', coalesce(lt.status, 'completed')
    ) as item
    from public.logistics_transfers lt
    left join public.warehouses sw on sw.id = lt.seller_warehouse_id
    left join public.cities sc on sc.id = sw.city_id
    left join public.warehouses bw on bw.id = lt.buyer_warehouse_id
    left join public.cities bc on bc.id = bw.city_id
    left join public.products p on p.id = lt.product_id
    join public.stores s on s.id = p_store_id and s.player_id = auth.uid()
    where (
      lt.buyer_store_id = p_store_id 
      or lt.seller_store_id = p_store_id
      or lt.buyer_warehouse_id in (select id from public.warehouses where store_id = p_store_id)
      or lt.seller_warehouse_id in (select id from public.warehouses where store_id = p_store_id)
    )
  ),
  sale_items as (
    select jsonb_build_object(
      'id', 'sale_' || sdp.id::text,
      'type', 'sale',
      'happened_at', coalesce(sdp.last_sale_at, sdp.performance_date::timestamp),
      'title', 'Satis Ozeti',
      'subtitle', coalesce(sdp.sale_event_count, 0)::text || ' satis islemi',
      'product_name', coalesce(sdp.product_name, 'Urun'),
      'quantity', coalesce(sdp.sold_quantity, 0),
      'amount', coalesce(sdp.revenue, 0),
      'secondary_amount', sdp.profit,
      'quality_level', sdp.quality_level,
      'status', 'completed'
    ) as item
    from public.store_daily_performance sdp
    join public.stores s on s.id = sdp.store_id and s.player_id = auth.uid()
    where sdp.store_id = p_store_id
      and sdp.sold_quantity > 0
  ),
  all_items as (
    select item from transfer_items
    union all
    select item from sale_items
  )
  select coalesce(
    jsonb_agg(item order by (item->>'happened_at')::timestamptz desc),
    '[]'::jsonb
  )
  from (
    select item
    from all_items
    order by (item->>'happened_at')::timestamptz desc
    limit 100
  ) ranked;
$function$;

-- Function: get_store_list_page_data
CREATE OR REPLACE FUNCTION public.get_store_list_page_data()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with live_rows as (
    select
      s.id,
      s.created_at as sort_time,
      s.name as sort_name,
      false as is_under_construction,
      s.is_active,
      coalesce(slot_summary.total_capacity, 0) as total_capacity,
      jsonb_build_object(
        'id', s.id,
        'name', s.name,
        'city_id', s.city_id,
        'city_name', c.name,
        'level', s.level,
        'is_active', s.is_active,
        'current_slot_count', s.current_slot_count,
        'max_slot_count', s.max_slot_count,
        'slot_capacity', s.slot_capacity,
        'store_type', jsonb_build_object(
          'id', st.id,
          'name', st.name,
          'icon', st.icon,
          'cost', st.cost,
          'required_level', st.required_level,
          'construction_time_minutes', st.construction_time_minutes
        ),
        'summary', jsonb_build_object(
          'total_quantity', coalesce(slot_summary.total_quantity, 0),
          'total_capacity', coalesce(slot_summary.total_capacity, 0),
          'pending_quantity', coalesce(slot_summary.pending_quantity, 0),
          'available_capacity', greatest(
            coalesce(slot_summary.total_capacity, 0)
            - coalesce(slot_summary.total_quantity, 0)
            - coalesce(slot_summary.pending_quantity, 0),
            0
          ),
          'used_capacity_ratio', case
            when coalesce(slot_summary.total_capacity, 0) > 0 then
              round(
                (
                  coalesce(slot_summary.total_quantity, 0)
                  + coalesce(slot_summary.pending_quantity, 0)
                )::numeric / slot_summary.total_capacity::numeric,
                4
              )
            else 0
          end,
          'pending_sale_total', coalesce(slot_summary.pending_sale_total, 0),
          'total_stock_cost_value', coalesce(slot_summary.total_stock_cost_value, 0),
          'total_stock_sale_value', coalesce(slot_summary.total_stock_sale_value, 0)
        ),
        'slots', coalesce(slot_summary.slots, '[]'::jsonb),
        'is_under_construction', false
      ) as payload
    from public.stores s
    join public.cities c on c.id = s.city_id
    join public.store_types st on st.id = s.store_type_id
    left join lateral (
      select
        coalesce(sum(ss.quantity), 0) as total_quantity,
        coalesce(sum(ss.capacity), 0) as total_capacity,
        coalesce(sum(ss.pending_quantity), 0) as pending_quantity,
        coalesce(sum(ss.pending_sale), 0) as pending_sale_total,
        coalesce(sum(ss.quantity * ss.cost), 0) as total_stock_cost_value,
        coalesce(sum(ss.quantity * ss.price), 0) as total_stock_sale_value,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'slot_id', ss.id,
              'id', ss.id,
              'store_id', ss.store_id,
              'slot_index', ss.slot_index,
              'brand_id', ss.brand_id,
              'product_id', ss.product_id,
              'product_name', p.urun_adi,
              'product_icon', p.urun_iconu,
              'quality_level', ss.quality_level,
              'quantity', ss.quantity,
              'capacity', ss.capacity,
              'pending_quantity', ss.pending_quantity,
              'price', ss.price,
              'cost', ss.cost,
              'pending_sale', ss.pending_sale,
              'is_active', ss.is_active,
              'is_empty', case
                when ss.product_id is null or ss.quality_level = 0 then true
                else false
              end,
              'used_capacity_ratio', case
                when ss.capacity > 0 then
                  round((ss.quantity + ss.pending_quantity)::numeric / ss.capacity::numeric, 4)
                else 0
              end
            )
            order by ss.slot_index asc
          ),
          '[]'::jsonb
        ) as slots
      from public.store_slots ss
      left join public.products p on p.id = ss.product_id
      where ss.store_id = s.id
    ) slot_summary on true
    where s.player_id = auth.uid()
  ),
  construction_rows as (
    select
      bc.id,
      bc.started_at as sort_time,
      coalesce(nullif(bc.params ->> 'name', ''), st.name, 'Magaza') as sort_name,
      true as is_under_construction,
      false as is_active,
      coalesce((bc.params ->> 'slot_capacity')::integer, 0) as total_capacity,
      jsonb_build_object(
        'id', bc.id,
        'name', coalesce(nullif(bc.params ->> 'name', ''), st.name, 'Magaza'),
        'city_id', bc.params ->> 'city_id',
        'city_name', c.name,
        'level', coalesce((bc.params ->> 'level')::integer, 1),
        'is_active', false,
        'current_slot_count', coalesce((bc.params ->> 'current_slot_count')::integer, 0),
        'max_slot_count', coalesce((bc.params ->> 'max_slot_count')::integer, 0),
        'slot_capacity', coalesce((bc.params ->> 'slot_capacity')::integer, 0),
        'store_type', jsonb_build_object(
          'id', st.id,
          'name', st.name,
          'icon', st.icon,
          'cost', st.cost,
          'required_level', st.required_level,
          'construction_time_minutes', st.construction_time_minutes
        ),
        'summary', jsonb_build_object(
          'total_quantity', 0,
          'total_capacity', coalesce((bc.params ->> 'slot_capacity')::integer, 0),
          'pending_quantity', 0,
          'available_capacity', coalesce((bc.params ->> 'slot_capacity')::integer, 0),
          'used_capacity_ratio', 0
        ),
        'slots', '[]'::jsonb,
        'is_under_construction', true,
        'started_at', bc.started_at,
        'finish_at', bc.finish_at,
        'construction_progress', case
          when bc.finish_at <= bc.started_at then 0
          else least(
            greatest(
              extract(epoch from (timezone('utc', now()) - bc.started_at))
              / nullif(extract(epoch from (bc.finish_at - bc.started_at)), 0),
              0
            ),
            1
          )
        end
      ) as payload
    from public.building_constructions bc
    left join public.store_types st
      on st.id = nullif(bc.params ->> 'store_type_id', '')::uuid
    left join public.cities c
      on c.id = nullif(bc.params ->> 'city_id', '')::uuid
    where bc.player_id = auth.uid()
      and bc.building_kind = 'store'
      and bc.status = 'in_progress'
  ),
  combined as (
    select * from live_rows
    union all
    select * from construction_rows
  )
  select jsonb_build_object(
    'success', true,
    'stores', coalesce(
      (
        select jsonb_agg(payload order by sort_time asc, sort_name asc)
        from combined
      ),
      '[]'::jsonb
    ),
    'summary', jsonb_build_object(
      'total_count', coalesce((select count(*) from combined), 0),
      'active_count', coalesce((select count(*) from live_rows where is_active is true), 0),
      'construction_count', coalesce((select count(*) from construction_rows), 0),
      'total_capacity', coalesce((select sum(total_capacity) from live_rows), 0)
    )
  );
$function$;

-- Function: get_store_types_catalog
CREATE OR REPLACE FUNCTION public.get_store_types_catalog()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(st) order by st.required_level, st.cost),
    '[]'::jsonb
  )
  from public.store_types st;
$function$;

-- Function: get_tender_center
CREATE OR REPLACE FUNCTION public.get_tender_center()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_open_tenders jsonb := '[]'::jsonb;
  v_my_active_tenders jsonb := '[]'::jsonb;
  v_my_bid_tenders jsonb := '[]'::jsonb;
  v_my_recent_tenders jsonb := '[]'::jsonb;
  v_delivery_count integer := 0;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum acilmamis.');
  end if;

  perform public.ensure_open_tenders();
  perform public.process_tender_deliveries(v_player_id);
  perform public.process_player_tenders(v_player_id);

  with bid_stats as (
    select
      tb.tender_id,
      count(*)::integer as bid_count,
      min(tb.bid_amount) as lowest_bid_amount
    from public.tender_bids tb
    where tb.status = 'active'
    group by tb.tender_id
  ),
  player_bid as (
    select
      tb.tender_id,
      tb.bid_amount
    from public.tender_bids tb
    where tb.player_id = v_player_id
      and tb.status = 'active'
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'tender_id', t.id,
        'title', t.title,
        'city_id', t.city_id,
        'city_name', c.name,
        'product_id', t.product_id,
        'product_name', p.urun_adi,
        'product_icon', p.urun_iconu,
        'quality_level', t.quality_level,
        'required_quantity', t.required_quantity,
        'reward_cash', t.reward_cash,
        'bond_amount', t.bond_amount,
        'award_type', t.award_type,
        'bid_count',
          case
            when t.award_type = 'lowest_bid' then coalesce(bs.bid_count, 0)
            else 0
          end,
        'lowest_bid_amount',
          case
            when t.award_type = 'lowest_bid' then bs.lowest_bid_amount
            else null
          end,
        'has_player_bid',
          case
            when t.award_type = 'lowest_bid' then pb.tender_id is not null
            else false
          end,
        'player_bid_amount',
          case
            when t.award_type = 'lowest_bid' then pb.bid_amount
            else null
          end,
        'accept_until', t.accept_until,
        'delivery_duration_minutes', t.delivery_duration_minutes,
        'status', t.status,
        'min_player_level', t.min_player_level
      )
      order by t.accept_until asc
    ),
    '[]'::jsonb
  )
  into v_open_tenders
  from public.tenders t
  join public.cities c on c.id = t.city_id
  join public.products p on p.id = t.product_id
  join public.players pl on pl.id = v_player_id
  left join bid_stats bs on bs.tender_id = t.id
  left join player_bid pb on pb.tender_id = t.id
  where t.status = 'open'
    and t.accept_until > timezone('utc'::text, now())
    and coalesce(pl.level, 1) >= t.min_player_level;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'player_tender_id', pt.id,
        'tender_id', pt.tender_id,
        'title', t.title,
        'city_name', c.name,
        'product_id', pt.product_id,
        'product_name', p.urun_adi,
        'product_icon', p.urun_iconu,
        'quality_level', pt.quality_level,
        'required_quantity', pt.required_quantity,
        'delivered_quantity', pt.delivered_quantity,
        'remaining_quantity', greatest(pt.required_quantity - pt.delivered_quantity, 0),
        'reward_cash', pt.reward_cash,
        'bond_paid', pt.bond_paid,
        'deadline_at', pt.deadline_at,
        'completed_at', pt.completed_at,
        'failed_at', pt.failed_at,
        'status', pt.status
      )
      order by pt.deadline_at asc
    ),
    '[]'::jsonb
  )
  into v_my_active_tenders
  from public.player_tenders pt
  join public.tenders t on t.id = pt.tender_id
  join public.cities c on c.id = pt.city_id
  join public.products p on p.id = pt.product_id
  where pt.player_id = v_player_id
    and pt.status = 'active';

  with bid_stats as (
    select
      tb.tender_id,
      count(*)::integer as bid_count,
      min(tb.bid_amount) as lowest_bid_amount
    from public.tender_bids tb
    where tb.status = 'active'
    group by tb.tender_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'tender_id', t.id,
        'title', t.title,
        'city_name', c.name,
        'product_name', p.urun_adi,
        'product_icon', p.urun_iconu,
        'quality_level', t.quality_level,
        'award_type', t.award_type,
        'bid_amount', tb.bid_amount,
        'bond_paid', tb.bond_paid,
        'bid_count', coalesce(bs.bid_count, 0),
        'lowest_bid_amount', bs.lowest_bid_amount,
        'accept_until', t.accept_until,
        'status', tb.status
      )
      order by t.accept_until asc
    ),
    '[]'::jsonb
  )
  into v_my_bid_tenders
  from public.tender_bids tb
  join public.tenders t on t.id = tb.tender_id
  join public.cities c on c.id = t.city_id
  join public.products p on p.id = t.product_id
  left join bid_stats bs on bs.tender_id = t.id
  where tb.player_id = v_player_id
    and tb.status = 'active'
    and t.status = 'open'
    and t.accept_until > timezone('utc'::text, now());

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'player_tender_id', pt.id,
        'tender_id', pt.tender_id,
        'title', t.title,
        'city_name', c.name,
        'product_id', pt.product_id,
        'product_name', p.urun_adi,
        'product_icon', p.urun_iconu,
        'quality_level', pt.quality_level,
        'required_quantity', pt.required_quantity,
        'delivered_quantity', pt.delivered_quantity,
        'remaining_quantity', greatest(pt.required_quantity - pt.delivered_quantity, 0),
        'reward_cash', pt.reward_cash,
        'bond_paid', pt.bond_paid,
        'deadline_at', pt.deadline_at,
        'completed_at', pt.completed_at,
        'failed_at', pt.failed_at,
        'status', pt.status
      )
      order by coalesce(pt.completed_at, pt.failed_at, pt.updated_at) desc
    ),
    '[]'::jsonb
  )
  into v_my_recent_tenders
  from (
    select *
    from public.player_tenders
    where player_id = v_player_id
      and status in ('completed', 'failed', 'cancelled')
    order by coalesce(completed_at, failed_at, updated_at) desc
    limit 10
  ) pt
  join public.tenders t on t.id = pt.tender_id
  join public.cities c on c.id = pt.city_id
  join public.products p on p.id = pt.product_id;

  select count(*) into v_delivery_count
  from public.tender_deliveries td
  where td.player_id = v_player_id and td.status = 'in_transit';

  return jsonb_build_object(
    'success', true,
    'open_tenders', v_open_tenders,
    'my_active_tenders', v_my_active_tenders,
    'my_bid_tenders', v_my_bid_tenders,
    'my_recent_tenders', v_my_recent_tenders,
    'delivery_count', v_delivery_count,
    'server_time', timezone('utc'::text, now())
  );
end;
$function$;

-- Function: get_tender_detail
CREATE OR REPLACE FUNCTION public.get_tender_detail(p_tender_id uuid DEFAULT NULL::uuid, p_player_tender_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
  v_tender public.tenders%rowtype;
  v_player_tender public.player_tenders%rowtype;
  v_player_bid public.tender_bids%rowtype;
  v_has_tender boolean := false;
  v_warehouse_options jsonb := '[]'::jsonb;
  v_active_deliveries jsonb := '[]'::jsonb;
  v_city_name text;
  v_product_name text;
  v_product_icon text;
  v_product_unit_volume numeric := 0;
  v_product_base_price numeric := 0;
  v_in_transit_quantity integer := 0;
begin
  if v_player_id is null then
    return jsonb_build_object('success', false, 'message', 'Oturum bulunamadi.');
  end if;

  if p_player_tender_id is null and p_tender_id is null then
    return jsonb_build_object('success', false, 'message', 'Ihale secilmedi.');
  end if;

  if p_player_tender_id is not null then
    select pt.* into v_player_tender
    from public.player_tenders pt
    where pt.id = p_player_tender_id and pt.player_id = v_player_id;

    if not found then
      return jsonb_build_object('success', false, 'message', 'Oyuncu ihalesi bulunamadi.');
    end if;

    select coalesce(sum(td.quantity), 0)::integer
    into v_in_transit_quantity
    from public.tender_deliveries td
    where td.player_tender_id = v_player_tender.id and td.status = 'in_transit';

    select t.* into v_tender from public.tenders t where t.id = v_player_tender.tender_id;
    if not found then
      return jsonb_build_object('success', false, 'message', 'Ihale bulunamadi.');
    end if;
  else
    select t.* into v_tender
    from public.tenders t
    where t.id = p_tender_id
      and t.status = 'open'
      and t.accept_until > timezone('utc'::text, now());

    v_has_tender := found;

    if v_has_tender and v_tender.award_type = 'lowest_bid' then
      select tb.* into v_player_bid
      from public.tender_bids tb
      where tb.tender_id = v_tender.id and tb.player_id = v_player_id;
    end if;
  end if;

  if p_player_tender_id is null and not v_has_tender then
    return jsonb_build_object('success', false, 'message', 'Ihale bulunamadi.');
  end if;

  select c.name into v_city_name from public.cities c where c.id = v_tender.city_id;
  select p.urun_adi, p.urun_iconu, coalesce(p.birim_hacim, 0), coalesce(p.baz_satis_fiyati, 0)
  into v_product_name, v_product_icon, v_product_unit_volume, v_product_base_price
  from public.products p
  where p.id = v_tender.product_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'warehouse_id', w.id,
        'warehouse_name', w.name,
        'city_id', w.city_id,
        'city_name', c.name,
        'available_quantity', inv.available_quantity,
        'unit_cost', coalesce(inv.avg_cost, 0),
        'same_city', (w.city_id = coalesce(v_player_tender.city_id, v_tender.city_id)),
        'distance_km',
          case
            when w.city_id = coalesce(v_player_tender.city_id, v_tender.city_id) then 0
            else round(
              (
                6371 * 2 * asin(
                  sqrt(
                    power(
                      sin(radians(coalesce(tc.map_position_x, 0) - coalesce(sc.map_position_x, 0)) / 2),
                      2
                    ) +
                    cos(radians(coalesce(sc.map_position_x, 0))) *
                    cos(radians(coalesce(tc.map_position_x, 0))) *
                    power(
                      sin(radians(coalesce(tc.map_position_y, 0) - coalesce(sc.map_position_y, 0)) / 2),
                      2
                    )
                  )
                )
              )::numeric,
              2
            )
          end,
        'estimated_duration_minutes',
          case
            when w.city_id = coalesce(v_player_tender.city_id, v_tender.city_id) then 5
            else null
          end,
        'can_deliver_before_deadline',
          case
            when p_player_tender_id is null then null
            when w.city_id <> v_player_tender.city_id then null
            else
              v_player_tender.deadline_at >= timezone('utc'::text, now()) +
                make_interval(
                  mins =>
                    case
                      when w.city_id = v_player_tender.city_id then 5
                      else greatest(
                        10,
                        ceil(
                          (
                            6371 * 2 * asin(
                              sqrt(
                                power(
                                  sin(radians(coalesce(tc.map_position_x, 0) - coalesce(sc.map_position_x, 0)) / 2),
                                  2
                                ) +
                                cos(radians(coalesce(sc.map_position_x, 0))) *
                                cos(radians(coalesce(tc.map_position_x, 0))) *
                                power(
                                  sin(radians(coalesce(tc.map_position_y, 0) - coalesce(sc.map_position_y, 0)) / 2),
                                  2
                                )
                              )
                            )
                          ) / 80.0 * 12.0
                        )
                      )::integer
                    end
                )
          end,
        'recommended',
          case
            when p_player_tender_id is null then (w.city_id = v_tender.city_id)
            when w.city_id = v_player_tender.city_id then true
            when
              (
                v_player_tender.deadline_at >= timezone('utc'::text, now()) +
                  make_interval(
                    mins =>
                      case
                        when w.city_id = v_player_tender.city_id then 5
                        else greatest(
                          10,
                          ceil(
                            (
                              6371 * 2 * asin(
                                sqrt(
                                  power(
                                    sin(radians(coalesce(tc.map_position_x, 0) - coalesce(sc.map_position_x, 0)) / 2),
                                    2
                                  ) +
                                  cos(radians(coalesce(sc.map_position_x, 0))) *
                                  cos(radians(coalesce(tc.map_position_x, 0))) *
                                  power(
                                    sin(radians(coalesce(tc.map_position_y, 0) - coalesce(sc.map_position_y, 0)) / 2),
                                    2
                                  )
                                )
                              )
                            ) / 80.0 * 12.0
                          )
                        )::integer
                      end
                  )
              )
              then true
            else false
          end
      )
      order by
        case
          when p_player_tender_id is null then case when w.city_id = v_tender.city_id then 0 else 1 end
          when w.city_id = v_player_tender.city_id then 0
          when
            v_player_tender.deadline_at >= timezone('utc'::text, now()) +
              make_interval(
                mins =>
                  case
                    when w.city_id = v_player_tender.city_id then 5
                    else greatest(
                      10,
                      ceil(
                        (
                          6371 * 2 * asin(
                            sqrt(
                              power(
                                sin(radians(coalesce(tc.map_position_x, 0) - coalesce(sc.map_position_x, 0)) / 2),
                                2
                              ) +
                              cos(radians(coalesce(sc.map_position_x, 0))) *
                              cos(radians(coalesce(tc.map_position_x, 0))) *
                              power(
                                sin(radians(coalesce(tc.map_position_y, 0) - coalesce(sc.map_position_y, 0)) / 2),
                                2
                              )
                            )
                          )
                        ) / 80.0 * 12.0
                      )
                    )::integer
                  end
              ) then 1
          else 2
        end,
        inv.available_quantity desc,
        w.name asc
    ),
    '[]'::jsonb
  )
  into v_warehouse_options
  from public.warehouses w
  join public.cities c on c.id = w.city_id
  join public.cities sc on sc.id = w.city_id
  join public.cities tc on tc.id = coalesce(v_player_tender.city_id, v_tender.city_id)
  join (
    select
      ws.warehouse_id,
      sum(greatest(coalesce(ws.quantity, 0), 0))::integer as available_quantity,
      coalesce(
        sum(coalesce(ws.cost, 0) * greatest(coalesce(ws.quantity, 0), 0))::numeric / 
        nullif(sum(greatest(coalesce(ws.quantity, 0), 0)), 0),
        0
      )::numeric as avg_cost
    from public.warehouse_slots ws
    where ws.product_id = coalesce(v_player_tender.product_id, v_tender.product_id)
      and ws.quality_level >= coalesce(v_player_tender.quality_level, v_tender.quality_level)
      and coalesce(ws.quantity, 0) > 0
    group by ws.warehouse_id
  ) inv on inv.warehouse_id = w.id
  where w.player_id = v_player_id and w.is_active = true;

  if p_player_tender_id is not null then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', td.id,
          'source_warehouse_id', td.source_warehouse_id,
          'source_warehouse_name', w.name,
          'source_city_name', c.name,
          'quantity', td.quantity,
          'status', td.status,
          'same_city', td.same_city,
          'started_at', td.started_at,
          'finish_at', td.finish_at
        )
        order by td.finish_at asc nulls last, td.created_at asc
      ),
      '[]'::jsonb
    )
    into v_active_deliveries
    from public.tender_deliveries td
    join public.warehouses w on w.id = td.source_warehouse_id
    join public.cities c on c.id = w.city_id
    where td.player_tender_id = v_player_tender.id and td.status = 'in_transit';
  end if;

  return jsonb_build_object(
    'success', true,
    'tender', jsonb_build_object(
      'id', v_tender.id,
      'title', v_tender.title,
      'description', v_tender.description,
      'city_id', v_tender.city_id,
      'city_name', coalesce(v_city_name, '-'),
      'product_id', v_tender.product_id,
      'product_name', coalesce(v_product_name, '-'),
      'product_icon', coalesce(v_product_icon, 'default.webp'),
      'product_unit_volume', coalesce(v_product_unit_volume, 0),
      'product_base_price', coalesce(v_product_base_price, 0),
      'quality_level', v_tender.quality_level,
      'required_quantity', v_tender.required_quantity,
      'reward_cash', v_tender.reward_cash,
      'bond_amount', v_tender.bond_amount,
      'award_type', coalesce(v_tender.award_type, 'lowest_bid'),
      'accept_until', v_tender.accept_until,
      'delivery_duration_minutes', v_tender.delivery_duration_minutes,
      'status', v_tender.status
    ),
    'player_tender', case
      when p_player_tender_id is null then null
      else jsonb_build_object(
        'id', v_player_tender.id,
        'accepted_at', v_player_tender.accepted_at,
        'deadline_at', v_player_tender.deadline_at,
        'required_quantity', v_player_tender.required_quantity,
        'delivered_quantity', v_player_tender.delivered_quantity,
        'in_transit_quantity', v_in_transit_quantity,
        'remaining_quantity', greatest(v_player_tender.required_quantity - v_player_tender.delivered_quantity - v_in_transit_quantity, 0),
        'status', v_player_tender.status
      )
    end,
    'player_bid', case
      when p_player_tender_id is not null or v_player_bid.id is null then null
      else jsonb_build_object(
        'id', v_player_bid.id,
        'bid_amount', v_player_bid.bid_amount,
        'bond_paid', v_player_bid.bond_paid,
        'status', v_player_bid.status,
        'submitted_at', v_player_bid.submitted_at,
        'updated_at', v_player_bid.updated_at
      )
    end,
    'warehouse_options', v_warehouse_options,
    'active_deliveries', v_active_deliveries
  );
end;
$function$;

-- Function: get_unread_notification_count
CREATE OR REPLACE FUNCTION public.get_unread_notification_count()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT count(*)::integer
  FROM public.player_notifications
  WHERE player_id = auth.uid()
    AND is_read = false;
$function$;

-- Function: get_warehouse_capacity_status
CREATE OR REPLACE FUNCTION public.get_warehouse_capacity_status(p_warehouse_id uuid)
 RETURNS TABLE(warehouse_id uuid, total_capacity numeric, used_capacity numeric, reserved_capacity numeric, available_capacity numeric)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with target_warehouse as (
    select w.id, w.capacity::numeric as total_capacity, w.reserved_capacity::numeric as reserved_capacity
    from public.warehouses w
    where w.id = p_warehouse_id
      and w.player_id = auth.uid()
  ),
  used_space as (
    select
      ws.warehouse_id,
      coalesce(sum(ws.quantity::numeric * coalesce(p.birim_hacim, 0)), 0) as used_capacity
    from public.warehouse_slots ws
    join public.products p on p.id = ws.product_id
    where ws.warehouse_id = p_warehouse_id
    group by ws.warehouse_id
  )
  select
    tw.id as warehouse_id,
    tw.total_capacity,
    coalesce(us.used_capacity, 0) as used_capacity,
    tw.reserved_capacity,
    greatest(tw.total_capacity - coalesce(us.used_capacity, 0) - tw.reserved_capacity, 0) as available_capacity
  from target_warehouse tw
  left join used_space us on us.warehouse_id = tw.id;
$function$;

-- Function: get_warehouse_history_items
CREATE OR REPLACE FUNCTION public.get_warehouse_history_items(p_warehouse_id uuid)
 RETURNS TABLE(id uuid, direction text, transfer_type text, status text, happened_at timestamp with time zone, started_at timestamp with time zone, finish_at timestamp with time zone, completed_at timestamp with time zone, product_id text, product_name text, product_icon text, quality_level integer, brand_id uuid, quantity integer, total_price numeric, transport_cost numeric, rental_cost numeric, is_rental boolean, source_name text, source_kind text, source_city_name text, target_name text, target_kind text, target_city_name text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid := auth.uid();
begin
  if v_player_id is null then
    raise exception 'Oturum bulunamadi.';
  end if;

  if not exists (
    select 1
    from public.warehouses w
    where w.id = p_warehouse_id
      and w.player_id = v_player_id
  ) then
    raise exception 'Depo bulunamadi veya size ait degil.';
  end if;

  return query
  with transfer_rows as (
    select
      lt.*,
      case
        when lt.buyer_warehouse_id = p_warehouse_id then 'incoming'
        else 'outgoing'
      end as movement_direction,
      coalesce(lt.completed_at, lt.finish_at, lt.started_at) as movement_at
    from public.logistics_transfers lt
    where lt.seller_warehouse_id = p_warehouse_id
       or lt.buyer_warehouse_id = p_warehouse_id
  )
  select
    tr.id,
    tr.movement_direction::text as direction,
    coalesce(tr.transfer_type, 'warehouse_transfer')::text as transfer_type,
    coalesce(tr.status, 'completed')::text as status,
    tr.movement_at as happened_at,
    tr.started_at,
    tr.finish_at,
    tr.completed_at,
    tr.product_id,
    coalesce(p.urun_adi, 'Urun')::text as product_name,
    coalesce(p.urun_iconu, 'default.webp')::text as product_icon,
    greatest(coalesce(tr.quality_level, 1), 1)::integer as quality_level,
    coalesce(
      tr.brand_id,
      '00000000-0000-0000-0000-000000000000'::uuid
    ) as brand_id,
    coalesce(tr.quantity, 0)::integer as quantity,
    coalesce(tr.total_price, 0) as total_price,
    coalesce(tr.transport_cost, 0) as transport_cost,
    coalesce(tr.rental_cost, 0) as rental_cost,
    (
      coalesce(tr.is_rental, false)
      or coalesce(tr.rental_cost, 0) > 0
    ) as is_rental,
    case
      when tr.seller_entity_kind = 'npc_market' then 'Pazar'
      when tr.seller_entity_kind in ('store', 'store_slot') then coalesce(ss.name, 'Magaza')
      when tr.seller_entity_kind in ('production', 'production_inventory') then
        coalesce(sf.name, sfd.name, sfa.name, sm.name, 'Uretim')
      else coalesce(sw.name, 'Depo')
    end::text as source_name,
    case
      when tr.seller_entity_kind = 'npc_market' then 'market'
      when tr.seller_entity_kind in ('store', 'store_slot') then 'store'
      when tr.seller_entity_kind in ('production', 'production_inventory') then 'production'
      else 'warehouse'
    end::text as source_kind,
    case
      when tr.seller_entity_kind = 'npc_market' then coalesce(bwc.name, swc.name, ssc.name, sfc.name, sfdc.name, sfac.name, smc.name, '-')
      when tr.seller_entity_kind in ('store', 'store_slot') then coalesce(ssc.name, '-')
      when tr.seller_entity_kind in ('production', 'production_inventory') then
        coalesce(sfc.name, sfdc.name, sfac.name, smc.name, '-')
      else coalesce(swc.name, '-')
    end::text as source_city_name,
    case
      when tr.buyer_entity_kind = 'npc_market' then 'Pazar'
      when tr.buyer_entity_kind in ('store', 'store_slot') then coalesce(bs.name, 'Magaza')
      when tr.buyer_entity_kind in ('production', 'production_inventory') then
        coalesce(bf.name, bfd.name, bfa.name, bm.name, 'Uretim')
      else coalesce(bw.name, 'Depo')
    end::text as target_name,
    case
      when tr.buyer_entity_kind = 'npc_market' then 'market'
      when tr.buyer_entity_kind in ('store', 'store_slot') then 'store'
      when tr.buyer_entity_kind in ('production', 'production_inventory') then 'production'
      else 'warehouse'
    end::text as target_kind,
    case
      when tr.buyer_entity_kind = 'npc_market' then coalesce(swc.name, bwc.name, bsc.name, bfc.name, bfdc.name, bfac.name, bmc.name, '-')
      when tr.buyer_entity_kind in ('store', 'store_slot') then coalesce(bsc.name, '-')
      when tr.buyer_entity_kind in ('production', 'production_inventory') then
        coalesce(bfc.name, bfdc.name, bfac.name, bmc.name, '-')
      else coalesce(bwc.name, '-')
    end::text as target_city_name
  from transfer_rows tr
  left join public.products p on p.id = tr.product_id
  left join public.warehouses sw on sw.id = tr.seller_warehouse_id
  left join public.cities swc on swc.id = sw.city_id
  left join public.warehouses bw on bw.id = tr.buyer_warehouse_id
  left join public.cities bwc on bwc.id = bw.city_id
  left join public.stores ss on ss.id = tr.seller_store_id
  left join public.cities ssc on ssc.id = ss.city_id
  left join public.stores bs on bs.id = tr.buyer_store_id
  left join public.cities bsc on bsc.id = bs.city_id
  left join public.production_inventory spi on spi.id = tr.seller_production_inventory_id
  left join public.factories sf on sf.id = spi.owner_id and spi.owner_kind = 'factory'
  left join public.cities sfc on sfc.id = sf.city_id
  left join public.fields sfd on sfd.id = spi.owner_id and spi.owner_kind = 'field'
  left join public.cities sfdc on sfdc.id = sfd.city_id
  left join public.farms sfa on sfa.id = spi.owner_id and spi.owner_kind = 'farm'
  left join public.cities sfac on sfac.id = sfa.city_id
  left join public.mines sm on sm.id = spi.owner_id and spi.owner_kind = 'mine'
  left join public.cities smc on smc.id = sm.city_id
  left join public.production_inventory bpi on bpi.id = tr.buyer_production_inventory_id
  left join public.factories bf on bf.id = bpi.owner_id and bpi.owner_kind = 'factory'
  left join public.cities bfc on bfc.id = bf.city_id
  left join public.fields bfd on bfd.id = bpi.owner_id and bpi.owner_kind = 'field'
  left join public.cities bfdc on bfdc.id = bfd.city_id
  left join public.farms bfa on bfa.id = bpi.owner_id and bpi.owner_kind = 'farm'
  left join public.cities bfac on bfac.id = bfa.city_id
  left join public.mines bm on bm.id = bpi.owner_id and bpi.owner_kind = 'mine'
  left join public.cities bmc on bmc.id = bm.city_id
  order by tr.movement_at desc, tr.started_at desc;
end;
$function$;

-- Function: get_warehouse_list_page_data
CREATE OR REPLACE FUNCTION public.get_warehouse_list_page_data()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with live_rows as (
    select
      w.id,
      w.created_at as sort_time,
      w.name as sort_name,
      false as is_under_construction,
      w.is_active,
      coalesce(w.capacity, 0) as total_capacity,
      jsonb_build_object(
        'id', w.id,
        'player_id', w.player_id,
        'warehouse_type_id', w.warehouse_type_id,
        'city_id', w.city_id,
        'name', w.name,
        'level', w.level,
        'capacity', w.capacity,
        'reserved_capacity', w.reserved_capacity,
        'is_active', w.is_active,
        'created_at', w.created_at,
        'updated_at', w.updated_at,
        'warehouse_kind', w.warehouse_kind,
        'store_id', w.store_id,
        'city', jsonb_build_object('name', c.name),
        'warehouse_type', jsonb_build_object(
          'id', wt.id,
          'name', wt.name,
          'icon', wt.icon,
          'base_capacity', wt.base_capacity,
          'cost', wt.cost,
          'required_level', wt.required_level,
          'construction_time_minutes', wt.construction_time_minutes,
          'accepted_product_ids', wt.accepted_product_ids
        ),
        'warehouse_slots', coalesce(slot_rows.slots, '[]'::jsonb),
        'is_under_construction', false
      ) as payload
    from public.warehouses w
    join public.cities c on c.id = w.city_id
    left join public.warehouse_types wt on wt.id = w.warehouse_type_id
    left join lateral (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', ws.id,
            'product_id', ws.product_id,
            'product_name', p.urun_adi,
            'quantity', ws.quantity,
            'quality_level', ws.quality_level,
            'brand_id', ws.brand_id,
            'price', ws.price,
            'cost', ws.cost,
            'is_available_for_sale', ws.is_available_for_sale,
            'product', case
              when p.id is null then null
              else jsonb_build_object(
                'id', p.id,
                'urun_adi', p.urun_adi,
                'urun_iconu', p.urun_iconu,
                'birim_hacim', p.birim_hacim
              )
            end
          )
          order by ws.created_at
        ),
        '[]'::jsonb
      ) as slots
      from public.warehouse_slots ws
      left join public.products p on p.id = ws.product_id
      where ws.warehouse_id = w.id
    ) slot_rows on true
    where w.player_id = auth.uid()
  ),
  construction_rows as (
    select
      bc.id,
      bc.started_at as sort_time,
      coalesce(nullif(bc.params ->> 'name', ''), wt.name, 'Depo') as sort_name,
      true as is_under_construction,
      false as is_active,
      coalesce((bc.params ->> 'capacity')::numeric, 0) as total_capacity,
      jsonb_build_object(
        'id', bc.id,
        'player_id', bc.player_id,
        'warehouse_type_id', bc.params ->> 'warehouse_type_id',
        'city_id', bc.params ->> 'city_id',
        'name', coalesce(nullif(bc.params ->> 'name', ''), wt.name, 'Depo'),
        'level', coalesce((bc.params ->> 'level')::integer, 1),
        'capacity', coalesce((bc.params ->> 'capacity')::numeric, 0),
        'reserved_capacity', coalesce((bc.params ->> 'reserved_capacity')::numeric, 0),
        'is_active', false,
        'created_at', bc.started_at,
        'updated_at', bc.started_at,
        'warehouse_kind', coalesce(bc.params ->> 'warehouse_kind', 'normal'),
        'store_id', bc.params ->> 'store_id',
        'city', jsonb_build_object('name', c.name),
        'warehouse_type', jsonb_build_object(
          'id', wt.id,
          'name', wt.name,
          'icon', wt.icon,
          'base_capacity', wt.base_capacity,
          'cost', wt.cost,
          'required_level', wt.required_level,
          'construction_time_minutes', wt.construction_time_minutes,
          'accepted_product_ids', wt.accepted_product_ids
        ),
        'warehouse_slots', '[]'::jsonb,
        'is_under_construction', true,
        'finish_at', bc.finish_at
      ) as payload
    from public.building_constructions bc
    left join public.warehouse_types wt
      on wt.id = nullif(bc.params ->> 'warehouse_type_id', '')::uuid
    left join public.cities c
      on c.id = nullif(bc.params ->> 'city_id', '')::uuid
    where bc.player_id = auth.uid()
      and bc.building_kind = 'warehouse'
      and bc.status = 'in_progress'
  ),
  combined as (
    select * from live_rows
    union all
    select * from construction_rows
  )
  select jsonb_build_object(
    'success', true,
    'warehouses', coalesce(
      (
        select jsonb_agg(payload order by sort_time asc, sort_name asc)
        from combined
      ),
      '[]'::jsonb
    ),
    'summary', jsonb_build_object(
      'total_count', coalesce((select count(*) from combined), 0),
      'active_count', coalesce((select count(*) from live_rows where is_active is true), 0),
      'construction_count', coalesce((select count(*) from construction_rows), 0),
      'total_capacity', coalesce((select sum(total_capacity) from live_rows), 0)
    )
  );
$function$;

