-- Function: grant_player_experience
CREATE OR REPLACE FUNCTION public.grant_player_experience(p_player_id uuid, p_amount integer, p_reason text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player public.players%rowtype;
  v_old_experience integer;
  v_new_experience integer;
  v_old_level integer;
  v_new_level integer;
  v_remaining_amount integer;
  v_required_for_level integer;
  v_progress jsonb;
begin
  if p_player_id is null then
    raise exception 'Gecersiz oyuncu.';
  end if;

  if auth.uid() is not null and auth.uid() <> p_player_id then
    raise exception 'Yetkisiz istek.';
  end if;

  select *
  into v_player
  from public.players
  where id = p_player_id
  for update;

  if not found then
    raise exception 'Oyuncu bulunamadi.';
  end if;

  v_old_experience := greatest(coalesce(v_player.experience, 0), 0);
  v_old_level := greatest(coalesce(v_player.level, 1), 1);
  v_new_experience := v_old_experience;
  v_new_level := v_old_level;

  if coalesce(p_amount, 0) <= 0 then
    v_progress := public.build_level_progress_payload(v_old_level, v_old_experience);

    return jsonb_build_object(
      'success', true,
      'amount', 0,
      'reason', p_reason,
      'old_level', v_old_level,
      'new_level', v_old_level,
      'old_experience', v_old_experience,
      'new_experience', v_old_experience,
      'leveled_up', false,
      'progress', v_progress
    );
  end if;

  v_remaining_amount := p_amount;

  while v_remaining_amount > 0 loop
    v_required_for_level := public.get_experience_required_for_level(v_new_level);

    if v_new_experience + v_remaining_amount < v_required_for_level then
      v_new_experience := v_new_experience + v_remaining_amount;
      v_remaining_amount := 0;
    else
      v_remaining_amount := v_remaining_amount - greatest(v_required_for_level - v_new_experience, 0);
      v_new_level := v_new_level + 1;
      v_new_experience := 0;
    end if;
  end loop;

  update public.players
  set
    experience = v_new_experience,
    level = v_new_level
  where id = p_player_id;

  insert into public.player_experience_logs (
    player_id,
    reason,
    amount,
    old_level,
    new_level,
    old_experience,
    new_experience,
    meta
  )
  values (
    p_player_id,
    p_reason,
    p_amount,
    v_old_level,
    v_new_level,
    v_old_experience,
    v_new_experience,
    coalesce(p_meta, '{}'::jsonb)
  );

  v_progress := public.build_level_progress_payload(v_new_level, v_new_experience);

  return jsonb_build_object(
    'success', true,
    'amount', p_amount,
    'reason', p_reason,
    'old_level', v_old_level,
    'new_level', v_new_level,
    'old_experience', v_old_experience,
    'new_experience', v_new_experience,
    'leveled_up', v_new_level > v_old_level,
    'levels_gained', greatest(v_new_level - v_old_level, 0),
    'progress', v_progress
  );
end;
$function$;

-- Function: handle_arge_research_mission_progress
CREATE OR REPLACE FUNCTION public.handle_arge_research_mission_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE'
     and new.status = 'completed'
     and coalesce(old.status, '') <> 'completed' then
    perform public.increment_player_mission_progress(new.player_id, 'arge_research_completed', 1);
    perform public.increment_player_achievement_progress(new.player_id, 'arge_research_completed', 1);
  end if;

  return new;
end;
$function$;

-- Function: handle_building_construction_mission_progress
CREATE OR REPLACE FUNCTION public.handle_building_construction_mission_progress()
 RETURNS trigger
 LANGUAGE plpgsql
