-- Function: handle_production_mission_progress
CREATE OR REPLACE FUNCTION public.handle_production_mission_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_delta integer := 0;
begin
  if tg_op = 'INSERT' then
    v_delta := coalesce(new.produced_quantity, 0);
  elsif tg_op = 'UPDATE' then
    v_delta := greatest(coalesce(new.produced_quantity, 0) - coalesce(old.produced_quantity, 0), 0);
  end if;

  if v_delta > 0 then
    perform public.increment_player_mission_progress(new.player_id, 'product_produced', v_delta);
    perform public.increment_player_achievement_progress(new.player_id, 'product_produced', v_delta);
  end if;

  return new;
end;
$function$;

