-- Function: increment_player_achievement_progress
CREATE OR REPLACE FUNCTION public.increment_player_achievement_progress(p_player_id uuid, p_event_key text, p_amount integer DEFAULT 1, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
begin
  if p_player_id is null or coalesce(p_event_key, '') = '' or coalesce(p_amount, 0) <= 0 then
    return;
  end if;

  perform public.ensure_player_achievement_rows(p_player_id);

  update public.player_achievements pa
  set
    progress_count = least(ad.target_count, pa.progress_count + p_amount),
    is_unlocked = (pa.progress_count + p_amount) >= ad.target_count,
    unlocked_at = case
      when (pa.progress_count + p_amount) >= ad.target_count and pa.unlocked_at is null then v_now
      else pa.unlocked_at
    end,
    last_progress_at = v_now,
    updated_at = v_now
  from public.achievement_definitions ad
  where pa.player_id = p_player_id
    and pa.achievement_id = ad.id
    and ad.is_active = true
    and ad.event_key = p_event_key
    and pa.is_unlocked = false;
end;
$function$;

-- Function: increment_player_mission_progress
CREATE OR REPLACE FUNCTION public.increment_player_mission_progress(p_player_id uuid, p_event_key text, p_amount integer DEFAULT 1, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamptz := timezone('utc', now());
begin
  if p_player_id is null or coalesce(p_event_key, '') = '' or coalesce(p_amount, 0) <= 0 then
    return;
  end if;

  perform public.ensure_player_mission_rows(p_player_id);
  perform public.reset_player_daily_missions(p_player_id);
  perform public.reset_player_weekly_missions(p_player_id);

  update public.player_missions pm
  set
    progress_count = least(md.target_count, pm.progress_count + p_amount),
    is_completed = (pm.progress_count + p_amount) >= md.target_count,
    completed_at = case
      when (pm.progress_count + p_amount) >= md.target_count and pm.completed_at is null then v_now
      else pm.completed_at
    end,
    last_progress_at = v_now,
    updated_at = v_now
  from public.mission_definitions md
  where pm.player_id = p_player_id
    and pm.mission_id = md.id
    and md.is_active = true
    and md.event_key = p_event_key
    and pm.is_claimed = false
    and pm.is_completed = false
    and (
      md.mission_type <> 'main'
      or md.required_mission_id is null
      or exists (
        select 1
        from public.player_missions req
        where req.player_id = p_player_id
          and req.mission_id = md.required_mission_id
          and req.is_claimed = true
      )
    );
end;
$function$;

-- Function: is_player_tax_blocked
CREATE OR REPLACE FUNCTION public.is_player_tax_blocked(p_player_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tax_debt numeric;
  v_level integer;
  v_limit numeric;
begin
  if p_player_id is null then
    return false;
  end if;

  select coalesce(tax_debt, 0) into v_tax_debt
  from public.player_taxes
  where player_id = p_player_id;

  if v_tax_debt <= 0 then
    return false;
  end if;

  select coalesce(level, 1) into v_level
  from public.players
  where id = p_player_id;

  v_limit := public.get_player_tax_limit(v_level);

  return v_tax_debt > v_limit;
end;
$function$;

-- Function: log_player_cash_change
CREATE OR REPLACE FUNCTION public.log_player_cash_change(p_player_id uuid, p_amount numeric, p_balance_before numeric, p_category text, p_note text DEFAULT NULL::text, p_ref_id uuid DEFAULT NULL::uuid, p_ref_kind text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  INSERT INTO public.player_cash_ledger (
    player_id, amount, balance_before, balance_after,
    category, note, ref_id, ref_kind
  ) VALUES (
    p_player_id, p_amount, p_balance_before, p_balance_before + p_amount,
    p_category, p_note, p_ref_id, p_ref_kind
  );
end;
$function$;

-- Function: logistics_vehicle_matches_route
CREATE OR REPLACE FUNCTION public.logistics_vehicle_matches_route(p_route_city_a_id uuid, p_route_city_b_id uuid, p_from_city_id uuid, p_to_city_id uuid)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select
    p_route_city_a_id is not null
    and p_route_city_b_id is not null
    and (
      (p_route_city_a_id = p_from_city_id and p_route_city_b_id = p_to_city_id)
      or
      (p_route_city_a_id = p_to_city_id and p_route_city_b_id = p_from_city_id)
    );
$function$;

-- Function: maintain_open_tenders
CREATE OR REPLACE FUNCTION public.maintain_open_tenders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expire_result jsonb := '{}'::jsonb;
  v_generation_result jsonb := '{}'::jsonb;
begin
  v_expire_result := public.ensure_open_tenders();
  v_generation_result := public.generate_open_tenders(50, 50);

