DROP TRIGGER IF EXISTS trg_arge_researches_mission_progress ON public.arge_researches;
CREATE TRIGGER trg_arge_researches_mission_progress AFTER UPDATE OF status ON arge_researches FOR EACH ROW EXECUTE FUNCTION handle_arge_research_mission_progress();

DROP TRIGGER IF EXISTS trg_building_constructions_mission_progress ON public.building_constructions;
CREATE TRIGGER trg_building_constructions_mission_progress AFTER UPDATE OF status ON building_constructions FOR EACH ROW EXECUTE FUNCTION handle_building_construction_mission_progress();

DROP TRIGGER IF EXISTS trg_building_upgrades_mission_progress ON public.building_upgrades;
CREATE TRIGGER trg_building_upgrades_mission_progress AFTER UPDATE OF status ON building_upgrades FOR EACH ROW EXECUTE FUNCTION handle_building_upgrade_mission_progress();

DROP TRIGGER IF EXISTS trim_chat_after_insert ON public.chat_messages;
CREATE TRIGGER trim_chat_after_insert AFTER INSERT ON chat_messages FOR EACH STATEMENT EXECUTE FUNCTION trim_chat_messages();

DROP TRIGGER IF EXISTS factories_apply_brand_selection ON public.factories;
CREATE TRIGGER factories_apply_brand_selection BEFORE INSERT OR UPDATE OF product_id ON factories FOR EACH ROW EXECUTE FUNCTION apply_production_brand_selection();

DROP TRIGGER IF EXISTS trg_logistics_transfers_mission_progress ON public.logistics_transfers;
CREATE TRIGGER trg_logistics_transfers_mission_progress AFTER UPDATE ON logistics_transfers FOR EACH ROW EXECUTE FUNCTION handle_logistics_transfer_mission_progress();

DROP TRIGGER IF EXISTS mines_apply_brand_selection ON public.mines;
CREATE TRIGGER mines_apply_brand_selection BEFORE INSERT OR UPDATE OF product_id ON mines FOR EACH ROW EXECUTE FUNCTION apply_production_brand_selection();

DROP TRIGGER IF EXISTS trg_player_daily_production_stats_mission_progress ON public.player_daily_production_stats;
CREATE TRIGGER trg_player_daily_production_stats_mission_progress AFTER INSERT OR UPDATE ON player_daily_production_stats FOR EACH ROW EXECUTE FUNCTION handle_production_mission_progress();

DROP TRIGGER IF EXISTS production_inventory_apply_brand ON public.production_inventory;
CREATE TRIGGER production_inventory_apply_brand BEFORE INSERT OR UPDATE OF owner_kind, owner_id, inventory_type, product_id, quality_level ON production_inventory FOR EACH ROW EXECUTE FUNCTION apply_production_inventory_brand();

DROP TRIGGER IF EXISTS production_slots_apply_brand_selection ON public.production_slots;
CREATE TRIGGER production_slots_apply_brand_selection BEFORE INSERT OR UPDATE OF product_id ON production_slots FOR EACH ROW EXECUTE FUNCTION apply_production_brand_selection();

DROP TRIGGER IF EXISTS trg_store_daily_performance_mission_progress ON public.store_daily_performance;
CREATE TRIGGER trg_store_daily_performance_mission_progress AFTER INSERT OR UPDATE OF sold_quantity ON store_daily_performance FOR EACH ROW EXECUTE FUNCTION handle_store_sales_mission_progress();

DROP TRIGGER IF EXISTS trg_reset_store_sale_timer_on_restock ON public.store_slots;
CREATE TRIGGER trg_reset_store_sale_timer_on_restock BEFORE UPDATE OF quantity, product_id, quality_level ON store_slots FOR EACH ROW EXECUTE FUNCTION reset_store_sale_timer_on_restock();

DROP TRIGGER IF EXISTS trg_set_warehouse_capacity_from_type ON public.warehouses;
CREATE TRIGGER trg_set_warehouse_capacity_from_type BEFORE INSERT ON warehouses FOR EACH ROW EXECUTE FUNCTION set_warehouse_capacity_from_type();

